@dataclass
class WorkspaceScope:
    """Immutable workspace scope definition."""
    root: Path
    name: str
    selected_at: float
    selected_by: str = "user"


class WorkspaceManager:
    """
    Centralized workspace scope manager.

    All filesystem access for user-selected content must go through this class.
    Provides read-only operations with strict scope enforcement.
    """

    def __init__(self, audit_manager=None):
        self._scope = None
        self._audit = audit_manager
        self._consulted_files = []
        self._max_file_size = DEFAULT_MAX_FILE_SIZE
        self._max_lines = DEFAULT_MAX_LINES
        self._max_chars = DEFAULT_MAX_CHARS
        self._enforce_readonly = True

    @property
    def active_scope(self):
        return self._scope

    @property
    def is_workspace_selected(self):
        return self._scope is not None

    def select_workspace(self, path: str, name: Optional[str] = None, selected_by: str = "user"):
        """Explicitly select a workspace root."""
        try:
            candidate = Path(path).resolve()
        except Exception as e:
            return AccessResult(
                allowed=False,
                reason=f"invalid path: {e}",
                denial_category="invalid_path"
            )

        if not candidate.exists():
            return AccessResult(
                allowed=False,
                reason=f"workspace does not exist: {candidate}",
                denial_category="not_found"
            )

        if not candidate.is_dir():
            return AccessResult(
                allowed=False,
                reason=f"workspace must be a directory: {candidate}",
                denial_category="not_directory"
            )

        workspace_name = name or candidate.name
        self._scope = WorkspaceScope(
            root=candidate,
            name=workspace_name,
            selected_at=time.time(),
            selected_by=selected_by
        )

        if self._audit:
            self._audit.log(f"Workspace selected: {workspace_name} at {candidate}")

        return AccessResult(
            allowed=True,
            path=candidate,
            workspace_relative=".",
            reason=f"Workspace '{workspace_name}' selected"
        )

    def clear_workspace(self):
        """Clear the active workspace selection."""
        if self._scope and self._audit:
            self._audit.log(f"Workspace cleared: {self._scope.name}")
        self._scope = None

    def _resolve_in_workspace(self, path: str):
        """Centralized path validation - the single source of truth for scope enforcement."""
        if not self._scope:
            return AccessResult(
                allowed=False,
                reason="no workspace selected",
                denial_category="no_workspace"
            )

        workspace_root = self._scope.root
        cleaned = path.strip().strip('"').strip("'")

        # Build the candidate path without resolving
        try:
            candidate = Path(cleaned) if Path(cleaned).is_absolute() else (workspace_root / cleaned)
        except Exception as e:
            return AccessResult(
                allowed=False,
                reason=f"path resolution failed: {e}",
                denial_category="resolution_failed"
            )

# Check each component for symlinks/junctions BEFORE resolving
        try:
            # Build path incrementally from workspace root
            check_path = workspace_root
            # Get relative parts from workspace root
            if candidate.is_absolute():
                try:
                    relative_parts = candidate.relative_to(workspace_root)
                except ValueError:
                    return AccessResult(
                        allowed=False,
                        reason=f"path escapes workspace: {path}",
                        denial_category="traversal"
                    )
            else:
                relative_parts = candidate
            for part in relative_parts.parts:
                check_path = check_path / part
                # Check if this component is a symlink/junction
                try:
                    is_link = False
                    if os.name == "nt":
                        # On Windows, check for both symlinks and junctions
                        # Junctions are reparse points with FILE_ATTRIBUTE_REPARSE_POINT (0x400)
                        # Use lstat to avoid following the junction
                        try:
                            attrs = check_path.lstat().st_file_attributes
                            if attrs & 0x400:  # FILE_ATTRIBUTE_REPARSE_POINT
                                is_link = True
                        except Exception:
                            pass
                        if not is_link:
                            is_link = check_path.is_symlink()
                    else:
                        is_link = check_path.is_symlink()

                    if is_link:
                        if os.name == "nt":
                            # For Windows junctions, is_symlink() may not detect them
                            try:
                                target = Path(os.readlink(check_path)).resolve()
                                if not target.is_relative_to(workspace_root.resolve()):
                                    return AccessResult(
                                        allowed=False,
                                        reason=f"symlink/junction escapes workspace: {check_path}",
                                        denial_category="symlink_escape"
                                    )
                            except Exception:
                                pass
                        else:
                            target = Path(os.readlink(check_path)).resolve()
                            if not target.is_relative_to(workspace_root.resolve()):
                                return AccessResult(
                                    allowed=False,
                                    reason=f"symlink escapes workspace: {check_path}",
                                    denial_category="symlink_escape"
                                )
                except Exception:
                    pass
        except Exception:
            pass

        # Now do the normal resolution and containment check
        try:
            resolved_candidate = candidate.resolve()
            relative = resolved_candidate.relative_to(workspace_root.resolve())
        except ValueError:
            return AccessResult(
                allowed=False,
                reason=f"path escapes workspace: {path}",
                denial_category="traversal"
            )
        except Exception as e:
            return AccessResult(
                allowed=False,
                reason=f"path resolution failed: {e}",
                denial_category="resolution_failed"
            )

        return AccessResult(
            allowed=True,
            path=resolved_candidate,
            workspace_relative=str(relative),
            reason="access allowed"
        )

    def _check_sensitive(self, path):
        return _matches_sensitive(path)

    def _check_size_limit(self, path):
        try:
            size = path.stat().st_size
        except Exception:
            return None

        if size > self._max_file_size:
            return {
                "allowed": False,
                "truncated": True,
                "reason": "size_limit",
                "file_size": size,
                "limit": self._max_file_size,
                "message": f"File size {size} bytes exceeds limit {self._max_file_size} bytes",
                "denial_category": "size_limit"
            }
        return None

    def _read_text_bounded(self, path):
        """Read text file with line/char limits, return content and truncation info."""
        size_check = self._check_size_limit(path)
        if size_check:
            return "", {**size_check, "allowed": False}

        if _is_binary_file(path):
            return "", {"allowed": False, "truncated": True, "reason": "binary_file", "message": "File appears to be binary", "denial_category": "binary_file"}

        lines = []
        total_chars = 0
        truncated = False

        try:
            with open(path, "r", encoding="utf-8", errors="ignore") as f:
                for line in f:
                    if len(lines) >= self._max_lines:
                        truncated = True
                        break
                    if total_chars + len(line) > self._max_chars:
                        truncated = True
                        break
                    lines.append(line)
                    total_chars += len(line)
        except Exception as e:
            return "", {"allowed": False, "truncated": True, "reason": "read_error", "error": str(e)}

        content = "".join(lines)

        if truncated:
            truncation_info = {
                "truncated": True,
                "reason": "line_or_char_limit",
                "lines_read": len(lines),
                "max_lines": self._max_lines,
                "chars_read": total_chars,
                "max_chars": self._max_chars,
                "message": f"File truncated: read {len(lines)} lines ({total_chars} chars) of max {self._max_lines} lines / {self._max_chars} chars"
            }
            return content, truncation_info

        return content, None

    def _record_access(self, workspace_relative, operation, allowed, truncation=None, denial_category="", denial_reason=""):
        record = ConsultedFileRecord(
            workspace_relative=workspace_relative,
            operation=operation,
            allowed=allowed,
            timestamp=time.time(),
            truncation=truncation,
            denial_category=denial_category,
            denial_reason=denial_reason
        )
        self._consulted_files.append(record)

        if self._audit:
            if allowed:
                self._audit.log(f"File {operation}: {workspace_relative}" + (f" [truncated]" if truncation and truncation.get("truncated") else ""))
            else:
                self._audit.log(f"File {operation} DENIED: {workspace_relative} ({denial_category}: {denial_reason})")

    def read_file(self, path):
        """Read a text file within the workspace."""
        resolved = self._resolve_in_workspace(path)
        if not resolved.allowed:
            self._record_access(path, "read", False, denial_category=resolved.denial_category, denial_reason=resolved.reason)
            return resolved

        target_path = resolved.path

        sensitive_pattern = _matches_sensitive(target_path)
        if sensitive_pattern:
            self._record_access(resolved.workspace_relative, "read", False, denial_category="sensitive_file", denial_reason=f"sensitive file pattern: {sensitive_pattern}")
            return AccessResult(allowed=False, reason=f"sensitive file denied: {sensitive_pattern}", denial_category="sensitive_file", workspace_relative=resolved.workspace_relative)

        if not target_path.exists():
            self._record_access(resolved.workspace_relative, "read", False, denial_category="not_found", denial_reason="file not found")
            return AccessResult(allowed=False, reason="file not found", denial_category="not_found", workspace_relative=resolved.workspace_relative)

        if not target_path.is_file():
            self._record_access(resolved.workspace_relative, "read", False, denial_category="not_file", denial_reason="path is not a file")
            return AccessResult(allowed=False, reason="path is not a file", denial_category="not_file", workspace_relative=resolved.workspace_relative)

        content, truncation = self._read_text_bounded(target_path)

        if isinstance(truncation, dict) and truncation.get("allowed") is False:
            self._record_access(resolved.workspace_relative, "read", False, denial_category=truncation.get("reason", "read_denied"), denial_reason=truncation.get("message", "read denied"))
            return AccessResult(allowed=False, reason=truncation.get("message", "read denied"), denial_category=truncation.get("reason", "read_denied"), workspace_relative=resolved.workspace_relative, truncation=truncation)

        self._record_access(resolved.workspace_relative, "read", True, truncation)

        return AccessResult(allowed=True, path=target_path, workspace_relative=resolved.workspace_relative, reason="read successful", truncation=truncation)

    def list_directory(self, path="."):
        resolved = self._resolve_in_workspace(path)
        if not resolved.allowed:
            self._record_access(path, "list", False, denial_category=resolved.denial_category, denial_reason=resolved.reason)
            return resolved

        target_path = resolved.path

        if not target_path.exists():
            self._record_access(resolved.workspace_relative, "list", False, denial_category="not_found", denial_reason="directory not found")
            return AccessResult(allowed=False, reason="directory not found", denial_category="not_found", workspace_relative=resolved.workspace_relative)

        if not target_path.is_dir():
            self._record_access(resolved.workspace_relative, "list", False, denial_category="not_directory", denial_reason="path is not a directory")
            return AccessResult(allowed=False, reason="path is not a directory", denial_category="not_directory", workspace_relative=resolved.workspace_relative)

        try:
            items = sorted(p.name for p in target_path.iterdir())
            self._record_access(resolved.workspace_relative, "list", True)
            return AccessResult(allowed=True, path=target_path, workspace_relative=resolved.workspace_relative, reason="list successful", truncation={"item_count": len(items)})
        except Exception as e:
            return AccessResult(allowed=False, reason=f"list failed: {e}", denial_category="list_failed", workspace_relative=resolved.workspace_relative)

    def get_workspace_info(self):
        if not self._scope:
            return None
        return {"name": self._scope.name, "root": str(self._scope.root), "selected_at": self._scope.selected_at, "selected_by": self._scope.selected_by}

    def get_consulted_files(self, clear=False):
        records = list(self._consulted_files)
        if clear:
            self._consulted_files.clear()
        return records

    def set_limits(self, max_file_size=None, max_lines=None, max_chars=None):
        if max_file_size is not None:
            self._max_file_size = max_file_size
        if max_lines is not None:
            self._max_lines = max_lines
        if max_chars is not None:
            self._max_chars = max_chars

    def set_readonly_mode(self, enforce=True):
        self._enforce_readonly = enforce


def create_workspace_manager(audit_manager=None):
    return WorkspaceManager(audit_manager=audit_manager)

