"""
--------------------------------------------
HERCULE AI Operating System
Module: Tool Matcher
Author: Heeran Paul
License: MIT
--------------------------------------------

Matches required capabilities to ranked tool/agent candidates and
executes with explicit fallback. Separation is strict:

ModelRouter -> MODEL · ToolMatcher -> TOOL · AgentManager -> AGENT ·
Orchestrator -> EXECUTION coordination.

A tool lacking required coverage is never selected; permissions are
pre-checked for ranking AND re-enforced at execution (the matcher
cannot override policy).
"""

import time
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional

from abilities.tool_health import ToolHealthMonitor, ToolPerformanceTracker
from cognition.capabilities.capability import coerce_all

_HEALTH_WEIGHT = {"READY": 1.0, "DEGRADED": 0.5, "LOADING": 0.4,
                  "AVAILABLE": 0.9, "UNAVAILABLE": 0.0, "FAILED": 0.0}


def _structured_failure_text(result: object) -> str | None:
    """Honest structured failures must trigger fallback, never count as success.

    Abilities return ``{"status": "failed", "error": ...}`` on failure;
    only ``{"status": "success", ...}`` may proceed to verification.
    """
    if not isinstance(result, dict):
        return None
    status = str(result.get("status", "")).lower()
    if status in ("failed", "error", "pending"):
        detail = result.get("error") or f"ability reported status '{status}'"
        return str(detail)[:300]
    if result.get("error") and status != "success":
        return str(result.get("error"))[:300]
    return None


class ToolMatchError(RuntimeError):
    def __init__(self, message: str, code: str = "TOOL_MATCH_ERROR", step_id: str = ""):
        super().__init__(message)
        self.code = code
        self.step_id = step_id


class _StructuredFailure(RuntimeError):
    """Internal: ability returned an honest failure dict (fallback trigger)."""


@dataclass
class ToolCandidate:
    kind: str  # tool | agent
    name: str
    covers: List[str] = field(default_factory=list)
    total: float = 0.0
    factors: Dict[str, float] = field(default_factory=dict)
    permission: Dict[str, Any] = field(default_factory=dict)

    def as_dict(self) -> Dict[str, Any]:
        return {"kind": self.kind, "name": self.name, "covers": list(self.covers),
                "total": round(self.total, 4),
                "factors": {k: round(v, 4) for k, v in self.factors.items()},
                "permission": {"allowed": self.permission.get("allowed"), "risk": self.permission.get("risk")}}


@dataclass
class ToolSelection:
    step_id: str
    selected: ToolCandidate
    candidates: List[ToolCandidate] = field(default_factory=list)
    rejected: List[Dict[str, Any]] = field(default_factory=list)
    coverage: str = "FULL"  # FULL | PARTIAL | NO_COVERAGE

    def as_dict(self) -> Dict[str, Any]:
        return {"step_id": self.step_id, "selected": self.selected.as_dict(),
                "candidates": [c.as_dict() for c in self.candidates],
                "rejected": list(self.rejected), "coverage": self.coverage}


class ToolMatcher:
    """Rank and select capability providers for plan steps."""

    def __init__(
        self,
        ability_manager=None,
        policy_manager=None,
        agent_manager=None,
        capability_registry=None,
        health_monitor: Optional[ToolHealthMonitor] = None,
        environment: str = "default",
    ):
        self.abilities = ability_manager
        self.policy = policy_manager
        self.agents = agent_manager
        self.registry = capability_registry
        self.health = health_monitor or ToolHealthMonitor()
        self.environment = environment

    # --------------------------------------------------
    def _live_providers(self, capability: str) -> List[Dict[str, Any]]:
        providers = self.registry.providers_for(capability, self.environment) if self.registry else []
        live = []
        for provider in providers:
            if provider.kind == "tool":
                status = self.health.check_tool(provider.name, self.abilities)
            else:
                status = self.health.check_agent(provider.name, self.agents)
            if status.get("state", "").upper() in ("READY", "DEGRADED"):
                live.append({"provider": provider, "health": status})
        return live

    def _permission(self, capability: str, risk: str = "LOW") -> Dict[str, Any]:
        if self.policy is None:
            return {"allowed": True, "risk": risk, "reason": "no policy bound"}
        try:
            return self.policy.evaluate(capability, {"risk": risk}, actor="tool-matcher")
        except Exception as exc:
            return {"allowed": False, "risk": risk, "reason": str(exc)[:160]}

    def match(self, step: Dict[str, Any], allow_partial: bool = False,
              preferred: Optional[Dict[str, str]] = None) -> ToolSelection:
        """Select the best healthy, policy-approved provider.

        ``preferred`` (CAPABILITY -> ability, from past successful
        experience) adds a small ranking boost to that provider only —
        it never skips health, permission, or coverage checks.
        """
        step_id = str(step.get("step_id", "step-?"))
        try:
            required = [c.value for c in coerce_all(step.get("required_capabilities", []) or [])]
        except ValueError as exc:
            raise ToolMatchError(f"step {step_id} declares unknown capability: {exc}",
                                 "UNKNOWN_CAPABILITY", step_id)
        if not required:
            raise ToolMatchError(f"step {step_id} declares no capabilities", "NO_CAPABILITY_DECLARED", step_id)
        risk = str(step.get("risk", "LOW"))

        per_cap = {cap: self._live_providers(cap) for cap in required}
        missing = [cap for cap, live in per_cap.items() if not live]
        if missing and not allow_partial:
            raise ToolMatchError(f"step {step_id} has no healthy provider for {missing}",
                                 "NO_HEALTHY_PROVIDER", step_id)

        # Candidate executors: single providers covering the most caps.
        by_executor: Dict[str, Dict[str, Any]] = {}
        for cap, live in per_cap.items():
            for entry in live:
                provider = entry["provider"]
                key = f"{provider.kind}:{provider.name}"
                slot = by_executor.setdefault(key, {"provider": provider, "covers": [], "health": entry["health"]})
                slot["covers"].append(cap)
        if not by_executor:
            raise ToolMatchError(f"step {step_id}: no coverage", "NO_CAPABILITY_COVERAGE", step_id)

        scored: List[ToolCandidate] = []
        rejected: List[Dict[str, Any]] = []
        for key, slot in by_executor.items():
            provider, covers = slot["provider"], slot["covers"]
            permission = self._permission(covers[0], risk)
            if not permission.get("allowed", True):
                rejected.append({"kind": provider.kind, "name": provider.name,
                                 "reason": f"permission denied for {covers[0]}"})
                continue
            coverage_ratio = len(covers) / len(required)
            health_w = _HEALTH_WEIGHT.get(slot["health"].get("state", "LOADING"), 0.0)
            reliability = self.health.tracker.stats_for(provider.name).success_rate()
            total = 0.55 * coverage_ratio + 0.20 * health_w + 0.15 * reliability + 0.10 * (1.0 if provider.kind == "tool" else 0.8)
            factors: Dict[str, float] = {"coverage": coverage_ratio, "health": health_w,
                                         "reliability": reliability}
            # Experience hint: prefer the previously successful provider
            # for a required capability (revalidated above; never overrides).
            if preferred:
                for cap in covers:
                    if str(preferred.get(str(cap).upper(), "")).lower() == str(provider.name).lower():
                        total += 0.15
                        factors["experience"] = 0.15
                        break
            scored.append(ToolCandidate(provider.kind, provider.name, covers, total,
                                        factors, permission))
        if not scored:
            raise ToolMatchError(f"step {step_id}: all candidates permission-denied",
                                 "PERMISSION_DENIED", step_id)
        scored.sort(key=lambda c: c.total, reverse=True)
        best = scored[0]
        coverage = "FULL" if len(best.covers) == len(required) else "PARTIAL"
        if coverage == "PARTIAL" and not allow_partial:
            raise ToolMatchError(
                f"step {step_id}: partial coverage only ({best.covers} of {required}); "
                "decompose the step or allow_partial", "PARTIAL_COVERAGE", step_id)
        return ToolSelection(step_id, best, scored, rejected, coverage)

    # --------------------------------------------------
    def execute_candidate(self, candidate: ToolCandidate, step: Dict[str, Any], payload: Optional[Dict[str, Any]] = None) -> Any:
        """Execute via AbilityManager (tools) or AgentManager (agents).

        Permissions re-enforced live by AbilityManager.execute; agents
        are pre-checked here since AgentManager has no policy gate.
        Mapping payloads merge into the agent task envelope; scalar
        payloads travel as ``{"input": payload}`` / positional input.
        """
        if candidate.kind == "agent":
            if self.agents is None:
                raise ToolMatchError(f"no agent manager for {candidate.name}", "NO_AGENT_MANAGER", candidate.name)
            for cap in candidate.covers:
                decision = self._permission(cap, str(step.get("risk", "LOW")))
                if not decision.get("allowed", True):
                    raise ToolMatchError(f"permission denied for agent {candidate.name} ({cap})",
                                         "PERMISSION_DENIED", str(step.get("step_id", "")))
            envelope: Dict[str, Any] = {"step": step}
            if isinstance(payload, dict):
                envelope.update(payload)
            elif payload is not None:
                envelope["input"] = payload
            return self.agents.execute_task(candidate.name, envelope)
        if self.abilities is None:
            raise ToolMatchError(f"no ability manager for {candidate.name}", "NO_ABILITY_MANAGER", candidate.name)
        # Canonical capabilities travel with the call so execution is
        # authorized per capability, not just per tool name.
        # Empty payloads fall back to the step description so abilities
        # receive the actual task text ({} must never reach eval/parse).
        if isinstance(payload, dict) and payload:
            task_input: Any = payload
        elif isinstance(payload, str) and payload.strip():
            task_input = payload
        else:
            task_input = step.get("description", "")
        import logging as _logging
        _logging.getLogger("HERCULE.RequestLifecycle").info(
            "CAPABILITY→SELECTED ABILITY caps=%s ability=%s step=%s",
            list(step.get("required_capabilities", []) or []), candidate.name,
            str(step.get("step_id", "")))
        return self.abilities.execute(candidate.name, task_input,
                                      capabilities=list(step.get("required_capabilities", []) or []),
                                      environment=self.environment)

    def execute_with_fallback(self, selection: ToolSelection, step: Dict[str, Any],
                              payload: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        """PRIMARY -> SECONDARY -> ... -> CLEAR FAILURE with classification.

        Destructive steps (HIGH risk, retry_destructive False) are never
        blindly retried on the same executor.
        """
        from evaluation.failures import classify_failure

        step_id = selection.step_id
        retry_policy = step.get("retry_policy", {}) or {}
        max_retries = int(retry_policy.get("max_retries", 1))
        retry_destructive = bool(retry_policy.get("retry_destructive", False))
        destructive = str(step.get("risk", "LOW")).upper() == "HIGH"
        errors: List[str] = []
        attempts = 0
        for candidate in selection.candidates:
            # Same-executor retry only when safe.
            tries = 1 + (max_retries if not (destructive and not retry_destructive) else 0)
            for _ in range(tries):
                attempts += 1
                started = time.perf_counter()
                try:
                    result = self.execute_candidate(candidate, step, payload)
                    failure_text = _structured_failure_text(result)
                    if failure_text is not None:
                        raise _StructuredFailure(failure_text)
                    latency_ms = (time.perf_counter() - started) * 1000.0
                    self.health.tracker.record(candidate.name, True, latency_ms)
                    self.health.note_success(candidate.name)
                    return {"status": "success", "executor": candidate.as_dict(),
                            "result": result, "attempts": attempts, "errors": errors}
                except Exception as exc:
                    latency_ms = (time.perf_counter() - started) * 1000.0
                    self.health.tracker.record(candidate.name, False, latency_ms)
                    self.health.note_failure(candidate.name)
                    failure = classify_failure(exc)
                    errors.append(f"{candidate.kind}:{candidate.name}: [{failure.code}] {exc}")
                    if not failure.retryable or (destructive and not retry_destructive):
                        break  # next candidate, never blind retry
        return {"status": "failed", "executor": None, "result": None,
                "attempts": attempts, "errors": errors}

from __future__ import annotations
"""
HERCULE AI Operating System
Module: Automation Ability
Author: Heeran Paul
License: MIT

Real implementation: Task automation using the automation plans system.
"""

import json
import time
from typing import Any, Dict, List, Optional

from abilities.base_ability import BaseAbility


class AutomationAbility(BaseAbility):

    def __init__(self):

        super().__init__(
            "automation",
            "Task automation: create, run, and manage automation plans",
            capability="APPLICATION_CONTROL",
            inputs={
                "operation": "create|run|list|get|approve|reject|cancel|status",
                "name": "plan name",
                "description": "plan description",
                "steps": "list of step dicts with action, target, etc.",
                "plan_id": "existing plan ID for run/get/approve/reject/cancel/status",
                "approval": "approve|reject for approval operations",
            },
            outputs={
                "plan_id": "created plan ID",
                "plan": "plan details",
                "plans": "list of plans",
                "status": "plan execution status",
                "result": "execution result",
            },
            permissions=["APPLICATION_CONTROL", "AUTOMATION"],
            environments={"default"},
            verification="plan created/executed, steps verified",
            timeout_s=300,
            risk="HIGH",
        )
        self._plan_manager = None

    def _ensure_plan_manager(self):
        if self._plan_manager is None:
            try:
                from change_proposal_manager import AutomationPlanManager, ChangeProposalManager
                from security.auditing.audit_manager import AuditManager
                audit = AuditManager()
                proposal_manager = ChangeProposalManager(audit)
                self._plan_manager = AutomationPlanManager(proposal_manager, audit)
            except ImportError:
                return None
        return self._plan_manager

    def validate_input(self, task, **kwargs):
        if isinstance(task, dict):
            op = task.get("operation", "")
            if not op:
                return "operation is required"
            if op == "create" and not task.get("name"):
                return "create requires name"
            if op in ("run", "get", "approve", "reject", "cancel", "status") and not task.get("plan_id"):
                return f"{op} requires plan_id"
            if op == "create" and not task.get("steps"):
                return "create requires steps"
            return ""
        text = str(task or "")
        if not text.strip():
            return "empty automation request"
        return ""

    def execute(self, task, context=None, **kwargs) -> Dict[str, Any]:
        if isinstance(task, dict):
            operation = str(task.get("operation", "")).lower()
        else:
            text = str(task or "").lower()
            if "create" in text and "plan" in text:
                operation = "create"
            elif "run" in text and "plan" in text:
                operation = "run"
            elif "list" in text and "plan" in text:
                operation = "list"
            else:
                operation = "list"

        pm = self._ensure_plan_manager()
        if not pm:
            return {"status": "failed", "error": "AutomationPlanManager not available"}

        try:
            if operation == "create":
                return self._create_plan(task, pm)
            elif operation == "run":
                return self._run_plan(task, pm)
            elif operation == "list":
                return self._list_plans(pm)
            elif operation == "get":
                return self._get_plan(task, pm)
            elif operation == "approve":
                return self._approve_plan(task, pm)
            elif operation == "reject":
                return self._reject_plan(task, pm)
            elif operation == "cancel":
                return self._cancel_plan(task, pm)
            elif operation == "status":
                return self._get_status(task, pm)
            else:
                return {"status": "failed", "error": f"unknown operation: {operation}"}
        except Exception as exc:
            return {"status": "failed", "error": str(exc)[:500]}

    def _create_plan(self, task: Dict[str, Any], pm) -> Dict[str, Any]:
        name = task.get("name", f"plan_{int(time.time())}")
        description = task.get("description", "")
        steps = task.get("steps", [])
        if not steps:
            return {"status": "failed", "error": "steps required for create"}
        plan = pm.create_plan(name=name, description=description, steps=steps)
        return {
            "status": "success",
            "operation": "create",
            "plan_id": plan.plan_id,
            "plan": plan.to_dict(),
        }

    def _run_plan(self, task: Dict[str, Any], pm) -> Dict[str, Any]:
        plan_id = task.get("plan_id")
        if not plan_id:
            return {"status": "failed", "error": "plan_id required for run"}
        result = pm.execute_plan(plan_id)
        return {
            "status": "success" if result.get("status") == "completed" else "failed",
            "operation": "run",
            "plan_id": plan_id,
            "result": result,
        }

    def _list_plans(self, pm) -> Dict[str, Any]:
        plans = pm.get_plans_by_workspace("")
        return {
            "status": "success",
            "operation": "list",
            "plans": [p.to_dict() for p in plans],
        }

    def _get_plan(self, task: Dict[str, Any], pm) -> Dict[str, Any]:
        plan_id = task.get("plan_id")
        if not plan_id:
            return {"status": "failed", "error": "plan_id required for get"}
        plan = pm.get_plan(plan_id)
        if not plan:
            return {"status": "failed", "error": f"plan not found: {plan_id}"}
        return {
            "status": "success",
            "operation": "get",
            "plan_id": plan_id,
            "plan": plan.to_dict(),
        }

    def _approve_plan(self, task: Dict[str, Any], pm) -> Dict[str, Any]:
        plan_id = task.get("plan_id")
        if not plan_id:
            return {"status": "failed", "error": "plan_id required for approve"}
        plan = pm.approve_plan(plan_id)
        return {
            "status": "success",
            "operation": "approve",
            "plan_id": plan_id,
            "plan": plan.to_dict(),
        }

    def _reject_plan(self, task: Dict[str, Any], pm) -> Dict[str, Any]:
        plan_id = task.get("plan_id")
        reason = task.get("reason", "rejected by user")
        if not plan_id:
            return {"status": "failed", "error": "plan_id required for reject"}
        plan = pm.reject_plan(plan_id, reason)
        return {
            "status": "success",
            "operation": "reject",
            "plan_id": plan_id,
            "plan": plan.to_dict(),
        }

    def _cancel_plan(self, task: Dict[str, Any], pm) -> Dict[str, Any]:
        plan_id = task.get("plan_id")
        if not plan_id:
            return {"status": "failed", "error": "plan_id required for cancel"}
        plan = pm.cancel_plan(plan_id)
        return {
            "status": "success",
            "operation": "cancel",
            "plan_id": plan_id,
            "plan": plan.to_dict(),
        }

    def _get_status(self, task: Dict[str, Any], pm) -> Dict[str, Any]:
        plan_id = task.get("plan_id")
        if not plan_id:
            return {"status": "failed", "error": "plan_id required for status"}
        plan = pm.get_plan(plan_id)
        if not plan:
            return {"status": "failed", "error": f"plan not found: {plan_id}"}
        return {
            "status": "success",
            "operation": "status",
            "plan_id": plan_id,
            "status": plan.status,
            "steps": [
                {"step_id": s.step_id, "action": s.action, "status": s.status}
                for s in plan.steps
            ],
        }

from __future__ import annotations
"""
HERCULE AI Operating System
Module: Browser Ability
Author: Heeran Paul
License: MIT

Real implementation: Browser automation via Playwright.
Supports navigation, screenshots, clicks, typing, extraction.
"""

import json
import os
import tempfile
import time
from typing import Any, Dict, List, Optional
from dataclasses import dataclass

from abilities.base_ability import BaseAbility


@dataclass
class BrowserAction:
    action: str  # navigate, click, type, screenshot, extract, wait, evaluate
    selector: Optional[str] = None
    url: Optional[str] = None
    text: Optional[str] = None
    value: Optional[str] = None
    timeout: int = 30000
    options: Optional[Dict[str, Any]] = None


class BrowserAbility(BaseAbility):

    def __init__(self):
        super().__init__(
            "browser",
            "Browser automation: navigate, click, type, screenshot, extract",
            capability="BROWSER_USE",
            inputs={
                "operation": "navigate|click|type|screenshot|extract|wait|evaluate",
                "url": "target URL for navigate",
                "selector": "CSS selector for click/type/extract",
                "text": "text to type",
                "value": "value for select/options",
                "timeout": "action timeout in ms (default 30000)",
                "options": "additional options dict",
            },
            outputs={
                "content": "extracted content or screenshot path",
                "url": "current page URL",
                "title": "page title",
                "cookies": "browser cookies",
            },
            permissions=["BROWSER_USE", "APPLICATION_CONTROL"],
            environments={"default"},
            verification="action completed, evidence captured",
            timeout_s=120,
            risk="MEDIUM",
        )
        self._playwright = None
        self._browser = None
        self._context = None
        self._page = None
        self._initialized = False

    def _ensure_playwright(self):
        if self._initialized:
            return True
        try:
            from playwright.sync_api import sync_playwright
            self._playwright = sync_playwright().start()
            self._browser = self._playwright.chromium.launch(headless=True)
            self._context = self._browser.new_context(
                viewport={"width": 1280, "height": 720},
                user_agent="HERCULE/1.0 BrowserAbility",
            )
            self._page = self._context.new_page()
            self._initialized = True
            return True
        except ImportError:
            return False
        except Exception as exc:
            return False

    def validate_input(self, task, **kwargs):
        if isinstance(task, dict):
            op = task.get("operation", "")
            if not op:
                return "operation is required"
            if op == "navigate" and not task.get("url"):
                return "navigate requires url"
            if op in ("click", "type", "extract") and not task.get("selector"):
                return f"{op} requires selector"
            if op == "type" and not task.get("text"):
                return "type requires text"
            return ""
        text = str(task or "")
        if not text.strip():
            return "empty browser request"
        return ""

    def execute(self, task, context=None, **kwargs) -> Dict[str, Any]:
        if not self._ensure_playwright():
            return {
                "status": "failed",
                "error": "Playwright not available. Install with: pip install playwright && playwright install chromium"
            }

        if isinstance(task, dict):
            operation = str(task.get("operation", "")).lower()
            action = BrowserAction(
                action=operation,
                selector=task.get("selector"),
                url=task.get("url"),
                text=task.get("text"),
                value=task.get("value"),
                timeout=task.get("timeout", 30000),
                options=task.get("options"),
            )
        else:
            text = str(task or "").strip()
            if text.startswith("navigate "):
                operation = "navigate"
                action = BrowserAction(action="navigate", url=text[9:].strip())
            elif text.startswith("screenshot"):
                operation = "screenshot"
                action = BrowserAction(action="screenshot")
            else:
                return {"status": "failed", "error": f"unknown operation in text: {text[:50]}"}

        try:
            result = getattr(self, f"_{action.action}")(action)
            return result
        except AttributeError:
            return {"status": "failed", "error": f"unknown operation: {action.action}"}
        except Exception as exc:
            return {"status": "failed", "error": str(exc)[:500]}

    def _navigate(self, action: BrowserAction) -> Dict[str, Any]:
        if not action.url:
            return {"status": "failed", "error": "navigate requires url"}
        try:
            response = self._page.goto(action.url, timeout=action.timeout, wait_until="domcontentloaded")
            return {
                "status": "success",
                "operation": "navigate",
                "url": self._page.url,
                "title": self._page.title(),
                "status_code": response.status if response else 0,
            }
        except Exception as exc:
            return {"status": "failed", "error": str(exc)[:300]}

    def _click(self, action: BrowserAction) -> Dict[str, Any]:
        if not action.selector:
            return {"status": "failed", "error": "click requires selector"}
        try:
            self._page.click(action.selector, timeout=action.timeout)
            return {
                "status": "success",
                "operation": "click",
                "selector": action.selector,
                "url": self._page.url,
            }
        except Exception as exc:
            return {"status": "failed", "error": str(exc)[:300]}

    def _type(self, action: BrowserAction) -> Dict[str, Any]:
        if not action.selector:
            return {"status": "failed", "error": "type requires selector"}
        if not action.text:
            return {"status": "failed", "error": "type requires text"}
        try:
            self._page.fill(action.selector, action.text, timeout=action.timeout)
            return {
                "status": "success",
                "operation": "type",
                "selector": action.selector,
                "text": action.text,
                "url": self._page.url,
            }
        except Exception as exc:
            return {"status": "failed", "error": str(exc)[:300]}

    def _screenshot(self, action: BrowserAction) -> Dict[str, Any]:
        try:
            path = tempfile.mktemp(suffix=".png")
            self._page.screenshot(path=path, full_page=action.options.get("full_page", True) if action.options else True)
            with open(path, "rb") as f:
                import base64
                encoded = base64.b64encode(f.read()).decode()
            os.unlink(path)
            return {
                "status": "success",
                "operation": "screenshot",
                "content": encoded,
                "format": "base64_png",
                "url": self._page.url,
            }
        except Exception as exc:
            return {"status": "failed", "error": str(exc)[:300]}

    def _extract(self, action: BrowserAction) -> Dict[str, Any]:
        if not action.selector:
            return {"status": "failed", "error": "extract requires selector"}
        try:
            elements = self._page.query_selector_all(action.selector)
            results = []
            for el in elements:
                text = el.inner_text()
                html = el.inner_html()
                results.append({"text": text, "html": html})
            return {
                "status": "success",
                "operation": "extract",
                "selector": action.selector,
                "count": len(results),
                "results": results,
                "url": self._page.url,
            }
        except Exception as exc:
            return {"status": "failed", "error": str(exc)[:300]}

    def _wait(self, action: BrowserAction) -> Dict[str, Any]:
        try:
            if action.selector:
                self._page.wait_for_selector(action.selector, timeout=action.timeout)
                return {"status": "success", "operation": "wait", "selector": action.selector}
            elif action.url:
                self._page.wait_for_url(action.url, timeout=action.timeout)
                return {"status": "success", "operation": "wait", "url": action.url}
            else:
                time.sleep(action.timeout / 1000)
                return {"status": "success", "operation": "wait", "duration_ms": action.timeout}
        except Exception as exc:
            return {"status": "failed", "error": str(exc)[:300]}

    def _evaluate(self, action: BrowserAction) -> Dict[str, Any]:
        try:
            script = action.options.get("script") if action.options else action.text
            if not script:
                return {"status": "failed", "error": "evaluate requires script in options or text"}
            result = self._page.evaluate(script)
            return {
                "status": "success",
                "operation": "evaluate",
                "result": result,
                "url": self._page.url,
            }
        except Exception as exc:
            return {"status": "failed", "error": str(exc)[:300]}

    def close(self):
        if self._page:
            self._page.close()
        if self._context:
            self._context.close()
        if self._browser:
            self._browser.close()
        if self._playwright:
            self._playwright.stop()
        self._initialized = False

