        self._workspace_manager = None

    def _ensure_workspace(self):
        if self._workspace_manager is None and create_workspace_manager:
            try:
                from security.auditing.audit_manager import AuditManager
                audit = AuditManager()
                self._workspace_manager = create_workspace_manager(audit)
            except Exception:
                pass
        return self._workspace_manager

    def validate_input(self, task, **kwargs):
        if isinstance(task, dict):
            op = task.get("operation", "generate")
            if op in ("edit", "analyze") and not task.get("file"):
                return f"operation '{op}' requires 'file' parameter"
            if op == "generate" and not (task.get("prompt") or task.get("code")):
                return "generate operation requires 'prompt' or 'code'"
            return ""
        text = str(task or "")
        if not text.strip():
            return "empty coding request"
        return ""

    def execute(self, task, context=None, **kwargs):
        if isinstance(task, dict):
            operation = str(task.get("operation", "generate")).lower()
            code = task.get("code", "")
            file_path = task.get("file", "")
            language = str(task.get("language", "python")).lower()
            prompt = task.get("prompt", "")
        else:
            operation = "generate"
            prompt = str(task)
            code = ""
            file_path = ""
            language = "python"

        try:
            if operation == "generate":
                return self._generate(prompt, language, code, **kwargs)
            elif operation == "edit":
                return self._edit(file_path, code, **kwargs)
            elif operation == "analyze":
                return self._analyze(file_path, code, language, **kwargs)
            elif operation == "execute":
                return self._execute(code, language, **kwargs)
            elif operation == "lint":
                return self._lint(code, language, **kwargs)
            elif operation == "test":
                return self._test(file_path, code, language, **kwargs)
            else:
                return {"status": "failed", "error": f"unknown operation: {operation}"}
        except Exception as exc:
            return {"status": "failed", "error": str(exc)[:500]}

    def _generate(self, prompt: str, language: str, existing_code: str, **kwargs) -> Dict[str, Any]:
        templates = {
            "python": self._python_template,
            "javascript": self._javascript_template,
            "typescript": self._typescript_template,
            "rust": self._rust_template,
            "go": self._go_template,
        }
        template_fn = templates.get(language, self._python_template)
        generated = template_fn(prompt, existing_code)
        return {
            "status": "success",
            "operation": "generate",
            "language": language,
            "code": generated,
            "prompt": prompt,
        }

    def _python_template(self, prompt: str, existing: str) -> str:
        if existing:
            return f"{existing}\n\n# Generated from: {prompt}\ndef generated_function():\n    pass"
        return textwrap.dedent(f"""\
            # Generated from: {prompt}
            def main():
                \"\"\"{prompt}\"\"\"
                pass

            if __name__ == "__main__":
                main()
            """)

    def _javascript_template(self, prompt: str, existing: str) -> str:
        if existing:
            return f"{existing}\n\n// Generated from: {prompt}\nfunction generatedFunction() {{\n    // TODO\n}}"
        return f"// Generated from: {prompt}\nfunction main() {{\n    // {prompt}\n}}\n\nmain();"

    def _typescript_template(self, prompt: str, existing: str) -> str:
        if existing:
            return f"{existing}\n\n// Generated from: {prompt}\nfunction generatedFunction(): void {{\n    // TODO\n}}"
        return f"// Generated from: {prompt}\nfunction main(): void {{\n    // {prompt}\n}}\n\nmain();"

    def _rust_template(self, prompt: str, existing: str) -> str:
        if existing:
            return f"{existing}\n\n// Generated from: {prompt}\nfn generated_function() {{\n    // TODO\n}}"
        return f"// Generated from: {prompt}\nfn main() {{\n    // {prompt}\n}}"

    def _go_template(self, prompt: str, existing: str) -> str:
        if existing:
            return f"{existing}\n\n// Generated from: {prompt}\nfunc generatedFunction() {{\n    // TODO\n}}"
        return f"// Generated from: {prompt}\npackage main\n\nfunc main() {{\n    // {prompt}\n}}"

    def _edit(self, file_path: str, new_code: str, **kwargs) -> Dict[str, Any]:
        if not file_path:
            return {"status": "failed", "error": "file path required for edit"}
        wm = self._ensure_workspace()
        if not wm:
            return {"status": "failed", "error": "workspace manager not available"}
        try:
            result = wm.read_file(file_path)
            if not result.allowed:
                return {"status": "failed", "error": result.reason, "denial_category": result.denial_category}
            old_content = result.path.read_text(encoding="utf-8")
            write_result = wm.write_file(file_path, new_code)
            if not write_result.allowed:
                return {"status": "failed", "error": write_result.reason, "denial_category": write_result.denial_category}
            return {
                "status": "success",
                "operation": "edit",
                "file": file_path,
                "old_content": old_content,
                "new_content": new_code,
            }
        except Exception as exc:
            return {"status": "failed", "error": str(exc)[:300]}

    def _analyze(self, file_path: str, code: str, language: str, **kwargs) -> Dict[str, Any]:
        target = code
        if not target and file_path:
            wm = self._ensure_workspace()
            if wm:
                result = wm.read_file(file_path)
                if result.allowed:
                    target = result.path.read_text(encoding="utf-8")
        if not target:
            return {"status": "failed", "error": "no code to analyze"}
        if language == "python":
            return self._analyze_python(target, file_path)
        return {"status": "success", "operation": "analyze", "language": language, "message": "analysis not implemented for this language"}

    def _analyze_python(self, code: str, file_path: str) -> Dict[str, Any]:
        try:
            tree = ast.parse(code)
            issues = []
            functions = []
            classes = []
            imports = []
            for node in ast.walk(tree):
                if isinstance(node, ast.FunctionDef):
                    functions.append({"name": node.name, "line": node.lineno, "args": [a.arg for a in node.args.args]})
                elif isinstance(node, ast.ClassDef):
                    classes.append({"name": node.name, "line": node.lineno, "methods": [n.name for n in node.body if isinstance(n, ast.FunctionDef)]})
                elif isinstance(node, (ast.Import, ast.ImportFrom)):
                    for alias in node.names:
                        imports.append({"name": alias.name, "line": node.lineno})
                elif isinstance(node, ast.Call) and hasattr(node.func, 'id') and node.func.id == 'eval':
                    issues.append({"type": "security", "message": "eval() usage detected", "line": getattr(node, 'lineno', 0)})
            return {
                "status": "success",
                "operation": "analyze",
                "file": file_path,
                "functions": functions,
                "classes": classes,
                "imports": imports,
                "issues": issues,
                "lines": len(code.splitlines()),
                "chars": len(code),
            }
        except SyntaxError as exc:
            return {"status": "failed", "error": f"syntax error: {exc.msg} at line {exc.lineno}"}

    def _execute(self, code: str, language: str, **kwargs) -> Dict[str, Any]:
        if not code:
            return {"status": "failed", "error": "no code to execute"}
        if language == "python":
            return self._execute_python(code, **kwargs)
        elif language in ("javascript", "typescript"):
            return self._execute_node(code, **kwargs)
        else:
            return {"status": "failed", "error": f"execution not supported for {language}"}

    def _execute_python(self, code: str, **kwargs) -> Dict[str, Any]:
        with tempfile.NamedTemporaryFile(mode='w', suffix='.py', delete=False) as f:
            f.write(code)
            temp_path = f.name
        try:
            result = subprocess.run(
                [sys.executable, temp_path],
                capture_output=True,
                text=True,
                timeout=kwargs.get("timeout", 30),
            )
            return {
                "status": "success" if result.returncode == 0 else "failed",
                "operation": "execute",
                "language": "python",
                "stdout": result.stdout,
                "stderr": result.stderr,
                "returncode": result.returncode,
            }
        except subprocess.TimeoutExpired:
            return {"status": "failed", "error": "execution timeout"}
        except Exception as exc:
            return {"status": "failed", "error": str(exc)}
        finally:
            Path(temp_path).unlink(missing_ok=True)

    def _execute_node(self, code: str, **kwargs) -> Dict[str, Any]:
        with tempfile.NamedTemporaryFile(mode='w', suffix='.js', delete=False) as f:
            f.write(code)
            temp_path = f.name
        try:
            result = subprocess.run(
                ["node", temp_path],
                capture_output=True,
                text=True,
                timeout=kwargs.get("timeout", 30),
            )
            return {
                "status": "success" if result.returncode == 0 else "failed",
                "operation": "execute",
                "language": "javascript",
                "stdout": result.stdout,
                "stderr": result.stderr,
                "returncode": result.returncode,
            }
        except FileNotFoundError:
            return {"status": "failed", "error": "node not installed"}
        except subprocess.TimeoutExpired:
            return {"status": "failed", "error": "execution timeout"}
        except Exception as exc:
            return {"status": "failed", "error": str(exc)}
        finally:
            Path(temp_path).unlink(missing_ok=True)

    def _lint(self, code: str, language: str, **kwargs) -> Dict[str, Any]:
        if not code:
            return {"status": "failed", "error": "no code to lint"}
        if language == "python":
            try:
                ast.parse(code)
                return {"status": "success", "operation": "lint", "language": "python", "issues": []}
            except SyntaxError as exc:
                return {"status": "success", "operation": "lint", "language": "python", "issues": [
                    {"type": "syntax", "message": exc.msg, "line": exc.lineno}
                ]}
        return {"status": "success", "operation": "lint", "language": language, "issues": [], "message": "lint not implemented for this language"}

    def _test(self, file_path: str, code: str, language: str, **kwargs) -> Dict[str, Any]:
        if language == "python":
            test_code = code
            if file_path and not test_code:
                wm = self._ensure_workspace()
                if wm:
                    result = wm.read_file(file_path)
                    if result.allowed:
                        test_code = result.path.read_text(encoding="utf-8")
            if not test_code:
                return {"status": "failed", "error": "no code to test"}
            with tempfile.NamedTemporaryFile(mode='w', suffix='_test.py', delete=False) as f:
                f.write(test_code)
                temp_path = f.name
            try:
                result = subprocess.run(
                    [sys.executable, "-m", "pytest", temp_path, "-v", "--tb=short"],
                    capture_output=True,
                    text=True,
                    timeout=kwargs.get("timeout", 60),
                )
                return {
                    "status": "success" if result.returncode == 0 else "failed",
                    "operation": "test",
                    "language": "python",
                    "stdout": result.stdout,
                    "stderr": result.stderr,
                    "returncode": result.returncode,
                }
            except Exception as exc:
                return {"status": "failed", "error": str(exc)}
            finally:
                Path(temp_path).unlink(missing_ok=True)
        return {"status": "failed", "error": f"testing not supported for {language}"}

from __future__ import annotations
"""
--------------------------------------------
HERCULE AI Operating System
Module: Computer Ability (v1.2, controlled)
Author: Heeran Paul
License: MIT
--------------------------------------------

Single-action computer control inside the existing ability pipeline
(capability -> permission -> execution -> verification). Structured
proposals only: dict tasks (or inputs) carrying explicit action
fields. Coordinates are validated against the real screen and
sensitive actions require a fresh grounding observation; HIGH-risk
actions additionally require a consumed human approval. The ability
never clicks, types, or launches anything the policy has not allowed.
"""

import re as _re
import time as _time

from abilities.base_ability import BaseAbility
from computer.actions import ComputerAction, describe_action_kind, parse_action


def _shared_controller():
    from computer.controller import shared_controller

    return shared_controller()


class ComputerAbility(BaseAbility):

    def __init__(self, controller=None):

        super().__init__(
            "computer",
            "Controlled desktop interaction: pointer, click, type, keys, apps (explicit only)",
            capability="APPLICATION_CONTROL",
            inputs={"action": "screenshot|move|click|double_click|right_click|scroll|type|press_key|hotkey|wait|open_app",
                    "target": "visual target description",
                    "coordinates": "[x, y] validated screen pixels",
                    "text": "text for type", "key": "key for press_key",
                    "hotkey": "key list", "app": "allowlisted application",
                    "approval_id": "approved request id (HIGH-risk)"},
            outputs={"action": "executed action", "verification": "evidence"},
            permissions=["APPLICATION_CONTROL"],
            environments={"default"},
            verification="dispatch receipt + outcome evidence per strategy",
            timeout_s=60,
            risk="MEDIUM",
        )
        self._controller = controller

    def _controller_or_shared(self):
        return self._controller if self._controller is not None else _shared_controller()

    def validate_input(self, task, **kwargs):
        if isinstance(task, dict):
            if not str(task.get("action", "") or "").strip() and not kwargs.get("action"):
                # Natural-language step text may still name a computer action.
                kind = describe_action_kind(str(task.get("description", "")))
                if not kind:
                    return "computer action needs an action field or action language"
                return ""
            return ""
        text = str(task or "")
        if not text.strip() and not kwargs.get("action"):
            return "empty computer request"
        return ""

    def execute(self, task="", context=None, **kwargs):
        from computer.policy import ApprovalStore  # noqa: F401 (explicit policy path)

        proposal: dict = {}
        text = ""
        approval_id = str(kwargs.pop("approval_id", "") or "")
        if isinstance(task, dict):
            text = str(task.get("description", task.get("goal", "")))
            for key in ("action", "target", "coordinates", "coordinate",
                        "text", "key", "hotkey", "app", "application",
                        "amount", "seconds", "reason", "observed_at",
                        "approval_id"):
                if task.get(key) not in (None, ""):
                    proposal[key] = task[key]
            inputs = task.get("inputs") if isinstance(task.get("inputs"), dict) else {}
            for key, value in (inputs or {}).items():
                if key not in proposal and value not in (None, ""):
                    proposal[key] = value
        else:
            text = str(task or "")
        for key in ("action", "target", "coordinates", "text", "key",
                    "hotkey", "app", "amount", "seconds", "reason",
                    "observed_at"):
            if key not in proposal and kwargs.get(key) not in (None, ""):
                proposal[key] = kwargs[key]
        if "app" not in proposal and proposal.get("application"):
            proposal["app"] = proposal.pop("application")
        if not str(proposal.get("action", "") or "").strip():
            kind = describe_action_kind(text)
            if not kind:
                return {"status": "failed",
                        "error": "no computer action specified"}
            proposal["action"] = kind
            if kind == "type" and not str(proposal.get("text", "") or "").strip():
                quoted = _re.search(r"['\"]([^'\"]+)['\"]", text)
                proposal["text"] = (quoted.group(1) if quoted else "")
            if kind == "open_app" and not proposal.get("app"):
                match = _re.search(r"(?i)open\s+(?:the\s+)?([a-z0-9 ]+)", text)
                proposal["app"] = (match.group(1).strip().lower() if match else "")
        if not approval_id:
            approval_id = str(proposal.pop("approval_id", "") or "")
        controller = self._controller_or_shared()
        if not controller.config.enabled:
            return {"status": "failed", "action": proposal.get("action", ""),
                    "error": "computer control is disabled (opt-in: HERCULE_COMPUTER_ENABLED=1)"}
        # Fresh grounding for sensitive actions: attach the controller's
        # latest observation timestamp when the caller gave none.
        try:
            probe = parse_action(dict(proposal))
        except Exception as error:
            code = getattr(error, "code", "INVALID_ACTION")
            return {"status": "failed", "error": str(error)[:300], "code": code}
        if probe.risk != "LOW" and not float(proposal.get("observed_at", 0.0) or 0.0):
            last = getattr(controller, "_last_observation", None) or {}
            try:
                age = _time.time() - float(last.get("at", 0))
                if age <= controller.config.observation_max_age_s:
                    proposal["observed_at"] = float(last.get("at", 0))
            except Exception:
                pass
        # Consume a matching human approval when the caller references none
        # explicitly (approve-then-retry UX: approve in UI, re-issue command).
        if not approval_id and probe.risk == "HIGH":
            try:
                candidate = dict(proposal)
                approval_id = controller.approvals.consume_approved(
                    {**probe.as_dict(), **{k: v for k, v in candidate.items()
                                           if k in probe.as_dict()}})
            except Exception:
                approval_id = ""
        try:
            screen = controller.adapter.screen_size()
        except Exception as error:
            return {"status": "failed", "action": probe.action,
                    "error": f"screen unavailable: {error}"[:300]}
        result = controller.run_action(proposal, approval_id=approval_id,
                                       screen=screen)
        if isinstance(result, dict) and result.get("status") == "completed":
            return {"status": "success", "action": result.get("action", {}),
                    "verification": result.get("verification", {}),
                    "content": f"computer {probe.action} verified"}
        error = str((result or {}).get("error", "computer action failed"))[:300]
        out = {"status": "failed", "action": (result or {}).get("action", {}),
               "error": error}
        for key in ("code", "verification"):
            if (result or {}).get(key) is not None:
                out[key] = result[key]
        return out

from __future__ import annotations
"""
HERCULE AI Operating System
Module: Database Ability
Author: Heeran Paul
License: MIT

Real implementation: SQLite, PostgreSQL, MySQL database operations.
"""

import json
import os
import sqlite3
import tempfile
from pathlib import Path
from typing import Any, Dict, List, Optional
from dataclasses import dataclass

from abilities.base_ability import BaseAbility


@dataclass
class DBConfig:
    type: str = "sqlite"  # sqlite, postgresql, mysql
    host: str = ""
    port: int = 0
    database: str = ""
    user: str = ""
    password: str = ""
    path: str = ""  # for sqlite


class DatabaseAbility(BaseAbility):

    def __init__(self):
        super().__init__(
            "database",
            "Database operations: query, insert, update, delete, schema",
            capability="DATABASE_READ",
            inputs={
                "operation": "query|execute|schema|tables|connect|disconnect",
                "config": "database connection config",
                "sql": "SQL query/statement",
                "params": "parameters for parameterized queries",
                "fetch": "one|all|many (default: all)",
            },
            outputs={
                "rows": "query results",
                "rowcount": "affected rows",
                "schema": "table schema info",
                "tables": "list of tables",
            },
            permissions=["DATABASE_READ", "DATABASE_WRITE"],
            environments={"default"},
            verification="query executed, results returned",
            timeout_s=60,
            risk="HIGH",
        )
        self._connections: Dict[str, Any] = {}
        self._default_config: Optional[DBConfig] = None

    def validate_input(self, task, **kwargs):
        if isinstance(task, dict):
            op = task.get("operation", "")
            if not op:
                return "operation is required"
            if op in ("query", "execute") and not task.get("sql"):
                return f"{op} requires sql"
            if op == "connect" and not task.get("config"):
                return "connect requires config"
            return ""
        text = str(task or "")
        if not text.strip():
            return "empty database request"
        return ""

    def execute(self, task, context=None, **kwargs) -> Dict[str, Any]:
        if isinstance(task, dict):
            operation = str(task.get("operation", "")).lower()
            config = task.get("config")
            sql = task.get("sql", "")
            params = task.get("params") or []
            fetch = task.get("fetch", "all")
        else:
            text = str(task or "").strip()
            if text.upper().startswith("SELECT") or text.upper().startswith("WITH"):
                operation = "query"
                sql = text
                params = []
                fetch = "all"
                config = None
            else:
                return {"status": "failed", "error": "specify operation and sql"}

        try:
            if operation == "connect":
                return self._connect(config)
            elif operation == "disconnect":
                return self._disconnect(config.get("name", "default") if config else "default")
            elif operation == "query":
                return self._query(sql, params, fetch, config)
            elif operation == "execute":
                return self._execute(sql, params, config)
            elif operation == "schema":
                return self._schema(config)
            elif operation == "tables":
                return self._tables(config)
            else:
                return {"status": "failed", "error": f"unknown operation: {operation}"}
        except Exception as exc:
            return {"status": "failed", "error": str(exc)[:500]}

    def _get_connection(self, config: Optional[DBConfig]) -> Any:
        if not config:
            if not self._default_config:
                self._default_config = DBConfig(type="sqlite", path=":memory:")
            config = self._default_config

        key = f"{config.type}://{config.host}:{config.port}/{config.database}" if config.type != "sqlite" else f"sqlite://{config.path}"
        if key in self._connections:
            conn = self._connections[key]
            try:
                conn.execute("SELECT 1")
                return conn
            except Exception:
                pass  # connection dead, recreate

        if config.type == "sqlite":
            path = config.path or ":memory:"
            if path != ":memory:":
                Path(path).parent.mkdir(parents=True, exist_ok=True)
            conn = sqlite3.connect(path, check_same_thread=False)
            conn.row_factory = sqlite3.Row
        elif config.type == "postgresql":
            try:
                import psycopg2
                conn = psycopg2.connect(
                    host=config.host, port=config.port,
                    database=config.database, user=config.user, password=config.password
                )
            except ImportError:
                raise RuntimeError("psycopg2 not installed")
        elif config.type == "mysql":
            try:
                import pymysql
                conn = pymysql.connect(
                    host=config.host, port=config.port,
                    database=config.database, user=config.user, password=config.password
                )
            except ImportError:
                raise RuntimeError("pymysql not installed")
        else:
            raise ValueError(f"unsupported database type: {config.type}")

        self._connections[key] = conn
        return conn

    def _connect(self, config: Dict[str, Any]) -> Dict[str, Any]:
        db_config = DBConfig(
            type=config.get("type", "sqlite"),
            host=config.get("host", ""),
            port=config.get("port", 0),
            database=config.get("database", ""),
            user=config.get("user", ""),
            password=config.get("password", ""),
            path=config.get("path", ""),
        )
        name = config.get("name", "default")
        key = f"{db_config.type}://{db_config.host}:{db_config.port}/{db_config.database}" if db_config.type != "sqlite" else f"sqlite://{db_config.path}"
        try:
            conn = self._get_connection(db_config)
            conn.execute("SELECT 1")
            self._connections[key] = conn
            return {"status": "success", "operation": "connect", "name": name, "type": db_config.type}
        except Exception as exc:
            return {"status": "failed", "error": str(exc)[:300]}

    def _disconnect(self, name: str) -> Dict[str, Any]:
        for key, conn in list(self._connections.items()):
            if name in key:
                try:
                    conn.close()
                except Exception:
                    pass
                del self._connections[key]
                return {"status": "success", "operation": "disconnect", "name": name}
        return {"status": "failed", "error": f"no connection named: {name}"}

    def _query(self, sql: str, params: List[Any], fetch: str, config: Optional[Dict[str, Any]]) -> Dict[str, Any]:
        db_config = None
        if config:
            db_config = DBConfig(
                type=config.get("type", "sqlite"),
                host=config.get("host", ""),
                port=config.get("port", 0),
                database=config.get("database", ""),
                user=config.get("user", ""),
                password=config.get("password", ""),
                path=config.get("path", ""),
            )
        conn = self._get_connection(db_config)
        cursor = conn.cursor()
        try:
            cursor.execute(sql, params)
            if fetch == "one":
                row = cursor.fetchone()
                rows = [dict(row)] if row else []
            elif fetch == "many":
                rows = [dict(r) for r in cursor.fetchmany(100)]
            else:
                rows = [dict(r) for r in cursor.fetchall()]
            return {
                "status": "success",
                "operation": "query",
                "rows": rows,
                "rowcount": len(rows),
            }
        finally:
            cursor.close()

    def _execute(self, sql: str, params: List[Any], config: Optional[Dict[str, Any]]) -> Dict[str, Any]:
        db_config = None
        if config:
            db_config = DBConfig(
                type=config.get("type", "sqlite"),
