        cursor = conn.cursor()
        try:
            if db_config and db_config.type == "sqlite":
                cursor.execute("SELECT name, sql FROM sqlite_master WHERE type='table'")
                tables = cursor.fetchall()
                schema = {}
                for table in tables:
                    name = table[0]
