import json
import os
import platform
import psutil
import socket
import subprocess
import sys
import tempfile
import time
from pathlib import Path
from typing import Any, Dict, List, Optional

from abilities.base_ability import BaseAbility


class DiagnosticsAbility(BaseAbility):

    def __init__(self):
        super().__init__(
            "diagnostics",
            "System diagnostics: health, performance, resources, network",
            capability="SYSTEM_OBSERVE",
            inputs={
                "operation": "health|resources|processes|network|disk|services|benchmarks|report",
                "target": "specific process/service name (optional)",
                "duration": "monitoring duration in seconds (default: 5)",
                "interval": "sampling interval in seconds (default: 1)",
            },
            outputs={
                "cpu": "CPU usage, cores, frequency",
                "memory": "RAM usage, swap, available",
                "disk": "disk usage, I/O stats",
                "network": "interfaces, connections, bandwidth",
                "processes": "top processes by CPU/memory",
                "services": "system services status",
                "benchmarks": "performance benchmarks",
            },
            permissions=["SYSTEM_OBSERVE"],
            environments={"default"},
            verification="metrics collected, valid ranges",
            timeout_s=60,
            risk="LOW",
        )

    def validate_input(self, task, **kwargs):
        if isinstance(task, dict):
            op = task.get("operation", "health")
            if op not in ("health", "resources", "processes", "network", "disk", "services", "benchmarks", "report"):
                return f"unknown operation: {op}"
            return ""
        text = str(task or "")
        if not text.strip():
            return "empty diagnostics request"
        return ""

    def execute(self, task, context=None, **kwargs) -> Dict[str, Any]:
        if isinstance(task, dict):
            operation = str(task.get("operation", "health")).lower()
            target = task.get("target")
            duration = int(task.get("duration", 5))
            interval = float(task.get("interval", 1))
        else:
            text = str(task or "").lower()
            if "benchmark" in text:
                operation = "benchmarks"
            elif "process" in text:
                operation = "processes"
            elif "network" in text:
                operation = "network"
            elif "disk" in text:
                operation = "disk"
            elif "service" in text:
                operation = "services"
            elif "resource" in text:
                operation = "resources"
            else:
                operation = "health"
            target = None
            duration = 5
            interval = 1

        try:
            if operation == "health":
                return self._health_check()
            elif operation == "resources":
                return self._resources(duration, interval)
            elif operation == "processes":
                return self._processes(target)
            elif operation == "network":
                return self._network()
            elif operation == "disk":
                return self._disk()
            elif operation == "services":
                return self._services(target)
            elif operation == "benchmarks":
                return self._benchmarks()
            elif operation == "report":
                return self._full_report()
            else:
                return {"status": "failed", "error": f"unknown operation: {operation}"}
        except Exception as exc:
            return {"status": "failed", "error": str(exc)[:500]}

    def _health_check(self) -> Dict[str, Any]:
        cpu = psutil.cpu_percent(interval=0.5)
        mem = psutil.virtual_memory()
        disk = psutil.disk_usage("/")
        issues = []
        if cpu > 90:
            issues.append(f"High CPU usage: {cpu}%")
        if mem.percent > 90:
            issues.append(f"High memory usage: {mem.percent}%")
        if disk.percent > 90:
            issues.append(f"High disk usage: {disk.percent}%")
        return {
            "status": "success",
            "operation": "health",
            "healthy": len(issues) == 0,
            "issues": issues,
            "cpu_percent": cpu,
            "memory_percent": mem.percent,
            "disk_percent": disk.percent,
            "timestamp": time.time(),
        }

    def _resources(self, duration: int, interval: float) -> Dict[str, Any]:
        samples = []
        end = time.time() + duration
        while time.time() < end:
            cpu = psutil.cpu_percent(interval=None)
            mem = psutil.virtual_memory()
            disk = psutil.disk_io_counters()
            net = psutil.net_io_counters()
            samples.append({
                "timestamp": time.time(),
                "cpu_percent": cpu,
                "memory_percent": mem.percent,
                "memory_available_gb": mem.available / (1024**3),
                "disk_read_mb": disk.read_bytes / (1024**2) if disk else 0,
                "disk_write_mb": disk.write_bytes / (1024**2) if disk else 0,
                "net_sent_mb": net.bytes_sent / (1024**2) if net else 0,
                "net_recv_mb": net.bytes_recv / (1024**2) if net else 0,
            })
            time.sleep(interval)
        return {
            "status": "success",
            "operation": "resources",
            "samples": samples,
            "summary": {
                "avg_cpu": sum(s["cpu_percent"] for s in samples) / len(samples),
                "avg_memory": sum(s["memory_percent"] for s in samples) / len(samples),
                "duration": duration,
            },
        }

    def _processes(self, target: Optional[str]) -> Dict[str, Any]:
        procs = []
        for proc in psutil.process_iter(["pid", "name", "cpu_percent", "memory_percent", "username", "cmdline"]):
            try:
                info = proc.info
                if target and target.lower() not in (info["name"] or "").lower() and target.lower() not in " ".join(info["cmdline"] or []).lower():
                    continue
                procs.append({
                    "pid": info["pid"],
                    "name": info["name"],
                    "cpu_percent": info["cpu_percent"],
                    "memory_percent": info["memory_percent"],
                    "username": info["username"],
                    "cmdline": " ".join(info["cmdline"] or [])[:200],
                })
            except (psutil.NoSuchProcess, psutil.AccessDenied):
                pass
        procs.sort(key=lambda x: x["cpu_percent"], reverse=True)
        return {
            "status": "success",
            "operation": "processes",
            "count": len(procs),
            "processes": procs[:20],
        }

    def _network(self) -> Dict[str, Any]:
        interfaces = psutil.net_if_addrs()
        stats = psutil.net_if_stats()
        connections = psutil.net_connections(kind="inet")
        io = psutil.net_io_counters()
        return {
            "status": "success",
            "operation": "network",
            "interfaces": {
                name: [{"address": addr.address, "netmask": addr.netmask, "family": str(addr.family)} for addr in addrs]
                for name, addrs in interfaces.items()
            },
            "stats": {name: {"isup": s.isup, "speed": s.speed, "mtu": s.mtu} for name, s in stats.items()},
            "connections": [
                {"fd": c.fd, "family": str(c.family), "type": str(c.type), "laddr": f"{c.laddr.ip}:{c.laddr.port}" if c.laddr else "",
                 "raddr": f"{c.raddr.ip}:{c.raddr.port}" if c.raddr else "", "status": c.status}
                for c in connections[:50]
            ],
            "io": {"bytes_sent": io.bytes_sent, "bytes_recv": io.bytes_recv, "packets_sent": io.packets_sent, "packets_recv": io.packets_recv} if io else {},
        }

    def _disk(self) -> Dict[str, Any]:
        partitions = psutil.disk_partitions()
        usage = {}
        for p in partitions:
            try:
                u = psutil.disk_usage(p.mountpoint)
                usage[p.mountpoint] = {"total_gb": u.total / (1024**3), "used_gb": u.used / (1024**3), "free_gb": u.free / (1024**3), "percent": u.percent}
            except PermissionError:
                pass
        io = psutil.disk_io_counters()
        return {
            "status": "success",
            "operation": "disk",
            "partitions": usage,
            "io": {"read_mb": io.read_bytes / (1024**2), "write_mb": io.write_bytes / (1024**2), "read_count": io.read_count, "write_count": io.write_count} if io else {},
        }

    def _services(self, target: Optional[str]) -> Dict[str, Any]:
        services = []
        try:
            if sys.platform == "win32":
                result = subprocess.run(["sc", "query", "state= all"], capture_output=True, text=True, timeout=10)
                for line in result.stdout.splitlines():
                    if "SERVICE_NAME:" in line:
                        name = line.split(":", 1)[1].strip()
                        if not target or target.lower() in name.lower():
                            services.append({"name": name, "platform": "windows"})
            else:
                result = subprocess.run(["systemctl", "list-units", "--type=service", "--no-legend"], capture_output=True, text=True, timeout=10)
                for line in result.stdout.splitlines():
                    parts = line.split()
                    if len(parts) >= 4:
                        name = parts[0]
                        if not target or target.lower() in name.lower():
                            services.append({"name": name, "status": parts[2], "sub": parts[3], "platform": "linux"})
        except Exception:
            pass
        return {"status": "success", "operation": "services", "services": services[:50]}

    def _benchmarks(self) -> Dict[str, Any]:
        results = {}
        start = time.perf_counter()
        _ = sum(i * i for i in range(1000000))
        results["cpu_loop_ms"] = (time.perf_counter() - start) * 1000
        start = time.perf_counter()
        data = b"x" * (10 * 1024 * 1024)
        _ = hash(data)
        results["hash_10mb_ms"] = (time.perf_counter() - start) * 1000
        start = time.perf_counter()
        with tempfile.NamedTemporaryFile(delete=False) as f:
            f.write(data)
            temp_path = f.name
        try:
            start = time.perf_counter()
            with open(temp_path, "rb") as f:
                _ = f.read()
            results["disk_read_10mb_ms"] = (time.perf_counter() - start) * 1000
        finally:
            Path(temp_path).unlink(missing_ok=True)
        start = time.perf_counter()
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(2)
        try:
            sock.connect(("8.8.8.8", 53))
            results["dns_tcp_ms"] = (time.perf_counter() - start) * 1000
        except Exception:
            results["dns_tcp_ms"] = -1
        finally:
            sock.close()
        return {"status": "success", "operation": "benchmarks", "benchmarks": results, "platform": platform.platform(), "python": sys.version}

    def _full_report(self) -> Dict[str, Any]:
        return {
            "status": "success",
            "operation": "report",
            "health": self._health_check(),
            "resources": self._resources(3, 1),
            "processes": self._processes(None),
            "network": self._network(),
            "disk": self._disk(),
            "benchmarks": self._benchmarks(),
        }

"""
--------------------------------------------
HERCULE AI Operating System
Module: File Ability
Author: Heeran Paul
License: MIT
--------------------------------------------

File Ability with P1 Selected-Content Understanding:
- Read-only mode using WorkspaceManager for scope enforcement
- Sensitive file protection
- Bounded reads with truncation metadata
- Consulted-file tracking for audit transparency
- Write operations preserved for backward compatibility (not part of P1)
"""

from __future__ import annotations

from pathlib import Path

import re as _re

from abilities.base_ability import BaseAbility

# Import WorkspaceManager for P1 scope enforcement
try:
    from workspace_manager import WorkspaceManager, create_workspace_manager
except Exception:
    WorkspaceManager = None
    create_workspace_manager = None

import re as _re
from pathlib import Path


def _workspace() -> Path:
    """Sandbox root for file operations (legacy, for write operations).

    Development: the process working directory at call time. Installed
    (frozen) app: a per-user workspace directory, since the install
    location (Program Files) and the launch cwd are not writable.
    """
    try:
        from system.paths import is_frozen, user_data_dir
        if is_frozen():
            workspace = user_data_dir() / "workspace"
            workspace.mkdir(parents=True, exist_ok=True)
            return workspace
    except Exception:
        pass
    return Path.cwd()


def _resolve(path: str) -> Path:
    """Resolve inside the workspace sandbox (no absolute escapes)."""
    cleaned = path.strip().strip('"').strip("'")
    workspace = _workspace()
    candidate = (Path(cleaned) if Path(cleaned).is_absolute()
                  else workspace / cleaned).resolve()
    try:
        candidate.relative_to(workspace.resolve())
    except ValueError:
        raise ValueError(f"path escapes workspace sandbox: {path!r}")
    return candidate


class FileAbility(BaseAbility):

    def __init__(self):

        super().__init__(

            "files",

            "Read, write, and list files inside the workspace sandbox. "
            "P1: Read-only mode with explicit workspace scope enforcement, "
            "sensitive file protection, bounded reads, and audit logging.",

            capability="FILE_READ",
            inputs={"operation": "read|write|list", "path": "workspace-relative path",
                    "data": "content for write", "readonly": "enable read-only P1 mode"},
            outputs={"content": "file text or listing", "consulted_files": "audit trail"},
            permissions=["FILE_READ", "FILE_WRITE"],
            environments={"default"},
            verification="content returned and non-empty / target exists",
            timeout_s=15,
            risk="MEDIUM",

        )

        # P1: Workspace manager for read-only scope enforcement
        self._workspace_manager = None
        self._readonly_mode = False
        if create_workspace_manager:
            try:
                # Get audit manager from runtime if available
                from security.auditing.audit_manager import AuditManager
                audit = AuditManager()
                self._workspace_manager = create_workspace_manager(audit)
            except Exception:
                pass

    ##################################################

    def validate_input(self, task, **kwargs):
        if isinstance(task, dict):
            if task.get("operation") in ("read", "write", "list") and task.get("path"):
                return ""
            if task.get("operation") or task.get("path"):
                return "payload needs operation (read|write|list) and path"
            return ""
        text = str(task or "")
        if not text.strip() and not kwargs.get("path"):
            return "empty file request"
        return ""

    def _ensure_workspace_manager(self):
        """Lazy initialization of workspace manager."""
        if self._workspace_manager is None and create_workspace_manager:
            try:
                from security.auditing.audit_manager import AuditManager
                audit = AuditManager()
                self._workspace_manager = create_workspace_manager(audit)
            except Exception:
                pass
        return self._workspace_manager

    def _get_workspace_root(self) -> Path:
        """Get the workspace root for P1 operations."""
        wm = self._ensure_workspace_manager()
        if wm and wm.active_scope:
            return wm.active_scope.root
        return _workspace()

    def _resolve_p1(self, path: str) -> Path:
        """P1 scope-aware resolution using WorkspaceManager."""
        wm = self._ensure_workspace_manager()
        if wm and wm.active_scope:
            workspace_root = wm.active_scope.root
            cleaned = path.strip().strip('"').strip("'")
            candidate = (Path(path) if Path(path).is_absolute()
                          else workspace_root / cleaned).resolve()
            try:
                candidate.relative_to(workspace_root.resolve())
            except ValueError:
                raise ValueError(f"path escapes workspace sandbox: {path!r}")
            return candidate
        # Fallback to legacy for backward compatibility
        return _resolve(path)

    ##################################################

    def validate_input(self, task, **kwargs):
        if isinstance(task, dict):
            if task.get("operation") in ("read", "write", "list") and task.get("path"):
                return ""
            if task.get("operation") or task.get("path"):
                return "payload needs operation (read|write|list) and path"
            return ""
        text = str(task or "")
        if not text.strip() and not kwargs.get("path"):
            return "empty file request"
        return ""

    def execute(

        self,

        task="",

        context=None,

        **kwargs,

    ):
        operation = str(kwargs.pop("operation", "") or "").lower()
        path = str(kwargs.pop("path", "") or "")
        data = kwargs.pop("data", kwargs.pop("content", ""))
        readonly = kwargs.pop("readonly", self._readonly_mode)
        text = task if isinstance(task, str) else ""

        if isinstance(task, dict):
            operation = operation or str(task.get("operation", "")).lower()
            path = path or str(task.get("path", ""))
            data = data if data != "" else task.get("data", task.get("content", ""))
            readonly = readonly or task.get("readonly", self._readonly_mode)
            text = str(task.get("description", text or ""))

        if not operation:
            lowered = f"{text} {path}".lower()
            # v1.1: write intent covers any workspace file artifact (.py,
            # .md, .json, ...) — not just .txt — so resolved multi-step
            # references ("write ... into test.py") route correctly.
            # Legacy ".txt"/"file" behavior is preserved byte-identically.
            has_file_artifact = ("file" in lowered or bool(
                _re.search(r"\.(txt|md|json|py|log|csv)\b", lowered)))
            if any(k in lowered for k in ("create", "write", "save")) and has_file_artifact:
                operation = "write"
            elif "list" in lowered and ("file" in lowered or "director" in lowered):
                operation = "list"
            else:
                operation = "read"
        if not path:
            match = _re.search(r"[\w\-./\\]+\.(txt|md|json|py|log|csv)", f"{text} {path}")
            path = match.group(0).strip("\"'") if match else path
        if operation in ("read", "write") and not path:
            # Never hallucinate a filename: without an explicit path the
            # request is underspecified — fail honestly so the pipeline can
            # fall back to another provider or report clearly.
            return {"status": "failed", "operation": operation,
                    "error": "no file path specified"}
        if operation == "write" and (data == "" or data is None):
            quoted = _re.search(r"['\"]([^'\"]+)['\"]", text)
            content_match = _re.search(r"(?i)content\s+(?:of\s+)?(?:is\s+)?(.+)$", text)
            data = (quoted.group(1) if quoted else
                    (content_match.group(1).strip() if content_match else "Hello from HERCULE"))

        # P1: Read-only mode uses WorkspaceManager for scope enforcement
        if operation in ("read", "list") and readonly:
            wm = self._ensure_workspace_manager()
            if not wm:
                return {"status": "failed", "operation": operation,
                        "error": "P1 workspace manager not available"}

            if not wm.active_scope:
                return {"status": "failed", "operation": operation,
                        "error": "no workspace selected for P1 read-only access"}

            try:
                if operation == "read":
                    result = wm.read_file(path)
                elif operation == "list":
                    result = wm.list_directory(path)
                else:
                    return {"status": "failed", "operation": operation,
                            "error": f"unsupported read-only operation: {operation}"}

                if result.allowed:
                    response = {
                        "status": "success",
                        "operation": operation,
                        "path": result.workspace_relative,
                        "content": result.path.read_text(encoding="utf-8", errors="ignore") if operation == "read" else "\n".join(sorted(p.name for p in result.path.iterdir()))
                    }
                    if result.truncation:
                        response["truncation"] = result.truncation
                    return response
                else:
                    return {
                        "status": "failed",
                        "operation": operation,
                        "error": result.reason,
                        "denial_category": result.denial_category,
                        "workspace_relative": result.workspace_relative
                    }
            except Exception as error:
                return {"status": "failed", "operation": operation, "error": str(error)}

        # Legacy path for write operations and non-readonly reads
        try:
            target = _resolve(path)
        except Exception as error:
            return {"status": "failed", "operation": operation, "error": str(error)}

        try:
            if operation == "write":
                target.parent.mkdir(parents=True, exist_ok=True)
                target.write_text(str(data), encoding="utf-8")
                return {"status": "success", "operation": "write",
                        "path": str(target.relative_to(_workspace().resolve())),
                        "content": str(data)}
            if operation == "list":
                directory = target if target.is_dir() else target.parent
                items = sorted(p.name for p in directory.iterdir()) if directory.is_dir() else []
                return {"status": "success", "operation": "list",
                        "path": str(directory), "content": "\n".join(items)}
            if not target.exists():
                return {"status": "failed", "operation": "read",
                        "path": str(path), "error": f"file not found: {path}"}
            content = target.read_text(encoding="utf-8", errors="ignore")
            return {"status": "success", "operation": "read",
                    "path": str(target.relative_to(_workspace().resolve())),
                    "content": content}
        except Exception as error:
            return {"status": "failed", "operation": operation,
                    "path": str(path), "error": str(error)}

    ##################################################

    def write(

        self,

        path,

        data,

    ):

        result = self.execute({"operation": "write", "path": path, "data": data})
        if result.get("status") != "success":
            raise RuntimeError(result.get("error", "write failed"))
        return result.get("content", "")

    def set_readonly_mode(self, enabled: bool) -> None:
        """Enable or disable P1 read-only mode."""
        self._readonly_mode = enabled
        if enabled:
            self._ensure_workspace_manager()

    def select_workspace(self, path: str, name: str = "") -> dict:
        """Select workspace for P1 read-only operations."""
        wm = self._ensure_workspace_manager()
        if not wm:
            return {"status": "failed", "error": "P1 workspace manager not available"}
        result = wm.select_workspace(path, name=name or "user-selected")
        if result.allowed:
            self._readonly_mode = True
            return {"status": "success", "workspace": result.workspace_relative, "root": str(wm.active_scope.root)}
        return {"status": "failed", "error": result.reason, "denial_category": result.denial_category}

    def clear_workspace(self) -> dict:
        """Clear the active workspace selection."""
        wm = self._ensure_workspace_manager()
        if wm:
            wm.clear_workspace()
            self._readonly_mode = False
            return {"status": "success", "message": "workspace cleared"}
        return {"status": "failed", "error": "workspace manager not available"}

    def get_workspace_info(self) -> dict:
        """Get current workspace metadata."""
        wm = self._ensure_workspace_manager()
        if wm and wm.active_scope:
            info = wm.get_workspace_info()
            info["readonly_mode"] = self._readonly_mode
            return info
        return {"status": "no_workspace", "readonly_mode": self._readonly_mode}

    def get_consulted_files(self, clear: bool = False) -> list:
        """Get the list of files consulted in this session (audit trail)."""
        wm = self._ensure_workspace_manager()
        if wm:
            return [r.__dict__ for r in wm.get_consulted_files(clear=clear)]
        return []

    def set_workspace_limits(self, max_file_size: int = None, max_lines: int = None, max_chars: int = None) -> dict:
        """Configure read limits for P1 operations."""
        wm = self._ensure_workspace_manager()
        if wm:
            wm.set_limits(max_file_size, max_lines, max_chars)
            return {"status": "success", "limits": {
                "max_file_size": max_file_size,
                "max_lines": max_lines,
                "max_chars": max_chars
            }}
        return {"status": "failed", "error": "workspace manager not available"}

    def set_readonly_enforcement(self, enforce: bool = True) -> None:
        """Set read-only enforcement mode."""
        self._readonly_mode = enforce
        wm = self._ensure_workspace_manager()
        if wm:
            wm.set_readonly_mode(enforce)

    ##################################################
    # P2: Change Proposal Creation Methods
    ##################################################

    def _ensure_change_proposal_manager(self):
        """Lazy initialization of change proposal manager."""
        if not hasattr(self, '_change_proposal_manager') or self._change_proposal_manager is None:
            try:
                from change_proposal_manager import ChangeProposalManager
                from security.auditing.audit_manager import AuditManager
                audit = AuditManager()
                wm = self._ensure_workspace_manager()
                self._change_proposal_manager = ChangeProposalManager(wm, audit)
            except Exception:
                pass
        return self._change_proposal_manager

    def create_text_file_proposal(
        self,
        destination_path: str,
        content: str = "",
        workspace_root: Optional[str] = None,
        workspace_name: Optional[str] = None,
        actor: str = "system",
        expires_in: Optional[float] = None,
    ) -> dict:
        """Create a CREATE_TEXT_FILE proposal."""
        cpm = self._ensure_change_proposal_manager()
        if not cpm:
            return {"status": "failed", "error": "Change proposal manager not available"}

        proposal = cpm.create_proposal(
            operation="create_text_file",
            destination_path=destination_path,
            content=content,
            workspace_root=workspace_root,
            workspace_name=workspace_name,
            actor=actor,
            expires_in=expires_in,
        )
        return proposal.to_dict()

    def edit_text_file_proposal(
        self,
        source_path: str,
        content: str,
        workspace_root: Optional[str] = None,
        workspace_name: Optional[str] = None,
        actor: str = "system",
        expires_in: Optional[float] = None,
    ) -> dict:
        """Create an EDIT_TEXT_FILE proposal."""
        cpm = self._ensure_change_proposal_manager()
        if not cpm:
            return {"status": "failed", "error": "Change proposal manager not available"}

        proposal = cpm.create_proposal(
            operation="edit_text_file",
            source_path=source_path,
            content=content,
            workspace_root=workspace_root,
            workspace_name=workspace_name,
            actor=actor,
            expires_in=expires_in,
        )
        return proposal.to_dict()

    def move_or_rename_proposal(
        self,
        source_path: str,
        destination_path: str,
        workspace_root: Optional[str] = None,
        workspace_name: Optional[str] = None,
        actor: str = "system",
        expires_in: Optional[float] = None,
    ) -> dict:
        """Create a MOVE_OR_RENAME proposal."""
        cpm = self._ensure_change_proposal_manager()
        if not cpm:
            return {"status": "failed", "error": "Change proposal manager not available"}

        proposal = cpm.create_proposal(
            operation="move_or_rename",
            source_path=source_path,
            destination_path=destination_path,
            workspace_root=workspace_root,
            workspace_name=workspace_name,
            actor=actor,
            expires_in=expires_in,
        )
        return proposal.to_dict()

    def submit_proposal(self, proposal_id: str) -> dict:
        """Submit a draft proposal for approval."""
        cpm = self._ensure_change_proposal_manager()
        if not cpm:
            return {"status": "failed", "error": "Change proposal manager not available"}

        try:
            proposal = cpm.submit_for_approval(proposal_id)
            return proposal.to_dict()
        except Exception as e:
            return {"status": "failed", "error": str(e)}

    def approve_proposal(self, proposal_id: str, actor: str = "user") -> dict:
        """Approve a pending proposal."""
        cpm = self._ensure_change_proposal_manager()
        if not cpm:
            return {"status": "failed", "error": "Change proposal manager not available"}

        try:
            proposal = cpm.approve(proposal_id, actor)
            return proposal.to_dict()
        except Exception as e:
            return {"status": "failed", "error": str(e)}

    def reject_proposal(self, proposal_id: str, actor: str = "user", reason: str = "") -> dict:
        """Reject a pending proposal."""
        cpm = self._ensure_change_proposal_manager()
        if not cpm:
            return {"status": "failed", "error": "Change proposal manager not available"}

        try:
            proposal = cpm.reject(proposal_id, actor, reason)
            return proposal.to_dict()
        except Exception as e:
            return {"status": "failed", "error": str(e)}

    def cancel_proposal(self, proposal_id: str, actor: str = "user") -> dict:
        """Cancel a draft or pending proposal."""
        cpm = self._ensure_change_proposal_manager()
        if not cpm:
            return {"status": "failed", "error": "Change proposal manager not available"}

        try:
            proposal = cpm.cancel(proposal_id, actor)
            return proposal.to_dict()
        except Exception as e:
            return {"status": "failed", "error": str(e)}

    def apply_proposal(self, proposal_id: str) -> dict:
        """Apply an approved proposal."""
        cpm = self._ensure_change_proposal_manager()
        if not cpm:
            return {"status": "failed", "error": "Change proposal manager not available"}

        try:
            proposal = cpm.apply(proposal_id)
            return proposal.to_dict()
        except Exception as e:
            return {"status": "failed", "error": str(e)}

    def get_proposal(self, proposal_id: str) -> dict:
        """Get a proposal by ID."""
        cpm = self._ensure_change_proposal_manager()
        if not cpm:
            return {"status": "failed", "error": "Change proposal manager not available"}

        proposal = cpm.get_proposal(proposal_id)
        if not proposal:
            return {"status": "failed", "error": "Proposal not found"}
        return proposal.to_dict()

    def get_proposal_preview(self, proposal_id: str) -> dict:
        """Get preview for a proposal."""
        cpm = self._ensure_change_proposal_manager()
        if not cpm:
            return {"status": "failed", "error": "Change proposal manager not available"}

        preview = cpm.get_proposal_preview(proposal_id)
        if not preview:
            return {"status": "failed", "error": "Preview not available"}
        return {"status": "success", "preview": preview.__dict__}

    def list_proposals(self, workspace_root: Optional[str] = None, state: Optional[str] = None) -> dict:
        """List proposals, optionally filtered by workspace and state."""
        cpm = self._ensure_change_proposal_manager()
        if not cpm:
            return {"status": "failed", "error": "Change proposal manager not available"}

        if workspace_root and state:
            proposals = cpm.get_proposals_by_state(state, workspace_root)
        elif workspace_root:
            proposals = cpm.get_proposals_by_workspace(workspace_root)
        elif state:
            proposals = cpm.get_proposals_by_state(state, workspace_root)
        else:
            proposals = list(cpm._proposals.values())

        return {"status": "success", "proposals": [p.to_dict() for p in proposals]}

    def expire_stale_proposals(self) -> dict:
        """Expire stale proposals."""
        cpm = self._ensure_change_proposal_manager()
        if not cpm:
            return {"status": "failed", "error": "Change proposal manager not available"}

        count = cpm.expire_stale_proposals()
        return {"status": "success", "expired_count": count}

    def cleanup_proposals(self, max_age_s: float = 3600.0) -> dict:
        """Clean up old proposals."""
        cpm = self._ensure_change_proposal_manager()
        if not cpm:
            return {"status": "failed", "error": "Change proposal manager not available"}

        count = cpm.cleanup_proposals(max_age_s)
        return {"status": "success", "removed_count": count}

from __future__ import annotations
"""
HERCULE AI Operating System
Module: Package Manager Ability
Author: Heeran Paul
License: MIT

Real implementation: pip, npm, cargo, go mod package management.
"""

import json
import subprocess
import sys
import tempfile
from pathlib import Path
from typing import Any, Dict, List, Optional

from abilities.base_ability import BaseAbility


class PackageManagerAbility(BaseAbility):

    SUPPORTED_MANAGERS = {
        "pip": {
            "install": ["pip", "install"],
            "uninstall": ["pip", "uninstall", "-y"],
            "list": ["pip", "list", "--format=json"],
            "show": ["pip", "show"],
            "search": ["pip", "search"],
            "check": ["pip", "check"],
        },
        "npm": {
            "install": ["npm", "install"],
            "uninstall": ["npm", "uninstall"],
            "list": ["npm", "list", "--json"],
            "show": ["npm", "view"],
            "search": ["npm", "search"],
            "audit": ["npm", "audit", "--json"],
        },
        "cargo": {
            "install": ["cargo", "install"],
            "uninstall": ["cargo", "uninstall"],
            "list": ["cargo", "install", "--list"],
            "search": ["cargo", "search", "--limit", "10"],
            "update": ["cargo", "update"],
        },
        "go": {
            "install": ["go", "install"],
            "list": ["go", "list", "-m", "all"],
            "get": ["go", "get"],
            "mod": ["go", "mod"],
        },
        "apt": {
            "install": ["apt-get", "install", "-y"],
            "remove": ["apt-get", "remove", "-y"],
            "list": ["dpkg", "-l"],
            "search": ["apt-cache", "search"],
            "update": ["apt-get", "update"],
        },
        "brew": {
            "install": ["brew", "install"],
            "uninstall": ["brew", "uninstall"],
            "list": ["brew", "list", "--json"],
            "search": ["brew", "search"],
            "update": ["brew", "update"],
        },
    }

    def __init__(self):
        super().__init__(
            "package_manager",
            "Package management: install, remove, list, search packages",
            capability="PACKAGE_MANAGE",
            inputs={
                "operation": "install|uninstall|list|show|search|update|audit",
                "manager": "pip|npm|cargo|go|apt|brew (auto-detected)",
                "packages": "package name(s) to install/uninstall",
                "version": "specific version (optional)",
                "flags": "additional flags",
                "cwd": "working directory",
            },
            outputs={
                "installed": "installed packages",
                "removed": "removed packages",
                "packages": "listed packages",
                "info": "package info",
                "stdout": "command output",
                "stderr": "command errors",
            },
            permissions=["PACKAGE_MANAGE", "TERMINAL_EXECUTE"],
            environments={"default"},
            verification="packages installed/removed, list verified",
            timeout_s=120,
            risk="HIGH",
        )

    def _detect_manager(self, cwd: Optional[str] = None) -> str:
        cwd = Path(cwd or ".")
        if (cwd / "package.json").exists() or (cwd / "pnpm-lock.yaml").exists() or (cwd / "yarn.lock").exists():
            return "npm"
        if (cwd / "Cargo.toml").exists():
            return "cargo"
        if (cwd / "go.mod").exists():
            return "go"
        if (cwd / "requirements.txt").exists() or (cwd / "pyproject.toml").exists():
            return "pip"
        if Path("/usr/bin/apt").exists() or Path("/usr/bin/apt-get").exists():
            return "apt"
        if Path("/opt/homebrew/bin/brew").exists() or Path("/usr/local/bin/brew").exists():
            return "brew"
        return "pip"

    def _run(self, cmd: List[str], cwd: Optional[str] = None, timeout: int = 120) -> Dict[str, Any]:
        try:
            result = subprocess.run(
                cmd,
                cwd=cwd,
                capture_output=True,
                text=True,
                timeout=timeout,
            )
            return {
                "status": "success" if result.returncode == 0 else "failed",
                "stdout": result.stdout,
                "stderr": result.stderr,
                "returncode": result.returncode,
            }
        except subprocess.TimeoutExpired:
            return {"status": "failed", "error": "command timeout", "returncode": -1}
        except FileNotFoundError:
            return {"status": "failed", "error": f"command not found: {cmd[0]}", "returncode": -1}
        except Exception as exc:
            return {"status": "failed", "error": str(exc)[:300], "returncode": -1}

    def validate_input(self, task, **kwargs):
        if isinstance(task, dict):
            op = task.get("operation", "")
            if not op:
                return "operation is required"
            if op in ("install", "uninstall") and not task.get("packages"):
                return f"{op} requires packages"
            return ""
        text = str(task or "")
        if not text.strip():
            return "empty package manager request"
        return ""

    def execute(self, task, context=None, **kwargs) -> Dict[str, Any]:
        if isinstance(task, dict):
            operation = str(task.get("operation", "")).lower()
            manager = task.get("manager") or self._detect_manager(task.get("cwd"))
            packages = task.get("packages", [])
            if isinstance(packages, str):
                packages = [packages]
            version = task.get("version")
            flags = task.get("flags", [])
            cwd = task.get("cwd")
        else:
            text = str(task or "").lower()
            if "install" in text:
                operation = "install"
            elif "remove" in text or "uninstall" in text:
                operation = "uninstall"
            elif "list" in text:
                operation = "list"
            elif "search" in text:
                operation = "search"
            else:
                operation = "list"
            manager = self._detect_manager()
            packages = []
            for word in text.split():
                if word not in ("install", "remove", "uninstall", "list", "search", "package", "packages", "the", "a", "an"):
                    packages.append(word)
            version = None
            flags = []
            cwd = None

        if manager not in self.SUPPORTED_MANAGERS:
            return {"status": "failed", "error": f"unsupported manager: {manager}"}

        mgr_cmds = self.SUPPORTED_MANAGERS[manager]
        if operation not in mgr_cmds:
            return {"status": "failed", "error": f"operation '{operation}' not supported for {manager}"}

        try:
            if operation == "install":
                return self._install(manager, packages, version, flags, cwd, mgr_cmds)
            elif operation == "uninstall":
                return self._uninstall(manager, packages, flags, cwd, mgr_cmds)
            elif operation == "list":
                return self._list(manager, cwd, mgr_cmds)
            elif operation == "show":
                return self._show(manager, packages, cwd, mgr_cmds)
            elif operation == "search":
                return self._search(manager, packages, cwd, mgr_cmds)
            elif operation == "update":
                return self._update(manager, cwd, mgr_cmds)
            elif operation == "audit":
                return self._audit(manager, cwd, mgr_cmds)
            else:
                return {"status": "failed", "error": f"unknown operation: {operation}"}
        except Exception as exc:
            return {"status": "failed", "error": str(exc)[:500]}

    def _install(self, manager: str, packages: List[str], version: Optional[str], flags: List[str], cwd: Optional[str], cmds: Dict) -> Dict[str, Any]:
        if not packages:
            return {"status": "failed", "error": "packages required for install"}
        installed = []
        for pkg in packages:
            pkg_spec = f"{pkg}=={version}" if version else pkg
            cmd = cmds["install"] + flags + [pkg_spec]
            result = self._run(cmd, cwd)
            if result["status"] == "success":
                installed.append(pkg)
            else:
                return {"status": "failed", "error": result.get("stderr", result.get("error")), "installed": installed}
        return {"status": "success", "operation": "install", "manager": manager, "installed": installed}

    def _uninstall(self, manager: str, packages: List[str], flags: List[str], cwd: Optional[str], cmds: Dict) -> Dict[str, Any]:
        if not packages:
            return {"status": "failed", "error": "packages required for uninstall"}
        removed = []
        for pkg in packages:
            cmd = cmds["uninstall"] + flags + [pkg]
            result = self._run(cmd, cwd)
            if result["status"] == "success":
                removed.append(pkg)
            else:
                return {"status": "failed", "error": result.get("stderr", result.get("error")), "removed": removed}
        return {"status": "success", "operation": "uninstall", "manager": manager, "removed": removed}

    def _list(self, manager: str, cwd: Optional[str], cmds: Dict) -> Dict[str, Any]:
        cmd = cmds["list"]
        result = self._run(cmd, cwd)
        if result["status"] != "success":
            return result
        try:
            if manager == "pip":
                pkgs = json.loads(result["stdout"])
                packages = [{"name": p["name"], "version": p["version"]} for p in pkgs]
            elif manager == "npm":
                data = json.loads(result["stdout"])
                packages = self._parse_npm_list(data)
            elif manager == "cargo":
                lines = result["stdout"].strip().split("\n")
                packages = [{"name": l.split()[0], "version": l.split()[1]} for l in lines if l and " " in l]
            elif manager == "apt":
                lines = result["stdout"].strip().split("\n")
                packages = [{"name": l.split()[1], "version": l.split()[2]} for l in lines if l.startswith("ii")]
            else:
                packages = [{"raw": result["stdout"]}]
            return {"status": "success", "operation": "list", "manager": manager, "packages": packages}
        except Exception as exc:
            return {"status": "success", "operation": "list", "manager": manager, "packages": [{"raw": result["stdout"]}]}

    def _parse_npm_list(self, data: Dict) -> List[Dict]:
        packages = []
        for name, info in data.get("dependencies", {}).items():
            packages.append({"name": name, "version": info.get("version", "")})
        return packages

    def _show(self, manager: str, packages: List[str], cwd: Optional[str], cmds: Dict) -> Dict[str, Any]:
        if not packages:
            return {"status": "failed", "error": "package required for show"}
        info = {}
        for pkg in packages:
            cmd = cmds["show"] + [pkg]
            result = self._run(cmd, cwd)
            if result["status"] == "success":
                try:
                    info[pkg] = json.loads(result["stdout"])
                except Exception:
                    info[pkg] = {"raw": result["stdout"]}
            else:
                info[pkg] = {"error": result.get("stderr", "unknown")}
        return {"status": "success", "operation": "show", "manager": manager, "info": info}

    def _search(self, manager: str, packages: List[str], cwd: Optional[str], cmds: Dict) -> Dict[str, Any]:
        if not packages:
            return {"status": "failed", "error": "query required for search"}
        query = " ".join(packages)
        cmd = cmds["search"] + [query]
        result = self._run(cmd, cwd)
        if result["status"] != "success":
            return result
        try:
            if manager == "npm":
                return {"status": "success", "operation": "search", "manager": manager, "results": json.loads(result["stdout"])}
        except Exception:
            pass
        return {"status": "success", "operation": "search", "manager": manager, "results": result["stdout"]}

    def _update(self, manager: str, cwd: Optional[str], cmds: Dict) -> Dict[str, Any]:
        if "update" not in cmds:
            return {"status": "failed", "error": f"update not supported for {manager}"}
        result = self._run(cmds["update"], cwd)
        return {"status": result["status"], "operation": "update", "manager": manager, "stdout": result["stdout"], "stderr": result["stderr"]}

    def _audit(self, manager: str, cwd: Optional[str], cmds: Dict) -> Dict[str, Any]:
        if "audit" not in cmds:
            return {"status": "failed", "error": f"audit not supported for {manager}"}
        result = self._run(cmds["audit"], cwd)
        if result["status"] != "success":
            return result
        try:
            return {"status": "success", "operation": "audit", "manager": manager, "results": json.loads(result["stdout"])}
        except Exception:
            return {"status": "success", "operation": "audit", "manager": manager, "results": result["stdout"]}

from __future__ import annotations
"""
--------------------------------------------
HERCULE AI Operating System
Module: Terminal Ability
Author: Heeran Paul
License: MIT
--------------------------------------------

Safe, restricted terminal execution: allowlisted read-only commands,
no shell, timeout enforced, destructive patterns blocked. High-risk:
callers must pass approval_required=True and approved=True (enforced
by AbilityManager). This never permits unrestricted system execution.
"""


import re as _re
import shlex
import subprocess

from abilities.base_ability import BaseAbility


_ALLOWED = {
    "echo": {"echo"},
    "info": {"hostname", "whoami", "python", "pip", "ls", "dir", "cat", "type"},
}

_FLAT_ALLOWED = {"echo", "hostname", "whoami", "python", "pip", "ls", "dir", "cat", "type"}

_BLOCKED = ("&", "|", ";", ">", "<", "`", "$", "rm ", "del ", "format", "shutdown",
            "reboot", "mkfs", "curl", "wget", "ssh", "chmod", "chown", "sudo", "powershell -c")

# Commands that take filesystem operands must stay inside the workspace
# sandbox (absolute paths or parent escapes would allow reads outside it).
_PATH_OPERAND_COMMANDS = {"ls", "dir", "cat", "type"}


def _workspace_safe(operand: str) -> bool:
    from pathlib import Path
    cleaned = (operand or "").strip().strip('"').strip("'")
    if not cleaned or cleaned.startswith("-"):
        return True  # flags carry no path
    candidate = Path(cleaned)
    if candidate.is_absolute():
        return False
    if ".." in candidate.parts:
        return False
    return True


class TerminalAbility(BaseAbility):

    def __init__(self):

        super().__init__(

            "terminal",

            "Execute allowlisted read-only terminal commands",

            capability="TERMINAL_EXECUTE",
            inputs={"command": "allowlisted command string"},
            outputs={"stdout": "command output"},
            permissions=["TERMINAL_EXECUTE"],
            environments={"default"},
            verification="exit status 0, relevant outputs captured",
            timeout_s=10,
            risk="HIGH",

        )

    ##################################################

    def validate_input(self, task, **kwargs):
        command = str(task if isinstance(task, str) else kwargs.get("command", "") or "")
        if not command.strip():
            return "empty command"
        lowered = command.lower()
        if any(pattern in lowered for pattern in _BLOCKED):
            return f"blocked pattern in command: {command[:80]}"
        try:
            parts = shlex.split(command, posix=True)
        except Exception:
            return "unparseable command"
        if not parts or parts[0].lower() not in _FLAT_ALLOWED:
            return f"command not allowlisted: {parts[0] if parts else ''}"
        if parts[0].lower() in _PATH_OPERAND_COMMANDS:
            # Check the RAW text: posix shlex strips backslashes, which
            # would hide Windows absolute paths (C:\...) from inspection.
            if _re.search(r"[a-zA-Z]:[\\/]", command) or "\\\\" in command:
                return ("path escapes workspace sandbox "
                        "(absolute paths are not allowed; use workspace-relative paths)")
            for operand in parts[1:]:
                if not _workspace_safe(operand):
                    return (f"path escapes workspace sandbox: {operand[:80]} "
                            f"(use workspace-relative paths)")
        return ""

    def execute(

        self,

        command: str = "",

        task=None,

        **kwargs,

    ):
        raw = str(command or task or kwargs.get("command", "") or "")
        problem = self.validate_input(raw)
        if problem:
            return {"status": "failed", "command": raw, "error": problem}

        parts = shlex.split(raw, posix=True)
        # Restrict subcommands: python --version, pip list, ls/dir listings.
        head = parts[0].lower()
        if head == "python" and parts[1:] not in ([], ["--version"]):
            return {"status": "failed", "command": raw,
                    "error": "only 'python --version' is allowlisted"}
        if head == "pip" and parts[1:] != ["list"]:
            return {"status": "failed", "command": raw,
                    "error": "only 'pip list' is allowlisted"}

        try:
            result = subprocess.run(
                parts,
                shell=False,
                capture_output=True,
                text=True,
                timeout=self.timeout_s,
            )
        except subprocess.TimeoutExpired:
            return {"status": "failed", "command": raw, "error": "command timed out"}
        except Exception as error:
            return {"status": "failed", "command": raw, "error": str(error)}

        if result.returncode != 0:
            return {"status": "failed", "command": raw, "stdout": result.stdout,
                    "stderr": result.stderr, "returncode": result.returncode,
                    "error": f"non-zero exit {result.returncode}"}
        return {

            "status": "success",

            "command": raw,

            "stdout": result.stdout,

            "stderr": result.stderr,

