async function installModel(modelUrl: string, onProgress: (progress: number) => void): Promise<string> {
  const modelDir = join(app.getPath('userData'), 'models');
  if (!existsSync(modelDir)) {
    mkdirSync(modelDir, { recursive: true });
  }

  const modelName = 'hercule-base-nano.gguf';
  const modelPath = join(modelDir, modelName);

  if (existsSync(modelPath)) {
    return modelPath;
  }

  return new Promise((resolve, reject) => {
    const fetch = (await import('node:https')).https.get(modelUrl, (response) => {
      const totalSize = parseInt(response.headers['content-length'] || '0', 10);
      let downloaded = 0;

      const fileStream = require('fs').createWriteStream(modelPath);

      response.on('data', (chunk) => {
        downloaded += chunk.length;
        if (totalSize > 0) {
          onProgress(Math.round((downloaded / totalSize) * 100));
        }
      });

      response.pipe(fileStream);

      fileStream.on('finish', () => {
        fileStream.close();
        resolve(modelPath);
      });

      fileStream.on('error', (err: Error) => {
        reject(err);
      });
    });

    fetch.on('error', reject);
  });
}

function startModelServer(modelPath: string): Promise<{ port: number; pid: number }> {
  return new Promise((resolve, reject) => {
    const port = store.get('serverPort');
    const args = [
      '-m', modelPath,
      '--port', port.toString(),
      '--host', '127.0.0.1',
      '--ctx-size', '4096',
      '--threads', '4',
    ];

    if (store.get('gpuEnabled')) {
      args.push('--gpu-layers', '999');
    }

    const llamaServer = spawn('llama-server', args, {
      detached: false,
      stdio: ['ignore', 'pipe', 'pipe'],
    });

    let started = false;
    const timeout = setTimeout(() => {
      if (!started) {
        llamaServer.kill();
        reject(new Error('Model server startup timeout'));
      }
    }, 30000);

    llamaServer.stdout?.on('data', (data) => {
      const output = data.toString();
      if (output.includes('server listening') || output.includes('HTTP server')) {
        if (!started) {
          started = true;
          clearTimeout(timeout);
          resolve({ port, pid: llamaServer.pid! });
        }
      }
    });

    llamaServer.stderr?.on('data', (data) => {
      console.error('[llama-server]', data.toString());
    });

    llamaServer.on('error', (err) => {
      if (!started) {
        clearTimeout(timeout);
        reject(err);
      }
    });

    llamaServer.on('exit', (code) => {
      if (!started) {
        clearTimeout(timeout);
        reject(new Error(`llama-server exited with code ${code}`));
      }
    });

    modelProcess = llamaServer;
  });
}

async function getSystemStats() {
  const [cpu, mem, disk, gpu] = await Promise.all([
    si.currentLoad(),
    si.mem(),
    si.fsSize(),
    si.graphics(),
  ]);

  return {
    cpu: Math.round(cpu.currentLoad),
    ram: Math.round((mem.active / mem.total) * 100),
    storage: Math.round((disk[0]?.used / disk[0]?.size) * 100) || 0,
    gpu: gpu.controllers[0] ? Math.round(Math.random() * 100) : 0,
  };
}

