"""Pixel-level input/output change representation for ARC demonstrations."""

from __future__ import annotations

from dataclasses import dataclass

from .grid import Grid, dimensions


Cell = tuple[int, int, int]
RecoloredCell = tuple[int, int, int, int]


@dataclass(frozen=True)
class GridDelta:
    source_dimensions: tuple[int, int]
    target_dimensions: tuple[int, int]
    preserved_cells: frozenset[Cell]
    removed_cells: frozenset[Cell]
    added_cells: frozenset[Cell]
    recolored_cells: frozenset[RecoloredCell]

    @property
    def dimensions_changed(self) -> bool:
        return self.source_dimensions != self.target_dimensions

    @property
    def changed_cell_count(self) -> int:
        return (len(self.removed_cells) + len(self.added_cells) +
                len(self.recolored_cells))


def compare_grids(source: Grid, target: Grid, background: int = 0) -> GridDelta:
    """Classify cells as preserved, removed, added, or recolored.

    Objects that move appear as removals and additions at pixel level. Higher
    reasoning layers can use object signatures to infer that correspondence.
    """
    source_h, source_w = dimensions(source)
    target_h, target_w = dimensions(target)
    preserved: set[Cell] = set()
    removed: set[Cell] = set()
    added: set[Cell] = set()
    recolored: set[RecoloredCell] = set()
    for row in range(max(source_h, target_h)):
        for col in range(max(source_w, target_w)):
            old = source[row][col] if row < source_h and col < source_w else background
            new = target[row][col] if row < target_h and col < target_w else background
            if old == new:
                continue
            if old == background:
                added.add((row, col, new))
            elif new == background:
                removed.add((row, col, old))
            else:
                recolored.add((row, col, old, new))
    for row in range(min(source_h, target_h)):
        for col in range(min(source_w, target_w)):
            value = source[row][col]
            if value != background and target[row][col] == value:
                preserved.add((row, col, value))
    return GridDelta((source_h, source_w), (target_h, target_w),
                     frozenset(preserved), frozenset(removed),
                     frozenset(added), frozenset(recolored))

"""Validated ARC grid parsing and small grid utilities."""

from __future__ import annotations

from collections import Counter
from typing import Iterable, Sequence, TypeAlias

Grid: TypeAlias = tuple[tuple[int, ...], ...]


def parse_grid(value: object) -> Grid:
    """Validate and freeze an ARC grid (nonempty, rectangular, colors 0..9)."""
    if not isinstance(value, (list, tuple)) or not value:
        raise ValueError("grid must be a nonempty sequence of rows")
    rows: list[tuple[int, ...]] = []
    width: int | None = None
    for row in value:
        if not isinstance(row, (list, tuple)) or not row:
            raise ValueError("grid rows must be nonempty sequences")
        parsed: list[int] = []
        for cell in row:
            if isinstance(cell, bool) or not isinstance(cell, int) or not 0 <= cell <= 9:
                raise ValueError(f"invalid ARC color: {cell!r}")
            parsed.append(cell)
        if width is None:
            width = len(parsed)
        elif len(parsed) != width:
            raise ValueError("grid must be rectangular")
        rows.append(tuple(parsed))
    return tuple(rows)


def dimensions(grid: Grid) -> tuple[int, int]:
    return len(grid), len(grid[0])


def to_lists(grid: Grid) -> list[list[int]]:
    return [list(row) for row in grid]


def make_grid(height: int, width: int, fill: int = 0) -> Grid:
    if height < 1 or width < 1 or not 0 <= fill <= 9:
        raise ValueError("invalid grid dimensions or fill color")
    return tuple(tuple(fill for _ in range(width)) for _ in range(height))


def non_background_cells(grid: Grid, background: int = 0) -> frozenset[tuple[int, int]]:
    return frozenset((r, c) for r, row in enumerate(grid)
                     for c, value in enumerate(row) if value != background)


def colors(grid: Grid) -> frozenset[int]:
    return frozenset(value for row in grid for value in row)


def infer_background(grid: Grid) -> int:
    """Infer the background color as 0 if present, otherwise most frequent."""
    counts = Counter(value for row in grid for value in row)
    if 0 in counts:
        return 0
    maximum = max(counts.values())
    tied = [color for color, count in counts.items() if count == maximum]
    return min(tied)

"""Metamorphic checks for exact-fit ARC rule candidates."""

from __future__ import annotations

from collections import deque
from typing import Iterable

from .grid import Grid
from .primitives import crop_non_background
from .relations import infer_background
from .objects import extract_objects


def _pad(grid: Grid, color: int, top: int = 1, left: int = 1,
         bottom: int = 1, right: int = 1) -> Grid:
    width = len(grid[0]) + left + right
    rows = [[color] * width for _ in range(top)]
    rows.extend([[color] * left + list(row) + [color] * right for row in grid])
    rows.extend([[color] * width for _ in range(bottom)])
    return tuple(tuple(row) for row in rows)


def _canvas_padding(rule, pairs) -> bool | None:
    applicable = 0
    for source, target in pairs:
        background = infer_background(source)
        padded = _pad(source, background)
        if (len(source), len(source[0])) == (len(target), len(target[0])):
            expected = _pad(target, background)
        elif crop_non_background(source, background) == target:
            # An outer canvas border is irrelevant to a crop-by-content rule.
            expected = target
        else:
            continue
        applicable += 1
        try:
            if rule.apply(padded) != expected:
                return False
        except (ArithmeticError, IndexError, TypeError, ValueError):
            return False
    return applicable > 0 if applicable else None


def _background_recolor(rule, pairs) -> bool | None:
    applicable = 0
    for source, target in pairs:
        if (len(source), len(source[0])) != (len(target), len(target[0])):
            continue
        background = infer_background(source)
        used = {value for row in source + target for value in row}
        replacement = next((value for value in range(10) if value not in used), None)
        if replacement is None:
            continue
        changed_source = tuple(tuple(replacement if value == background else value
                                     for value in row) for row in source)
        changed_target = tuple(tuple(replacement if value == background else value
                                     for value in row) for row in target)
        applicable += 1
        try:
            if rule.apply(changed_source) != changed_target:
                return False
        except (ArithmeticError, IndexError, TypeError, ValueError):
            return False
    return applicable > 0 if applicable else None


def _palette_rename(rule, pairs) -> bool | None:
    palette = sorted({value for source, target in pairs
                      for row in source + target for value in row if value != 0})
    if not palette:
        return None
    mapping: dict[int, int] = {}
    if len(palette) > 1:
        mapping[palette[0]], mapping[palette[1]] = palette[1], palette[0]
    else:
        replacement = next((value for value in range(1, 10)
                            if value != palette[0]), None)
        if replacement is None:
            return None
        mapping[palette[0]] = replacement
    for source, target in pairs:
        renamed_source = tuple(tuple(mapping.get(value, value) for value in row)
                               for row in source)
        renamed_target = tuple(tuple(mapping.get(value, value) for value in row)
                               for row in target)
        try:
            if rule.apply(renamed_source) != renamed_target:
                return False
        except (ArithmeticError, IndexError, TypeError, ValueError):
            return False
    return True


def _irrelevant_object_insertion(rule, pairs) -> bool | None:
    """Insert an irrelevant distractor object and check if rule still executes without unhandled exceptions.

    The test adds a single pixel of unused color and verifies the rule doesn't crash
    with unhandled exceptions (ArithmeticError, IndexError, TypeError).
    ValueError from selector ambiguity is expected when input is modified.
    """
    applicable = 0
    for source, target in pairs:
        background = infer_background(source)
        used_colors = {v for s, t in pairs for row in s + t for v in row if v != background}
        unused_colors = [c for c in range(1, 10) if c not in used_colors]
        if not unused_colors:
            continue
        distractor_color = unused_colors[0]
        h, w = len(source), len(source[0])

        # Find empty spot
        for r in range(h):
            for c in range(w):
                if source[r][c] == background:
                    test_grid = [list(row) for row in source]
                    test_grid[r][c] = distractor_color
                    test_grid = tuple(tuple(row) for row in test_grid)
                    applicable += 1
                    try:
                        result = rule.apply(test_grid)
                        # Rule should execute and produce valid grid dimensions
                        if len(result) != len(source) or len(result[0]) != len(source[0]):
                            return False
                    except (ArithmeticError, IndexError, TypeError):
                        # Unhandled exceptions are failures
                        return False
                    except ValueError:
                        # ValueError from selector ambiguity is expected when input is modified
                        # This is not a failure - the rule gracefully handles ambiguous input
                        pass
                    break
            if applicable > 0:
                break
    return applicable > 0 if applicable else None


def _irrelevant_object_deletion(rule, pairs) -> bool | None:
    """Delete an irrelevant object and check if rule still works on remaining.

    Removes the smallest object (likely distractor) and checks if rule executes
    without unhandled exceptions. ValueError from selector ambiguity is expected
    if the removed object was a landmark/source.
    """
    applicable = 0
    for source, target in pairs:
        background = infer_background(source)
        objects = extract_objects(source, background_color=background)
        if len(objects) < 2:
            continue
        # Remove the smallest object (likely distractor)
        smallest = min(objects, key=lambda o: len(o.cells))
        test_grid = [list(row) for row in source]
        for r, c in smallest.cells:
            test_grid[r][c] = background
        test_grid = tuple(tuple(row) for row in test_grid)
        applicable += 1
        try:
            result = rule.apply(test_grid)
            if len(result) != len(source) or len(result[0]) != len(source[0]):
                return False
        except (ArithmeticError, IndexError, TypeError):
            # Unhandled exceptions are failures
            return False
        except ValueError:
            # ValueError from selector ambiguity is expected if we removed a landmark/source
            pass
    return applicable > 0 if applicable else None


def _object_reordering(rule, pairs) -> bool | None:
    """Test if rule works when object order changes (should for relational rules)."""
    applicable = 0
    for source, target in pairs:
        background = infer_background(source)
        objects = extract_objects(source, background_color=background)
        if len(objects) < 2:
            continue
        # This test is more conceptual - we test by applying to a grid
        # where objects are in different spatial arrangement but same relations
        # For now, just check basic applicability
        applicable += 1
        try:
            result = rule.apply(source)
            if result != target:
                return False
        except (ArithmeticError, IndexError, TypeError, ValueError):
            return False
    return applicable > 0 if applicable else None


def _symmetric_duplicate_insertion(rule, pairs) -> bool | None:
    """Insert a symmetric duplicate of an existing object."""
    applicable = 0
    for source, target in pairs:
        background = infer_background(source)
        objects = extract_objects(source, background_color=background)
        if not objects:
            continue
        # Try to place a duplicate of the first object at a symmetric position
        obj = objects[0]
        h, w = len(source), len(source[0])
        # Try placing at mirrored position
        top, left, bottom, right = obj.bbox
        mirror_r = h - 1 - (top + bottom) // 2
        mirror_c = w - 1 - (left + right) // 2
        if 0 <= mirror_r < h and 0 <= mirror_c < w:
            test_grid = [list(row) for row in source]
            for r, c in obj.cells:
                nr = mirror_r - top + r
                nc = mirror_c - left + c
                if 0 <= nr < h and 0 <= nc < w:
                    test_grid[nr][nc] = obj.color
            test_grid = tuple(tuple(row) for row in test_grid)
            applicable += 1
            try:
                result = rule.apply(test_grid)
                if len(result) != len(source) or len(result[0]) != len(source[0]):
                    return False
            except (ArithmeticError, IndexError, TypeError):
                # Unhandled exceptions are failures
                return False
            except ValueError:
                # ValueError from selector ambiguity is expected when input is modified
                pass
    return applicable > 0 if applicable else None


def _distractor_objects(rule, pairs) -> bool | None:
    """Combined test: rule should not break when distractors are added/removed."""
    # Test insertion
    ins = _irrelevant_object_insertion(rule, pairs)
    if ins is False:
        return False
    # Test deletion
    dels = _irrelevant_object_deletion(rule, pairs)
    if dels is False:
        return False
    return True


def check_rule_invariance(rule, train_pairs: Iterable[tuple[Grid, Grid]]) -> dict:
    """Check exact-fit rules under controlled frame, background, and color changes.

    Acceptance criteria:
    - Relational rules (with relation_predicates) MUST pass landmark_translation
      when it is applicable (not None). This tests whether the rule tracks
      landmark movement rather than memorizing fixed offsets.
      Relational rules should also NOT fail extended checks when applicable.
    - Non-relational rules must pass at least one CORE invariance check:
      landmark_translation, canvas_padding, or background_recolor.
      Palette_rename is reported but does NOT grant acceptance alone,
      EXCEPT for general geometric transformations (scale, tile) where 
      no core checks are applicable.
      Extended checks (distractor_robustness, symmetric_duplicate) are 
      reported but do NOT grant/revoke acceptance for non-relational rules.
    """
    pairs = tuple(train_pairs)
    outcomes: dict[str, bool | None] = {"landmark_translation": None}
    has_relation = bool(getattr(rule, "relation_predicates", ()))
    if rule.relation_perturbation is not None:
        results = [rule.relation_perturbation(source) for source, _ in pairs]
        applicable = [result for result in results if result is not None]
        outcomes["landmark_translation"] = (
            bool(applicable) and all(applicable) if applicable else None)
    outcomes["canvas_padding"] = _canvas_padding(rule, pairs)
    outcomes["background_recolor"] = _background_recolor(rule, pairs)
    outcomes["palette_rename"] = _palette_rename(rule, pairs)
    # Extended invariance tests
    outcomes["distractor_robustness"] = _distractor_objects(rule, pairs)
    outcomes["symmetric_duplicate"] = _symmetric_duplicate_insertion(rule, pairs)

    core_checks = ("landmark_translation", "canvas_padding", "background_recolor")
    extended_checks = ("distractor_robustness", "symmetric_duplicate")
    # Relational rules require landmark_translation to pass when applicable.
    if has_relation and outcomes["landmark_translation"] is not None:
        # For relational: require landmark_translation AND don't fail extended checks
        lt_pass = outcomes["landmark_translation"] is True
        ext_fail = any(outcomes.get(c) is False for c in extended_checks)
        accepted = lt_pass and not ext_fail
    else:
        # Non-relational: accept if at least one CORE check passes.
        passed_core = tuple(name for name in core_checks if outcomes.get(name) is True)
        # For general geometric transformations (scale, tile) where no core 
        # checks are applicable, palette_rename can grant acceptance.
        core_applicable = any(outcomes.get(c) is not None for c in core_checks)
        # Only scale and tile families get palette_rename acceptance for dimension-changing
        is_geometric_transform = getattr(rule, "family", "") in ("scaling", "tiling")
        if not core_applicable and outcomes.get("palette_rename") is True and is_geometric_transform:
            accepted = True
        else:
            accepted = bool(passed_core)

    failed = tuple(name for name, result in outcomes.items() if result is False)
    return {"passed": tuple(name for name, result in outcomes.items() if result is True),
            "failed": failed,
            "not_applicable": tuple(name for name, result in outcomes.items()
                                     if result is None),
            "accepted": accepted, "checks": outcomes}

"""Deterministic ARC grid and object transformation primitives."""

from __future__ import annotations

from collections.abc import Callable, Iterable, Sequence
from typing import Any

from .grid import Grid, make_grid, infer_background
from .objects import ArcObject, connected_components, describe_object, extract_objects


def reflect_horizontal(grid: Grid) -> Grid:
    return tuple(reversed(grid))


def reflect_vertical(grid: Grid) -> Grid:
    return tuple(tuple(reversed(row)) for row in grid)


def rotate(grid: Grid, quarter_turns: int = 1) -> Grid:
    """Rotate clockwise by an integer number of quarter turns."""
    turns = quarter_turns % 4
    result = grid
    for _ in range(turns):
        result = tuple(tuple(result[r][c] for r in range(len(result) - 1, -1, -1))
                       for c in range(len(result[0])))
    return result


def translate(grid: Grid, dy: int, dx: int, background: int = 0) -> Grid:
    h, w = len(grid), len(grid[0])
    out = [list(row) for row in make_grid(h, w, background)]
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            rr, cc = r + dy, c + dx
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = value
    return tuple(tuple(row) for row in out)


def scale(grid: Grid, sy: int, sx: int | None = None) -> Grid:
    sx = sy if sx is None else sx
    if sy < 1 or sx < 1:
        raise ValueError("scale factors must be positive integers")
    return tuple(tuple(value for value in row for _ in range(sx))
                 for row in grid for _ in range(sy))


def tile(grid: Grid, ny: int, nx: int | None = None) -> Grid:
    nx = ny if nx is None else nx
    if ny < 1 or nx < 1:
        raise ValueError("tile counts must be positive integers")
    return tuple(tuple(grid[r % len(grid)][c % len(grid[0])]
                       for c in range(len(grid[0]) * nx))
                 for r in range(len(grid) * ny))


def crop(grid: Grid, top: int, left: int, bottom: int, right: int) -> Grid:
    if not (0 <= top < bottom <= len(grid) and 0 <= left < right <= len(grid[0])):
        raise ValueError("crop bounds are outside the grid or empty")
    return tuple(tuple(row[left:right]) for row in grid[top:bottom])


def crop_non_background(grid: Grid, background: int = 0) -> Grid:
    cells = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row)
             if value != background]
    if not cells:
        return ((background,),)
    return crop(grid, min(r for r, _ in cells), min(c for _, c in cells),
                max(r for r, _ in cells) + 1, max(c for _, c in cells) + 1)


def crop_color(grid: Grid, color: int, background: int = 0) -> Grid:
    selected = tuple(tuple(value if value == color else background for value in row)
                     for row in grid)
    return crop_non_background(selected, background)


def fill_enclosed_background(grid: Grid, color: int | None = None,
                             background: int = 0) -> Grid:
    """Fill enclosed background cells with color or the most frequent foreground."""
    from .objects import enclosed_background_cells
    if color is None:
        counts = {value: sum(cell == value for row in grid for cell in row)
                  for value in {cell for row in grid for cell in row if cell != background}}
        if not counts:
            return grid
        color = min(counts, key=lambda value: (-counts[value], value))
    out = [list(row) for row in grid]
    for r, c in enclosed_background_cells(grid, background):
        out[r][c] = color
    return tuple(tuple(row) for row in out)


def object_bounding_boxes(grid: Grid, background: int = 0) -> Grid:
    out = [list(row) for row in grid]
    for obj in extract_objects(grid):
        top, left, bottom, right = obj.bbox
        for r in range(top, bottom):
            for c in range(left, right):
                if out[r][c] not in (background, obj.color):
                    raise ValueError("object bounding boxes of different colors overlap")
                out[r][c] = obj.color
    return tuple(tuple(row) for row in out)


def object_outlines(grid: Grid, background: int = 0) -> Grid:
    out = [[background] * len(grid[0]) for _ in grid]
    for obj in extract_objects(grid):
        for r, c in obj.cells:
            if any((r + dr, c + dc) not in obj.cells
                   for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1))):
                out[r][c] = obj.color
    return tuple(tuple(row) for row in out)


def object_shape_signature(obj: ArcObject) -> tuple:
    top, left, _, _ = obj.bbox
    return (obj.height, obj.width,
            tuple(sorted((r - top, c - left) for r, c in obj.cells)))


def object_feature(obj: ArcObject, feature: str) -> tuple | int | str:
    if feature == "size":
        return len(obj.cells)
    if feature == "shape":
        return object_shape_signature(obj)
    if feature == "orientation":
        return obj.orientation
    if feature == "symmetry":
        return obj.symmetry
    if feature == "dimensions":
        return obj.height, obj.width
    if feature == "aspect":
        return obj.height, obj.width
    if feature == "color":
        return obj.color
    raise ValueError(f"unknown object feature: {feature}")


def select_objects(grid: Grid, selector: str, background: int = 0) -> Grid:
    """Keep objects selected by a simple, explicitly named structural rule."""
    objects = extract_objects(grid)
    if not objects:
        return grid
    areas = [len(obj.cells) for obj in objects]
    if selector == "largest":
        chosen = {id(obj) for obj in objects if len(obj.cells) == max(areas)}
    elif selector == "smallest":
        chosen = {id(obj) for obj in objects if len(obj.cells) == min(areas)}
    elif selector == "unique-size":
        counts = {area: areas.count(area) for area in set(areas)}
        chosen = {id(obj) for obj in objects if counts[len(obj.cells)] == 1}
    elif selector == "unique-shape":
        shapes = [object_shape_signature(obj) for obj in objects]
        chosen = {id(obj) for obj, shape in zip(objects, shapes)
                  if shapes.count(shape) == 1}
    elif selector in {"most-frequent-color", "least-frequent-color"}:
        counts = {color: sum(obj.color == color for obj in objects)
                  for color in {obj.color for obj in objects}}
        target = (max(counts.values()) if selector == "most-frequent-color"
                  else min(counts.values()))
        colors = {color for color, value in counts.items() if value == target}
        chosen = {id(obj) for obj in objects if obj.color in colors}
    elif selector in {"symmetric", "asymmetric"}:
        chosen = {id(obj) for obj in objects
                  if any(obj.symmetry) == (selector == "symmetric")}
    elif selector in {"horizontal", "vertical", "square", "point", "wide", "tall"}:
        chosen = {id(obj) for obj in objects if obj.orientation == selector}
    else:
        raise ValueError(f"unknown object selector: {selector}")
    return render_objects((obj for obj in objects if id(obj) in chosen),
                          len(grid), len(grid[0]), background)


def recolor_objects_by_feature(grid: Grid, mapping: dict,
                               feature: str = "shape") -> Grid:
    """Recolor each whole component from a learned structural feature map."""
    out = [list(row) for row in grid]
    for obj in extract_objects(grid):
        color = mapping.get(object_feature(obj, feature), obj.color)
        if not isinstance(color, int) or not 0 <= color <= 9:
            raise ValueError("mapped object color is outside the ARC palette")
        for r, c in obj.cells:
            out[r][c] = color
    return tuple(tuple(row) for row in out)


def transform_each_object(grid: Grid, operation: str,
                          background: int = 0) -> Grid:
    """Apply a local geometric transform to every object at its top-left anchor."""
    transforms = {
        "reflect-horizontal": reflect_horizontal,
        "reflect-vertical": reflect_vertical,
        "rotate-90": lambda g: rotate(g, 1),
        "rotate-180": lambda g: rotate(g, 2),
        "rotate-270": lambda g: rotate(g, 3),
    }
    if operation not in transforms:
        raise ValueError(f"unknown local object transform: {operation}")
    out = [list(row) for row in make_grid(len(grid), len(grid[0]), background)]
    for obj in extract_objects(grid):
        top, left, bottom, right = obj.bbox
        local = tuple(tuple(grid[r][c] if (r, c) in obj.cells else background
                            for c in range(left, right))
                      for r in range(top, bottom))
        transformed = transforms[operation](local)
        if top + len(transformed) > len(grid) or left + len(transformed[0]) > len(grid[0]):
            raise ValueError("transformed object exceeds the grid boundary")
        for r, row in enumerate(transformed):
            for c, color in enumerate(row):
                if color == background:
                    continue
                rr, cc = top + r, left + c
                if out[rr][cc] not in (background, color):
                    raise ValueError("locally transformed objects collide")
                out[rr][cc] = color
    return tuple(tuple(row) for row in out)


def complete_symmetry(grid: Grid, axis: str = "vertical", background: int = 0) -> Grid:
    """Complete a grid under an axis reflection; incompatible halves are rejected."""
    h, w = len(grid), len(grid[0])
    out = [list(row) for row in grid]
    for r in range(h):
        for c in range(w):
            if axis == "vertical":
                rr, cc = r, w - 1 - c
            elif axis == "horizontal":
                rr, cc = h - 1 - r, c
            elif axis == "diagonal":
                if h != w:
                    raise ValueError("diagonal symmetry requires a square grid")
                rr, cc = c, r
            elif axis == "antidiagonal":
                if h != w:
                    raise ValueError("antidiagonal symmetry requires a square grid")
                rr, cc = h - 1 - c, w - 1 - r
            else:
                raise ValueError(f"unknown symmetry axis: {axis}")
            a, b = grid[r][c], grid[rr][cc]
            if a != background and b != background and a != b:
                raise ValueError("input conflicts with the requested symmetry")
            out[r][c] = a if a != background else b
    return tuple(tuple(row) for row in out)


def gravity(grid: Grid, direction: str = "down", background: int = 0) -> Grid:
    """Move rigid monochrome objects until the edge or another object blocks them."""
    if direction not in {"up", "down", "left", "right"}:
        raise ValueError(f"unknown gravity direction: {direction}")
    vectors = {"up": (-1, 0), "down": (1, 0),
               "left": (0, -1), "right": (0, 1)}
    dr, dc = vectors[direction]
    if direction == "down":
        objects = sorted(extract_objects(grid), key=lambda o: -o.bbox[2])
    elif direction == "up":
        objects = sorted(extract_objects(grid), key=lambda o: o.bbox[0])
    elif direction == "right":
        objects = sorted(extract_objects(grid), key=lambda o: -o.bbox[3])
    else:
        objects = sorted(extract_objects(grid), key=lambda o: o.bbox[1])
    h, w = len(grid), len(grid[0])
    out = [[background] * w for _ in range(h)]
    for obj in objects:
        cells = obj.cells
        dy = dx = 0
        while True:
            shifted = {(r + dy + dr, c + dx + dc) for r, c in cells}
            if any(r < 0 or r >= h or c < 0 or c >= w for r, c in shifted):
                break
            if any(out[r][c] != background for r, c in shifted):
                break
            dy += dr
            dx += dc
        for r, c in cells:
            out[r + dy][c + dx] = obj.color
    return tuple(tuple(row) for row in out)


def connect_aligned_objects(grid: Grid, color_policy: str = "same",
                            background: int | None = None) -> Grid:
    """Fill gaps between row/column-aligned objects under a fixed color policy."""
    if color_policy not in {"same", "first", "second"}:
        raise ValueError(f"unknown connection color policy: {color_policy}")
    if background is None:
        background = infer_background(grid)
    objects = extract_objects(grid, background_color=background)
    out = [list(row) for row in grid]
    lines: dict[tuple[int, int], set[int]] = {}
    for i, first in enumerate(objects):
        for second in objects[i + 1:]:
            if color_policy == "same" and first.color != second.color:
                continue
            color = (first.color if color_policy in {"same", "first"}
                     else second.color)
            shared_rows = sorted({r for r, _ in first.cells} & {r for r, _ in second.cells})
            shared_cols = sorted({c for _, c in first.cells} & {c for _, c in second.cells})
            options = []
            for r in shared_rows:
                for ca in (c for rr, c in first.cells if rr == r):
                    for cb in (c for rr, c in second.cells if rr == r):
                        if abs(ca - cb) > 1:
                            options.append((abs(ca - cb) - 1, r,
                                            min(ca, cb), max(ca, cb), "horizontal"))
            for c in shared_cols:
                for ra in (r for r, cc in first.cells if cc == c):
                    for rb in (r for r, cc in second.cells if cc == c):
                        if abs(ra - rb) > 1:
                            options.append((abs(ra - rb) - 1, c,
                                            min(ra, rb), max(ra, rb), "vertical"))
            if not options:
                continue
            _, fixed, low, high, orientation = min(options)
            cells = (((fixed, p) for p in range(low + 1, high))
                     if orientation == "horizontal"
                     else ((p, fixed) for p in range(low + 1, high)))
            for point in cells:
                lines.setdefault(point, set()).add(color)
    for (r, c), colors in lines.items():
        if len(colors) > 1:
            raise ValueError("aligned connections assign conflicting colors")
        color = next(iter(colors))
        if out[r][c] not in (background, color):
            raise ValueError("aligned connection overwrites an object")
        out[r][c] = color
    return tuple(tuple(row) for row in out)


def connect_nearest_objects(grid: Grid, route: str = "horizontal-first",
                            color_policy: str = "same", background: int | None = None) -> Grid:
    """Connect the unique nearest object pair by one of two shortest L routes."""
    if route not in {"horizontal-first", "vertical-first"}:
        raise ValueError(f"unknown connection route: {route}")
    if color_policy not in {"same", "first", "second"}:
        raise ValueError(f"unknown connection color policy: {color_policy}")
    if background is None:
        background = infer_background(grid)
    objects = extract_objects(grid, background_color=background)
    options = []
    for i, first in enumerate(objects):
        for j in range(i + 1, len(objects)):
            second = objects[j]
            if color_policy == "same" and first.color != second.color:
                continue
            for a in first.cells:
                for b in second.cells:
                    distance = abs(a[0] - b[0]) + abs(a[1] - b[1])
                    options.append((distance, i, j, a, b))
    if not options:
        return grid
    minimum = min(option[0] for option in options)
    closest = [option for option in options if option[0] == minimum]
    object_pairs = {(option[1], option[2]) for option in closest}
    if len(object_pairs) != 1:
        raise ValueError("nearest object pair is ambiguous")
    if len(closest) != 1:
        raise ValueError("nearest endpoint correspondence is ambiguous")
    distance, first_index, second_index, first_cell, second_cell = closest[0]
    if distance <= 1:
        return grid
    first, second = objects[first_index], objects[second_index]
    color = (first.color if color_policy in {"same", "first"}
             else second.color)
    r1, c1 = first_cell
    r2, c2 = second_cell
    path = []
    if route == "horizontal-first":
        step = 1 if c2 > c1 else -1
        path.extend((r1, c) for c in range(c1 + step, c2 + step, step))
        step = 1 if r2 > r1 else -1
        path.extend((r, c2) for r in range(r1 + step, r2, step))
    else:
        step = 1 if r2 > r1 else -1
        path.extend((r, c1) for r in range(r1 + step, r2 + step, step))
        step = 1 if c2 > c1 else -1
        path.extend((r2, c) for c in range(c1 + step, c2, step))
    out = [list(row) for row in grid]
    for r, c in path:
        if out[r][c] != background:
            raise ValueError("nearest-object path crosses an occupied cell")
        out[r][c] = color
    return tuple(tuple(row) for row in out)


def extend_lines_to_edge(grid: Grid, background: int | None = None) -> Grid:
    """Extend every length-two-or-more monochrome row/column run to its edges."""
    if background is None:
        background = infer_background(grid)
    lines: dict[tuple[int, int], set[int]] = {}
    h, w = len(grid), len(grid[0])
    for r in range(h):
        start = 0
        while start < w:
            color = grid[r][start]
            end = start + 1
            while color != background and end < w and grid[r][end] == color:
                end += 1
            if color != background and end - start >= 2:
                for c in range(w):
                    lines.setdefault((r, c), set()).add(color)
            start = end
    for c in range(w):
        start = 0
        while start < h:
            color = grid[start][c]
            end = start + 1
            while color != background and end < h and grid[end][c] == color:
                end += 1
            if color != background and end - start >= 2:
                for r in range(h):
                    lines.setdefault((r, c), set()).add(color)
            start = end
    out = [list(row) for row in grid]
    for (r, c), colors in lines.items():
        if len(colors) > 1:
            raise ValueError("horizontal/vertical line extensions conflict")
        color = next(iter(colors))
        if out[r][c] not in (background, color):
            raise ValueError("line extension overwrites a different color")
        out[r][c] = color
    return tuple(tuple(row) for row in out)


def transform_objects_by_signature(
        grid: Grid, transforms: dict[tuple, tuple[int, int, int]]) -> Grid:
    """Apply inferred (dy, dx, output-color) rules keyed by color and shape."""
    from .objects import describe_object
    out_objects = []
    for component in connected_components(grid):
        top_left = min(component)
        color = grid[top_left[0]][top_left[1]]
        source = describe_object(color, component)
        key = (color, object_shape_signature(source))
        if key not in transforms:
            raise ValueError("no signature-matched transform for an input object")
        dy, dx, output_color = transforms[key]
        moved = {(r + dy, c + dx) for r, c in component}
        if any(not (0 <= r < len(grid) and 0 <= c < len(grid[0]))
               for r, c in moved):
            raise ValueError("signature-moved object exceeds grid bounds")
        out_objects.append(describe_object(output_color, moved))
    return render_objects(out_objects, len(grid), len(grid[0]))


def recolor(grid: Grid, mapping: dict[int, int]) -> Grid:
    if any(not (0 <= a <= 9 and 0 <= b <= 9) for a, b in mapping.items()):
        raise ValueError("colors must be between 0 and 9")
    return tuple(tuple(mapping.get(value, value) for value in row) for row in grid)


def recolor_by_palette_rank(grid: Grid, rank_mapping: dict[int, int],
                            measure: str = "cells") -> Grid:
    """Map each color's frequency/object-count rank to another input palette role."""
    palette = {value for row in grid for value in row}
    if measure == "cells":
        values = {color: sum(cell == color for row in grid for cell in row)
                  for color in palette}
    elif measure == "objects":
        from .objects import connected_components
        values = {color: (0 if color == 0 else
                          len(connected_components(grid, color=color)))
                  for color in palette}
    else:
        raise ValueError(f"unknown palette rank measure: {measure}")
    ordered = sorted(palette, key=lambda color: (-values[color], color))
    rank_to_color = {rank: color for rank, color in enumerate(ordered)}
    output_map = {color: rank_to_color.get(rank_mapping.get(rank, rank), color)
                  for rank, color in enumerate(ordered)}
    return recolor(grid, output_map)


def intersect(a: Grid, b: Grid, background: int = 0) -> Grid:
    if (len(a), len(a[0])) != (len(b), len(b[0])):
        raise ValueError("intersection requires equal dimensions")
    return tuple(tuple(x if x == y and x != background else background
                       for x, y in zip(ra, rb)) for ra, rb in zip(a, b))


def subtract(a: Grid, b: Grid, background: int = 0) -> Grid:
    if (len(a), len(a[0])) != (len(b), len(b[0])):
        raise ValueError("subtraction requires equal dimensions")
    return tuple(tuple(x if y == background else background
                       for x, y in zip(ra, rb)) for ra, rb in zip(a, b))


def overlay(base: Grid, foreground: Grid, background: int = 0) -> Grid:
    if (len(base), len(base[0])) != (len(foreground), len(foreground[0])):
        raise ValueError("overlay requires equal dimensions")
    return tuple(tuple(y if y != background else x for x, y in zip(ra, rb))
                 for ra, rb in zip(base, foreground))


def mask(grid: Grid, mask_grid: Grid, background: int = 0) -> Grid:
    if (len(grid), len(grid[0])) != (len(mask_grid), len(mask_grid[0])):
        raise ValueError("mask requires equal dimensions")
    return tuple(tuple(x if m != background else background
                       for x, m in zip(ra, rb)) for ra, rb in zip(grid, mask_grid))


def split_on_separator(grid: Grid, axis: str) -> tuple[Grid, ...]:
    """Split on complete, solid non-background rows or columns."""
    if axis == "horizontal":
        dividers = [r for r, row in enumerate(grid)
                    if row[0] != 0 and all(value == row[0] for value in row)]
        segments = []
        start = 0
        for divider in dividers:
            if divider > start:
                segments.append(tuple(grid[start:divider]))
            start = divider + 1
        if start < len(grid):
            segments.append(tuple(grid[start:]))
        return tuple(segments) if dividers else ()
    if axis == "vertical":
        width = len(grid[0])
        dividers = [c for c in range(width)
                    if grid[0][c] != 0 and all(row[c] == grid[0][c] for row in grid)]
        segments = []
        start = 0
        for divider in dividers:
            if divider > start:
                segments.append(tuple(tuple(row[start:divider]) for row in grid))
            start = divider + 1
        if start < width:
            segments.append(tuple(tuple(row[start:]) for row in grid))
        return tuple(segments) if dividers else ()
    raise ValueError("separator axis must be horizontal or vertical")


def combine_regions(a: Grid, b: Grid, operation: str,
                    background: int = 0) -> Grid:
    if (len(a), len(a[0])) != (len(b), len(b[0])):
        raise ValueError("region combination requires equal dimensions")
    out = []
    for row_a, row_b in zip(a, b):
        row = []
        for x, y in zip(row_a, row_b):
            if operation == "union":
                if x != background and y != background and x != y:
                    raise ValueError("overlapping regions contain different colors")
                row.append(x if x != background else y)
            elif operation == "intersection":
                row.append(x if x == y and x != background else background)
            elif operation == "xor":
                if x != background and y != background and x != y:
                    raise ValueError("xor overlap contains different colors")
                row.append(background if x != background and y != background
                           else x if x != background else y)
            elif operation == "subtract-left":
                row.append(x if y == background else background)
            elif operation == "subtract-right":
                row.append(y if x == background else background)
            else:
                raise ValueError(f"unknown region operation: {operation}")
        out.append(tuple(row))
    return tuple(out)


def count(grid: Grid, mode: str = "cells", color: int | None = None) -> int:
    if mode == "cells":
        return sum(1 for row in grid for value in row
                   if value != 0 and (color is None or value == color))
    if mode == "objects":
        return sum(1 for component in connected_components(grid)
                   if color is None or grid[min(component)[0]][min(component)[1]] == color)
    if mode == "colors":
        return len({value for row in grid for value in row if value != 0
                    and (color is None or value == color)})
    if mode == "color_cells":
        if color is None:
            raise ValueError("color_cells mode requires color")
        return sum(value == color for row in grid for value in row)
    raise ValueError(f"unknown count mode: {mode}")


def order_objects(objects: Iterable[ArcObject], key: str = "top_left",
                  reverse: bool = False) -> tuple[ArcObject, ...]:
    keys: dict[str, Callable[[ArcObject], Any]] = {
        "top_left": lambda o: (o.bbox[0], o.bbox[1]),
        "area": lambda o: len(o.cells), "color": lambda o: o.color,
        "width": lambda o: o.width, "height": lambda o: o.height,
        "centroid": lambda o: o.centroid,
    }
    if key not in keys:
        raise ValueError(f"unknown object ordering key: {key}")
    return tuple(sorted(objects, key=keys[key], reverse=reverse))


def render_objects(objects: Iterable[ArcObject], height: int, width: int,
                   background: int = 0) -> Grid:
    out = [list(row) for row in make_grid(height, width, background)]
    for obj in objects:
        for r, c in sorted(obj.cells):
            if 0 <= r < height and 0 <= c < width:
                out[r][c] = obj.color
    return tuple(tuple(row) for row in out)


def move_objects(grid: Grid, dy: int, dx: int, background: int = 0) -> Grid:
    objects = []
    for component in connected_components(grid):
        r, c = min(component)
        objects.append(describe_object(grid[r][c],
                                       ((rr + dy, cc + dx) for rr, cc in component)))
    return render_objects(objects, len(grid), len(grid[0]), background)


def grow(grid: Grid, iterations: int = 1, connectivity: int = 4) -> Grid:
    if iterations < 0 or connectivity not in (4, 8):
        raise ValueError("iterations must be nonnegative and connectivity 4 or 8")
    current = [list(row) for row in grid]
    h, w = len(grid), len(grid[0])
    offsets = [(r, c) for r in (-1, 0, 1) for c in (-1, 0, 1)
               if (r or c) and (connectivity == 8 or abs(r) + abs(c) == 1)]
    for _ in range(iterations):
        additions: dict[tuple[int, int], set[int]] = {}
        for r in range(h):
            for c in range(w):
                color = current[r][c]
                if color == 0:
                    continue
                for dr, dc in offsets:
                    rr, cc = r + dr, c + dc
                    if 0 <= rr < h and 0 <= cc < w and current[rr][cc] == 0:
                        additions.setdefault((rr, cc), set()).add(color)
        for (r, c), candidates in additions.items():
            if len(candidates) == 1:
                current[r][c] = next(iter(candidates))
    return tuple(tuple(row) for row in current)


def split_object(grid: Grid, connectivity: int = 4) -> tuple[ArcObject, ...]:
    return tuple(describe_object(grid[min(cells)[0]][min(cells)[1]], cells)
                 for cells in connected_components(grid, connectivity=connectivity))


def merge_objects(objects: Iterable[ArcObject], height: int, width: int,
                  background: int = 0) -> Grid:
    return render_objects(objects, height, width, background)


def relative_position(a: ArcObject, b: ArcObject) -> str:
    from .objects import relative_position as _relative_position
    return _relative_position(a, b)


def coordinate_transform(point: tuple[int, int], height: int, width: int,
                         operation: str) -> tuple[int, int, int, int]:
    """Map a cell coordinate and return (row, column, out_height, out_width)."""
    r, c = point
    if not (0 <= r < height and 0 <= c < width):
        raise ValueError("point is outside the source grid")
    if operation == "identity":
        return r, c, height, width
    if operation == "reflect_horizontal":
        return height - 1 - r, c, height, width
    if operation == "reflect_vertical":
        return r, width - 1 - c, height, width
    if operation == "rotate90":
        return c, height - 1 - r, width, height
    if operation == "rotate180":
        return height - 1 - r, width - 1 - c, height, width
    if operation == "rotate270":
        return width - 1 - c, r, width, height
    raise ValueError(f"unknown coordinate transform: {operation}")


def complete_pattern(grid: Sequence[Sequence[int | None]]) -> tuple[tuple[int, ...], ...]:
    """Fill None cells using the shortest row period consistent with known cells."""
    if not grid or not grid[0] or any(len(row) != len(grid[0]) for row in grid):
        raise ValueError("pattern must be a nonempty rectangle")
    result = []
    for row in grid:
        width = len(row)
        period = next((p for p in range(1, width + 1)
                       if all(row[i] is None or row[j] is None or row[i] == row[j]
                              for i in range(width) for j in range(width)
                              if i % p == j % p)), None)
        if period is None:
            raise ValueError("no periodic completion is consistent with known cells")
        values: list[int | None] = [None] * period
        for i, value in enumerate(row):
            if value is not None:
                slot = i % period
                if values[slot] is not None and values[slot] != value:
                    raise ValueError("inconsistent periodic row")
                values[slot] = value
        if any(value is None for value in values):
            raise ValueError("insufficient known cells to infer the row period")
        result.append(tuple(int(values[i % period]) for i in range(width)))
    return tuple(result)

"""Bounded, evidence-guided composition search for ARC grid programs."""

from __future__ import annotations

from collections import Counter
from dataclasses import dataclass
from time import perf_counter
from typing import Callable

from .grid import Grid, dimensions
from .deltas import compare_grids
from .objects import extract_objects
from .primitives import (
    combine_regions, complete_symmetry, connect_aligned_objects,
    connect_nearest_objects, crop_color, crop_non_background,
    extend_lines_to_edge, fill_enclosed_background, gravity,
    object_bounding_boxes, object_feature, object_outlines,
    recolor_objects_by_feature, reflect_horizontal, reflect_vertical, rotate,
    scale, select_objects, split_on_separator, tile, transform_each_object,
)
from .rules import (
    Rule, _local_rewrite_rule, _mapping_rule,
    _object_correspondence_rule, _palette_rank_rule,
)


Transform = Callable[[Grid], Grid]


@dataclass(frozen=True)
class Operator:
    name: str
    apply: Transform
    complexity: int
    assumptions: int
    family: str
    known_colors: tuple[int, ...] = ()
    relation_predicates: tuple[str, ...] = ()
    local_writes: int = 0


@dataclass(frozen=True)
class Node:
    outputs: tuple[Grid, ...]
    program: tuple[Operator, ...]

    @property
    def cost(self) -> int:
        return sum(operator.complexity for operator in self.program)

    @property
    def assumptions(self) -> int:
        return sum(operator.assumptions for operator in self.program)

    @property
    def name(self) -> str:
        return " -> ".join(operator.name for operator in self.program)


def _operator_library(pairs: tuple[tuple[Grid, Grid], ...]) -> list[Operator]:
    operators: list[Operator] = []
    deltas = tuple(compare_grids(source, target) for source, target in pairs)
    dimensions_change = any(delta.dimensions_changed for delta in deltas)
    same_dimensions = all(not delta.dimensions_changed for delta in deltas)
    has_additions = any(delta.added_cells for delta in deltas)
    has_changes = any(delta.changed_cell_count for delta in deltas)
    selection_plausible = any(
        len(extract_objects(target)) < len(extract_objects(source)) or
        sum(value != 0 for row in target for value in row) <
        sum(value != 0 for row in source for value in row)
        for source, target in pairs)
    palette_reduced = any(
        {value for row in target for value in row} <
        {value for row in source for value in row}
        for source, target in pairs)

    def add(name, apply, complexity=2, assumptions=1, family="primitive",
            known_colors=(), relation_predicates=(), local_writes=0):
        operators.append(Operator(name, apply, complexity, assumptions,
                                  family, tuple(sorted(set(known_colors))),
                                  tuple(relation_predicates), local_writes))

    core_geometry = (
        ("reflect-horizontal", reflect_horizontal, 2),
        ("reflect-vertical", reflect_vertical, 2),
        ("reflect-both-axes", lambda g: reflect_vertical(reflect_horizontal(g)), 3),
        ("rotate-90", lambda g: rotate(g, 1), 2),
        ("rotate-180", lambda g: rotate(g, 2), 2),
        ("rotate-270", lambda g: rotate(g, 3), 2),
    )
    for name, fn, cost in core_geometry:
        add(name, fn, cost, family="grid-transform")
    if dimensions_change:
        add("crop-non-background", crop_non_background, 2,
            family="grid-transform")
    if has_additions:
        for name, fn, cost in (
                ("fill-enclosed", fill_enclosed_background, 3),
                ("fill-object-bboxes", object_bounding_boxes, 3),
                ("object-outlines", object_outlines, 3),
                ("extend-lines-to-edge", extend_lines_to_edge, 4)):
            add(name, fn, cost, family="object-construction")

    if has_additions:
        for axis in ("vertical", "horizontal", "diagonal", "antidiagonal"):
            add(f"complete-symmetry({axis})",
                lambda g, axis=axis: complete_symmetry(g, axis), 3,
                family="symmetry")
    if same_dimensions and has_changes:
        for direction in ("up", "down", "left", "right"):
            add(f"gravity-{direction}",
                lambda g, direction=direction: gravity(g, direction), 4,
                family="object-movement")
    if selection_plausible:
        for selector in ("largest", "smallest", "unique-size", "unique-shape",
                         "most-frequent-color", "least-frequent-color", "symmetric",
                         "asymmetric", "horizontal", "vertical", "square", "point",
                         "wide", "tall"):
            add(f"select-objects({selector})",
                lambda g, selector=selector: select_objects(g, selector), 3,
                family=f"object-selection-{selector}")
    if same_dimensions:
        for operation in ("reflect-horizontal", "reflect-vertical", "rotate-90",
                          "rotate-180", "rotate-270"):
            add(f"transform-each-object({operation})",
                lambda g, operation=operation: transform_each_object(g, operation),
                4, family="object-transform")
    if has_additions:
        for policy in ("same", "first", "second"):
            add(f"connect-aligned({policy})",
                lambda g, policy=policy: connect_aligned_objects(g, policy),
                5, assumptions=2, family="object-relations")
            for route in ("horizontal-first", "vertical-first"):
                add(f"connect-nearest({route},{policy})",
                    lambda g, route=route, policy=policy:
                    connect_nearest_objects(g, route, policy),
                    7, assumptions=3, family="object-relations")

        # Relation-conditioned copy/place is a terminal hypothesis, not an
        # intermediate operator. It is generated only in _terminal_rules.

    colors = sorted({value for source, _ in pairs for row in source for value in row
                     if value != 0})
    if selection_plausible or palette_reduced:
        for color in colors:
            add(f"keep-color({color})",
                lambda g, color=color: tuple(tuple(value if value == color else 0
                                                    for value in row) for row in g),
                2, family="object-selection", known_colors=(color,))
            add(f"crop-color({color})",
                lambda g, color=color: crop_color(g, color), 3,
                family="object-selection", known_colors=(color,))
    if has_additions:
        for color in colors:
            add(f"fill-holes({color})",
                lambda g, color=color: fill_enclosed_background(g, color), 3,
                family="topology", known_colors=(color,))

    # Dimension factors are capped; the search only uses factors visible in
    # demonstration input/output dimensions or the common small ARC factors.
    factors = set()
    if dimensions_change:
        for source, target in pairs:
            sh, sw = dimensions(source)
            th, tw = dimensions(target)
            if sh and th % sh == 0 and 1 < th // sh <= 4:
                factors.add(th // sh)
            if sw and tw % sw == 0 and 1 < tw // sw <= 4:
                factors.add(tw // sw)
        factors.update({2, 3})
    for sy in sorted(factors):
        for sx in sorted(factors):
            if sy * sx > 9:
                continue
            add(f"scale({sy},{sx})", lambda g, sy=sy, sx=sx: scale(g, sy, sx),
                2 + sy + sx, family="scaling")
            add(f"tile({sy},{sx})", lambda g, sy=sy, sx=sx: tile(g, sy, sx),
                3 + sy + sx, family="tiling")

    if dimensions_change:
      for axis in ("horizontal", "vertical"):
        for operation in ("union", "intersection", "xor",
                          "subtract-left", "subtract-right"):
            def combine(grid: Grid, axis=axis, operation=operation) -> Grid:
                regions = split_on_separator(grid, axis)
                if len(regions) != 2:
                    raise ValueError("expected two regions around a separator")
                return combine_regions(regions[0], regions[1], operation)
            add(f"split-{axis}-{operation}", combine, 4,
                assumptions=2, family="region-combination")
    return operators


def _grid_loss(outputs: tuple[Grid, ...], targets: tuple[Grid, ...]) -> int:
    total = 0
    for output, target in zip(outputs, targets):
        oh, ow = dimensions(output)
        th, tw = dimensions(target)
        total += 30 * (abs(oh - th) + abs(ow - tw))
        total += sum(output[row][col] != target[row][col]
                     for row in range(min(oh, th))
                     for col in range(min(ow, tw)))
        out_counts = Counter(value for row in output for value in row if value)
        target_counts = Counter(value for row in target for value in row if value)
        total += 2 * sum(abs(out_counts[color] - target_counts[color])
                         for color in set(out_counts) | set(target_counts))
    return total


def _feature_recolor_rule(pairs: tuple[tuple[Grid, Grid], ...]) -> Rule | None:
    for feature in ("size", "shape", "orientation", "symmetry", "dimensions"):
        mapping = {}
        consistent = True
        for source, target in pairs:
            if dimensions(source) != dimensions(target):
                consistent = False
                break
            for obj in extract_objects(source):
                colors = {target[row][col] for row, col in obj.cells}
                if len(colors) != 1:
                    consistent = False
                    break
                key, color = object_feature(obj, feature), next(iter(colors))
                if key in mapping and mapping[key] != color:
                    consistent = False
                    break
                mapping[key] = color
            if not consistent:
                break
        if consistent and mapping:
            transform = lambda grid, mapping=mapping, feature=feature: \
                recolor_objects_by_feature(grid, mapping, feature)
            return Rule(f"recolor-objects-by-{feature}", transform, 4,
                        assumptions=1, family="object-recolor")
    return None


def _terminal_rules(outputs: tuple[Grid, ...], targets: tuple[Grid, ...]) -> list[Rule]:
    pairs = tuple(zip(outputs, targets))
    terminals = []
    mapping = _mapping_rule(pairs, lambda grid: grid, "global-color-map", 2)
    if mapping:
        terminals.append(mapping)
    for measure in ("cells", "objects"):
        palette = _palette_rank_rule(pairs, measure, lambda grid: grid,
                                     f"palette-role-{measure}")
        if palette:
            terminals.append(palette)
    for factory in (_feature_recolor_rule, _object_correspondence_rule):
        rule = factory(pairs)
        if rule:
            terminals.append(rule)
    from .relations import generate_relation_copy_hypotheses
    # Limit relation hypotheses in search to avoid combinatorial explosion.
    # They are end-to-end rules; using many as terminals bloats search.
    terminals.extend(generate_relation_copy_hypotheses(pairs, max_hypotheses=16))
    for radius in (1, 2):
        local = _local_rewrite_rule(pairs, radius)
        if local:
            terminals.append(local)
    return terminals


def _compose_rule(program: tuple[Operator, ...],
                  terminal: Rule | None = None) -> Rule:
    operations = tuple(program)
    names = [op.name for op in operations]
    if terminal:
        names.append(terminal.name)
    complexity = sum(op.complexity for op in operations)
    assumptions = sum(op.assumptions for op in operations)
    known_colors = {color for op in operations for color in op.known_colors}
    relation_predicates = tuple(dict.fromkeys(
        predicate for op in operations for predicate in op.relation_predicates))
    local_writes = sum(op.local_writes for op in operations)
    family = "program-search"
    if terminal:
        complexity += terminal.complexity
        assumptions += terminal.assumptions
        known_colors.update(terminal.known_colors)
        relation_predicates += tuple(predicate for predicate in
                                     terminal.relation_predicates
                                     if predicate not in relation_predicates)
        local_writes += terminal.local_writes

    def apply(grid: Grid, operations=operations, terminal=terminal) -> Grid:
        result = grid
        for op in operations:
            result = op.apply(result)
        return terminal.apply(result) if terminal else result

    return Rule("program: " + " -> ".join(names), apply,
                complexity, assumptions, family=family,
                structural_coverage=len(names),
                known_colors=tuple(sorted(known_colors)),
                relation_predicates=relation_predicates,
                local_writes=local_writes)


def _select_beam(nodes: list[Node], targets: tuple[Grid, ...],
                 width: int) -> list[Node]:
    unique: dict[tuple[Grid, ...], Node] = {}
    for node in nodes:
        previous = unique.get(node.outputs)
        if previous is None or (node.cost, node.assumptions, node.name) < (
                previous.cost, previous.assumptions, previous.name):
            unique[node.outputs] = node
    ordered = sorted(unique.values(), key=lambda node: (
        _grid_loss(node.outputs, targets), node.cost,
        node.assumptions, node.name))
    family_counts: Counter[str] = Counter()
    selected = []
    family_limit = max(3, width // 4)
    for node in ordered:
        family = node.program[-1].family if node.program else "input"
        if family_counts[family] >= family_limit:
            continue
        selected.append(node)
        family_counts[family] += 1
        if len(selected) == width:
            break
    return selected


def discover_compositions(
        pairs: tuple[tuple[Grid, Grid], ...],
        max_depth: int = 3,
        beam_width: int = 32,
        max_returned: int = 12) -> tuple[list[Rule], dict]:
    """Search short typed-ish grid programs, then leave acceptance to replay."""
    started = perf_counter()
    targets = tuple(target for _, target in pairs)
    source_state = tuple(source for source, _ in pairs)
    operators = _operator_library(pairs)
    beam = [Node(source_state, ())]
    visited_beam_states = {source_state}
    stats = {"triggered": True, "max_depth": max_depth,
             "depth_reached": 0,
             "beam_width": beam_width, "operator_count": len(operators),
             "state_expansions": 0, "candidate_states_by_depth": {},
             "unique_states_by_depth": {},
             "exact_programs_by_depth": {},
             "exact_programs_found": 0, "emitted_partial_programs": 0,
             "termination": "max_depth", "terminated_on_exact": False}
    all_exact_rules: dict[str, Rule] = {}

    for depth in range(1, max_depth + 1):
        stats["depth_reached"] = depth
        next_by_family: dict[str, dict[tuple[Grid, ...], Node]] = {}
        exact_rules = []
        family_limit = max(2, beam_width // 4)
        for node in beam:
            if len(node.program) + 1 <= max_depth:
                for terminal in _terminal_rules(node.outputs, targets):
                    try:
                        predicted = tuple(terminal.apply(grid) for grid in node.outputs)
                    except (ArithmeticError, IndexError, TypeError, ValueError):
                        continue
                    if predicted == targets:
                        program = _compose_rule(node.program, terminal)
                        if program.name not in all_exact_rules:
                            exact_rules.append(program)
                            all_exact_rules[program.name] = program
            if len(node.program) >= max_depth:
                continue
            for operator in operators:
                stats["state_expansions"] += 1
                try:
                    outputs = tuple(operator.apply(grid) for grid in node.outputs)
                except (ArithmeticError, IndexError, TypeError, ValueError):
                    continue
                if outputs == node.outputs:
                    continue
                program = node.program + (operator,)
                if outputs == targets:
                    candidate = _compose_rule(program)
                    if candidate.name not in all_exact_rules:
                        exact_rules.append(candidate)
                        all_exact_rules[candidate.name] = candidate
                    continue
                if outputs in visited_beam_states:
                    continue
                candidate = Node(outputs, program)
                family_nodes = next_by_family.setdefault(operator.family, {})
                previous = family_nodes.get(outputs)
                if previous is None or (candidate.cost, candidate.assumptions,
                                        candidate.name) < (
                        previous.cost, previous.assumptions, previous.name):
                    family_nodes[outputs] = candidate
                # Keep a small per-family reservoir while expanding instead
                # of retaining every beam x operator state until layer end.
                if len(family_nodes) > 2 * family_limit:
                    ordered_family = sorted(family_nodes.values(), key=lambda item: (
                        _grid_loss(item.outputs, targets), item.cost,
                        item.assumptions, item.name))
                    family_nodes.clear()
                    family_nodes.update((item.outputs, item)
                                        for item in ordered_family[:family_limit])
        if exact_rules:
            stats["exact_programs_by_depth"][str(depth)] = len(exact_rules)
        next_nodes = [node for family_nodes in next_by_family.values()
                      for node in family_nodes.values()]
        stats["candidate_states_by_depth"][str(depth)] = len(next_nodes)
        beam = _select_beam(next_nodes, targets, beam_width)
        visited_beam_states.update(node.outputs for node in beam)
        stats["unique_states_by_depth"][str(depth)] = len(beam)
        if not beam:
            stats["termination"] = ("frontier_exhausted_after_exact"
                                     if all_exact_rules else "empty_frontier")
            break

    if all_exact_rules:
        exact_rules = sorted(all_exact_rules.values(), key=lambda rule: (
            rule.complexity, rule.assumptions, -rule.structural_coverage,
            rule.name))
        stats["exact_programs_found"] = len(exact_rules)
        stats["first_exact_depth"] = min(map(int,
                                             stats["exact_programs_by_depth"]))
        stats["terminated_on_exact"] = True
        if stats["termination"] == "max_depth":
            stats["termination"] = "max_depth_after_exact"
        stats["elapsed_seconds"] = round(perf_counter() - started, 6)
        return exact_rules[:max_returned], stats

    partial_rules = [_compose_rule(node.program) for node in beam if node.program]
    partial_rules.sort(key=lambda rule: (rule.complexity, rule.assumptions,
                                        rule.name))
    stats["emitted_partial_programs"] = min(len(partial_rules), max_returned)
    stats["elapsed_seconds"] = round(perf_counter() - started, 6)
    return partial_rules[:max_returned], stats

"""Role-based object relations and relation-conditioned copy placement."""

from __future__ import annotations

from collections import Counter, defaultdict
from dataclasses import dataclass, field
from itertools import combinations, permutations
from typing import Iterable

from .deltas import compare_grids
from .grid import Grid, infer_background
from .objects import (ArcObject, extract_objects, normalized_shape,
                      left_of, right_of, above, below, same_row, same_column,
                      between, vertically_between, nth_from_left, nth_from_right,
                      nth_from_top, nth_from_bottom, manhattan_distance,
                      nearest_to, farthest_from, same_distance, same_relative_position,
                      relative_offset, aligned_with, compute_relational_signature)
from .rules import Rule


Selector = tuple

# ============================================================
# RELATIONAL PREDICATE FUNCTIONS (re-exported from objects)
# ============================================================

# These are now imported from objects module
# left_of, right_of, above, below, same_row, same_column
# between, vertically_between, nth_from_left, nth_from_right
# nth_from_top, nth_from_bottom, manhattan_distance, chebyshev_distance
# euclidean_distance, nearest_to, farthest_from, same_distance
# closest_to_corner, closest_to_edge, same_relative_position
# relative_offset, aligned_with, compute_relational_signature

# ============================================================
# RELATION GRAPH STRUCTURES
# ============================================================

@dataclass(frozen=True)
class RelationEdge:
    """Explicit relation between two objects with quantitative attributes."""
    source_id: int
    target_id: int
    predicate: str
    attributes: dict = field(default_factory=dict)  # e.g., {"offset": (dy, dx), "distance": 3.5}


@dataclass(frozen=True)
class RelationGraph:
    """Explicit graph of objects and their relations."""
    objects: tuple[ArcObject, ...]
    edges: tuple[RelationEdge, ...]
    # Index for fast lookup
    _edges_by_source: dict[int, list[RelationEdge]] = field(default_factory=dict, init=False)
    _edges_by_target: dict[int, list[RelationEdge]] = field(default_factory=dict, init=False)
    _edges_by_predicate: dict[str, list[RelationEdge]] = field(default_factory=dict, init=False)

    def __post_init__(self):
        # Build indices
        for edge in self.edges:
            self._edges_by_source.setdefault(edge.source_id, []).append(edge)
            self._edges_by_target.setdefault(edge.target_id, []).append(edge)
            self._edges_by_predicate.setdefault(edge.predicate, []).append(edge)

    def outgoing(self, obj_id: int) -> list[RelationEdge]:
        return self._edges_by_source.get(obj_id, [])

    def incoming(self, obj_id: int) -> list[RelationEdge]:
        return self._edges_by_target.get(obj_id, [])

    def by_predicate(self, predicate: str) -> list[RelationEdge]:
        return self._edges_by_predicate.get(predicate, [])


# ============================================================
# ROLE DISAMBIGUATION STRUCTURES
# ============================================================

@dataclass(frozen=True)
class RoleBinding:
    """Explicit role assignment for an object."""
    object_id: int
    role: str  # "source", "landmark", "landmark_b", "anchor", "target", etc.
    selector: Selector  # The selector that uniquely identifies this object
    confidence: float  # Based on selector uniqueness, relational evidence


@dataclass(frozen=True)
class CandidateProgram:
    """A complete candidate with role bindings and transformation."""
    role_bindings: tuple[RoleBinding, ...]
    transformation_family: str  # "copy_onto_marker", "align_bbox", "between", etc.
    placement_params: tuple  # Specific placement parameters
    color_policy: str  # "source" or "landmark"
    transformation_fn: callable  # The actual transformation function
    # Evidence across training examples
    training_evidence: dict[int, bool] = field(default_factory=dict)  # example_idx -> pass/fail
    invariance_evidence: dict[str, bool] = field(default_factory=dict)  # perturbation -> pass/fail
    # Scoring components
    parsimony_score: int = 0
    relational_evidence_score: float = 0.0
    cross_example_consistency: float = 0.0
    invariance_score: int = 0


def build_relation_graph(objects: list[ArcObject]) -> RelationGraph:
    """Build explicit relation graph from objects."""
    edges = []
    for i, obj_a in enumerate(objects):
        for j, obj_b in enumerate(objects):
            if i == j:
                continue
            relations = object_relations(obj_a, obj_b)
            for rel in relations:
                attrs = {}
                if rel in ("offset_by", "offset_by_vector"):
                    dy = obj_b.centroid[0] - obj_a.centroid[0]
                    dx = obj_b.centroid[1] - obj_a.centroid[1]
                    attrs["offset"] = (dy, dx)
                elif rel in ("nearest", "farthest"):
                    dy = obj_b.centroid[0] - obj_a.centroid[0]
                    dx = obj_b.centroid[1] - obj_a.centroid[1]
                    attrs["distance"] = (dy * dy + dx * dx) ** 0.5
                elif rel in ("aligned_x", "aligned_y", "same_row", "same_column"):
                    attrs["axis"] = "x" if rel in ("aligned_x", "same_column") else "y"
                edges.append(RelationEdge(i, j, rel, attrs))
    return RelationGraph(tuple(objects), tuple(edges))


# Phase 3: ROLE DISAMBIGUATION - Generate candidate bindings
def generate_role_candidates(objects: list[ArcObject], 
                             source_color: int | None = None,
                             landmark_color: int | None = None) -> dict[str, list[RoleBinding]]:
    """
    For each potential role, generate ALL candidate objects that could fill it.
    Returns dict of role -> list of candidate RoleBindings.
    """
    candidates = defaultdict(list)

    for obj_id, obj in enumerate(objects):
        # Generate all selectors that uniquely identify this object
        selectors = _selector_specs(objects, obj)
        for selector in selectors:
            # Determine potential roles based on object properties and selector type
            kind = selector[0]

            # Source candidates: objects that could be copied
            if source_color is None or obj.color == source_color:
                candidates["source"].append(RoleBinding(
                    object_id=obj_id,
                    role="source",
                    selector=selector,
                    confidence=_compute_role_confidence(obj, "source", objects, selector)
                ))

            # Landmark candidates: objects that could serve as reference
            if landmark_color is None or obj.color == landmark_color:
                candidates["landmark"].append(RoleBinding(
                    object_id=obj_id,
                    role="landmark",
                    selector=selector,
                    confidence=_compute_role_confidence(obj, "landmark", objects, selector)
                ))

            # Anchor candidates: unique, stable reference points
            if kind in ("unique-color", "unique-shape", "unique-size", "point", "largest", "smallest"):
                candidates["anchor"].append(RoleBinding(
                    object_id=obj_id,
                    role="anchor",
                    selector=selector,
                    confidence=_compute_role_confidence(obj, "anchor", objects, selector)
                ))

            # Marker candidates: small, distinct objects
            if kind in ("point", "unique-color", "unique-shape", "unique-size"):
                candidates["marker"].append(RoleBinding(
                    object_id=obj_id,
                    role="marker",
                    selector=selector,
                    confidence=_compute_role_confidence(obj, "marker", objects, selector)
                ))

    return dict(candidates)


def _compute_role_confidence(obj: ArcObject, role: str, 
                            all_objects: list[ArcObject], selector: Selector) -> float:
    """Compute confidence score for a role assignment."""
    base_confidence = 1.0
    kind = selector[0]

    # Unique selectors are more confident
    if kind in ("unique-color", "unique-shape", "unique-size", "unique-color", "unique-size"):
        base_confidence += 0.5
    elif kind in ("largest", "smallest"):
        base_confidence += 0.3
    elif kind == "point":
        base_confidence += 0.2

    # Role-specific bonuses
    if role == "source":
        # Prefer objects with distinct shape (more likely to be copied)
        shape_counts = Counter(normalized_shape(o) for o in all_objects)
        if shape_counts[normalized_shape(obj)] == 1:
            base_confidence += 0.2
    elif role == "landmark":
        # Prefer stable, distinctive landmarks
        if kind in ("unique-color", "unique-shape", "unique-size", "largest", "smallest"):
            base_confidence += 0.3
        # Prefer objects with high connectivity to others (central in relation graph)
        if len(obj.adjacent_colors) > 0:
            base_confidence += 0.2
    elif role == "anchor":
        # Prefer unique, stable anchors
        if kind in ("unique-color", "unique-shape", "unique-size"):
            base_confidence += 0.5

    # Penalty for objects that are enclosed (less likely to be independent landmarks)
    if len(obj.enclosed_by) > 0:
        base_confidence -= 0.2

    return min(base_confidence, 1.0)


# Cross-example role validation
def validate_role_bindings_across_examples(
    train_pairs: list[tuple[Grid, Grid]],
    candidate_program: CandidateProgram
) -> tuple[bool, dict]:
    """
    Test a candidate role binding across ALL training examples.
    Returns (is_valid, evidence_dict).
    """
    evidence = {}
    all_pass = True

    for ex_idx, (source, target) in enumerate(train_pairs):
        try:
            # Try to resolve all role bindings in this example
            source_objects = extract_objects(source, background_color=infer_background(source))
            target_objects = extract_objects(target, background_color=infer_background(target))

            # Try to find objects matching each role's selector
            bound_objects = {}
            for binding in candidate_program.role_bindings:
                matches = _matches(source_objects, binding.selector)
                if len(matches) != 1:
                    evidence[ex_idx] = False
                    all_pass = False
                    break
                bound_objects[binding.role] = matches[0]

            if not all_pass:
                break

            # Apply transformation and verify
            result = candidate_program.transformation_fn(source, bound_objects)
            if result != target:
                evidence[ex_idx] = False
                all_pass = False
            else:
                evidence[ex_idx] = True
        except Exception as e:
            evidence[ex_idx] = False
            all_pass = False

    return all_pass, evidence


