    """Cheap parsimony key for ranking relation hypotheses."""
    selector_bits: int
    placement_rank: int
    objects_touched: int
    recolor_penalty: int
    name: str  # tiebreaker


def _placement_rank(placement: tuple) -> int:
    """Rank placements by simplicity: onto_marker < adjacent < align_bbox < between < mirrored_across < repeated_k."""
    kind = placement[0]
    ranks = {
        "onto_marker": 0,
        "adjacent": 1,
        "align_bbox": 2,
        "between": 3,
        "mirrored_across": 4,
        "repeated_k": 5,
    }
    return ranks.get(kind, 99)


def _selector_bits(selector: Selector) -> int:
    """Bits needed to encode selector (fewer = simpler)."""
    kind = selector[0]
    # Single-token selectors are cheapest
    if kind in ("unique-color", "unique-shape", "unique-size", "most-frequent-color", "least-frequent-color",
                "largest", "smallest", "point", "shape"):
        return 1
    if kind in ("color", "area", "orientation"):
        return 2
    if kind == "color_shape":
        return 3
    return 4


def _compute_parsimony(rule: Rule, source_role: Selector, landmark_role: Selector,
                       landmark_b_role: Selector | None, placement: tuple,
                       color_policy: str) -> ParsimonyScore:
    """Compute parsimony score for a relation hypothesis."""
    selector_bits = (_selector_bits(source_role) + _selector_bits(landmark_role) +
                     (_selector_bits(landmark_b_role) if landmark_b_role else 0))
    placement_rank = _placement_rank(placement)
    # objects_touched: 2 for single landmark, 3 for between
    objects_touched = 3 if landmark_b_role else 2
    # recolor_penalty: 1 if copying with landmark color instead of source color
    recolor_penalty = 1 if color_policy == "landmark" else 0
    return ParsimonyScore(
        selector_bits=selector_bits,
        placement_rank=placement_rank,
        objects_touched=objects_touched,
        recolor_penalty=recolor_penalty,
        name=rule.name
    )


def _normalize_selector_name(selector: Selector) -> str:
    """Normalize selector for duplicate detection."""
    return selector[0]


def _funnel_hypotheses(rules: list[Rule], max_before_invariance: int = 16,
                       max_per_placement_family: int = 2) -> list[Rule]:
    """
    64 → 16 → 1 funnel applied ONLY to relation-conditioned-copy rules.
    Other rule families pass through unchanged.
    1. Score by parsimony (relation rules only)
    2. Drop exact duplicates (normalize selector names)
    3. Keep at most max_per_placement_family per placement family
    4. Keep at most max_before_invariance total relation rules
    """
    if not rules:
        return []

    # Separate relation-conditioned-copy rules from others
    relation_rules = [r for r in rules if r.family == "relation-conditioned-copy"]
    other_rules = [r for r in rules if r.family != "relation-conditioned-copy"]

    if not relation_rules:
        return rules  # No relation rules to funnel

    # Group by placement family and compute parsimony
    scored = []
    seen_normalized = set()

    for rule in relation_rules:
        # Parse placement family from name
        try:
            place_part = rule.name.split("->place(")[1].split(")->color")[0]
            placement_family = place_part.split(",")[-1].split(":")[0]
        except (IndexError, ValueError):
            placement_family = "unknown"

        # Normalize selector names for deduplication
        src_sel = _normalize_selector_name_from_rule(rule, "copy")
        lm_sel = _normalize_selector_name_from_rule(rule, "place")

        norm_key = (src_sel, lm_sel, placement_family, 
                    "landmark_b" in rule.name, rule.family)

        if norm_key in seen_normalized:
            continue
        seen_normalized.add(norm_key)

        scored.append((rule, placement_family))

    # Sort by complexity (lower = simpler), then name
    scored.sort(key=lambda x: (x[0].complexity, x[0].name))

    # Cap per placement family
    family_counts: Counter[str] = Counter()
    filtered = []
    for rule, family in scored:
        if family_counts[family] >= max_per_placement_family:
            continue
        filtered.append(rule)
        family_counts[family] += 1
        if len(filtered) >= max_before_invariance:
            break

    # Return other rules + funneled relation rules
    return other_rules + filtered


def _normalize_selector_name_from_rule(rule: Rule, prefix: str) -> str:
    """Extract and normalize selector from rule name."""
    try:
        if prefix == "copy":
            part = rule.name.split("object-program:copy(")[1].split(")")[0]
        else:
            part = rule.name.split("->place(")[1].split(",")[0]
        # Normalize: just take the selector kind
        return part.split(",")[0].strip("'\"()")
    except (IndexError, ValueError):
        return "unknown"


def _select_final_candidates(rules: list[Rule]) -> list[Rule]:
    """
    After invariance filtering, keep 1 primary + 1 distinct backup.
    Backup must differ in placement family or selector kind.
    """
    if not rules:
        return []
    if len(rules) == 1:
        return rules

    primary = rules[0]
    primary_family = _extract_placement_family(primary.name)
    primary_selector = _extract_source_selector(primary.name)

    for rule in rules[1:]:
        if (_extract_placement_family(rule.name) != primary_family or
            _extract_source_selector(rule.name) != primary_selector):
            return [primary, rule]

    return [primary]


def _extract_placement_family(name: str) -> str:
    try:
        return name.split("->place(")[1].split(")->color")[0].split(",")[-1].split(":")[0]
    except (IndexError, ValueError):
        return "unknown"


def _extract_source_selector(name: str) -> str:
    try:
        return name.split("object-program:copy(")[1].split(")")[0].split(",")[0].strip("'\"()")
    except (IndexError, ValueError):
        return "unknown"


def _matches(objects: Iterable[ArcObject], selector: Selector) -> list[ArcObject]:
    objects = list(objects)
    kind = selector[0]
    if kind == "shape":
        return [obj for obj in objects if normalized_shape(obj) == selector[1]]
    if kind == "color_shape":
        return [obj for obj in objects if obj.color == selector[1] and
                normalized_shape(obj) == selector[2]]
    if kind == "color":
        return [obj for obj in objects if obj.color == selector[1]]
    if kind == "area":
        return [obj for obj in objects if len(obj.cells) == selector[1]]
    if kind == "orientation":
        return [obj for obj in objects if obj.orientation == selector[1]]
    if kind == "point":
        return [obj for obj in objects if len(obj.cells) == 1]
    if kind in ("largest", "smallest"):
        if not objects:
            return []
        area = max if kind == "largest" else min
        target_area = area(len(obj.cells) for obj in objects)
        return [obj for obj in objects if len(obj.cells) == target_area]
    if kind == "unique-color":
        color_counts = Counter(obj.color for obj in objects)
        return [obj for obj in objects if color_counts[obj.color] == 1]
    if kind == "unique-shape":
        shape_counts = Counter(normalized_shape(obj) for obj in objects)
        return [obj for obj in objects if shape_counts[normalized_shape(obj)] == 1]
    if kind == "unique-size":
        size_counts = Counter(len(obj.cells) for obj in objects)
        return [obj for obj in objects if size_counts[len(obj.cells)] == 1]
    if kind == "most-frequent-color":
        if not objects:
            return []
        color_counts = Counter(obj.color for obj in objects)
        max_count = max(color_counts.values())
        target_colors = {c for c, cnt in color_counts.items() if cnt == max_count}
        return [obj for obj in objects if obj.color in target_colors]
    if kind == "least-frequent-color":
        if not objects:
            return []
        color_counts = Counter(obj.color for obj in objects)
        min_count = min(color_counts.values())
        target_colors = {c for c, cnt in color_counts.items() if cnt == min_count}
        return [obj for obj in objects if obj.color in target_colors]
    raise ValueError(f"unknown object selector: {kind}")


def _selector_specs(objects: list[ArcObject], obj: ArcObject) -> list[Selector]:
    """Return invariant object-role descriptions that uniquely select obj."""
    shape = normalized_shape(obj)
    candidates: list[Selector] = [
        ("shape", shape), ("color_shape", obj.color, shape),
        ("color", obj.color), ("area", len(obj.cells)),
        ("orientation", obj.orientation),
    ]
    if len(obj.cells) == 1:
        candidates.append(("point",))
    areas = [len(item.cells) for item in objects]
    if areas.count(len(obj.cells)) == 1:
        if len(obj.cells) == max(areas):
            candidates.append(("largest",))
        if len(obj.cells) == min(areas):
            candidates.append(("smallest",))
    color_counts = Counter(item.color for item in objects)
    if color_counts[obj.color] == 1:
        candidates.append(("unique-color",))
    shape_counts = Counter(normalized_shape(item) for item in objects)
    if shape_counts[shape] == 1:
        candidates.append(("unique-shape",))
    if areas.count(len(obj.cells)) == 1:
        candidates.append(("unique-size",))
    max_color_count = max(color_counts.values())
    if color_counts[obj.color] == max_color_count:
        candidates.append(("most-frequent-color",))
    min_color_count = min(color_counts.values())
    if color_counts[obj.color] == min_color_count:
        candidates.append(("least-frequent-color",))
    return list(dict.fromkeys(selector for selector in candidates
                              if (matches := _matches(objects, selector)) == [obj]))


def _selector_complexity(selector: Selector) -> int:
    return {"shape": 1, "point": 1, "largest": 1, "smallest": 1,
            "unique-color": 1, "unique-shape": 1, "unique-size": 1,
            "most-frequent-color": 1, "least-frequent-color": 1,
            "color": 2, "area": 2, "orientation": 2,
            "color_shape": 3}[selector[0]]


def _resolve(grid: Grid, selector: Selector) -> ArcObject:
    objects = extract_objects(grid, background_color=infer_background(grid))
    matches = _matches(objects, selector)
    if len(matches) != 1:
        raise ValueError("object role is absent or ambiguous")
    return matches[0]


def _shape_anchor(obj: ArcObject, choice: str) -> tuple[int, int]:
    top, left, _, _ = obj.bbox
    local = {(r - top, c - left) for r, c in obj.cells}
    if choice == "top_left":
        return min(local)
    if choice == "bottom_right":
        return max(local)
    if choice == "center_cell":
        center = obj.centroid
        return min(local, key=lambda point: (
            abs(point[0] + top - center[0]) + abs(point[1] + left - center[1]),
            point))
    raise ValueError(f"unknown source anchor: {choice}")


def _aligned_offset(source_size: int, landmark_size: int,
                    alignment: str) -> int | None:
    if alignment == "start":
        return 0
    if alignment == "end":
        return landmark_size - source_size
    difference = landmark_size - source_size
    if difference % 2:
        return None
    return difference // 2


def _placement_origin(source: ArcObject, landmark: ArcObject,
                      placement: tuple, landmark_b: ArcObject | None = None) -> tuple[int, int] | None:
    kind = placement[0]
    sr, sc, sr1, sc1 = source.bbox
    lr, lc, lr1, lc1 = landmark.bbox
    if kind == "onto_marker":
        _, anchor_name = placement
        ar, ac = _shape_anchor(source, anchor_name)
        marker_r, marker_c = min(landmark.cells)
        return marker_r - ar, marker_c - ac
    if kind == "align_bbox":
        _, vertical, horizontal = placement
        dy = _aligned_offset(source.height, landmark.height, vertical)
        dx = _aligned_offset(source.width, landmark.width, horizontal)
        if dy is None or dx is None:
            return None
        return lr + dy, lc + dx
    if kind == "adjacent":
        _, direction, alignment = placement
        if direction in ("above", "below"):
            dx = _aligned_offset(source.width, landmark.width, alignment)
            if dx is None:
                return None
            row = lr - source.height if direction == "above" else lr1
            return row, lc + dx
        dy = _aligned_offset(source.height, landmark.height, alignment)
        if dy is None:
            return None
        col = lc - source.width if direction == "left" else lc1
        return lr + dy, col
    if kind == "between":
        if landmark_b is None:
            return None
        br, bc, br1, bc1 = landmark_b.bbox
        mid_r = (lr + br) // 2
        mid_c = (lc + bc) // 2
        return mid_r - source.height // 2, mid_c - source.width // 2
    if kind == "mirrored_across":
        center_r = (lr + lr1) / 2
        center_c = (lc + lc1) / 2
        source_center_r = (sr + sr1) / 2
        source_center_c = (sc + sc1) / 2
        dy = int(2 * (center_r - source_center_r))
        dx = int(2 * (center_c - source_center_c))
        return sr + dy, sc + dx
    if kind == "repeated_k":
        _, k = placement
        dr = lr - sr
        dc = lc - sc
        return sr + k * dr, sc + k * dc
    return None


def _render_copy(grid: Grid, source_selector: Selector,
                 landmark_selector: Selector, placement: tuple,
                 color_policy: str, landmark_b_selector: Selector | None = None) -> Grid:
    source = _resolve(grid, source_selector)
    landmark = _resolve(grid, landmark_selector)
    if source.cells == landmark.cells:
        raise ValueError("source and landmark roles resolve to the same object")
    landmark_b = None
    if landmark_b_selector is not None:
        landmark_b = _resolve(grid, landmark_b_selector)
        if landmark_b.cells == source.cells or landmark_b.cells == landmark.cells:
            raise ValueError("landmark_b resolves to source or landmark")
    origin = _placement_origin(source, landmark, placement, landmark_b)
    if origin is None:
        raise ValueError("relation cannot be instantiated on this grid")
    top, left = source.bbox[:2]
    kind = placement[0]
    color = source.color if color_policy == "source" else landmark.color
    h, w = len(grid), len(grid[0])
    out = [list(row) for row in grid]
    background = infer_background(grid)

    def paint_cells(cells: frozenset[tuple[int, int]]) -> None:
        for r, c in cells:
            existing = grid[r][c]
            on_landmark = (r, c) in landmark.cells
            on_landmark_b = landmark_b is not None and (r, c) in landmark_b.cells
            if (r, c) in source.cells:
                raise ValueError("relation-conditioned copy overlaps its source")
            if existing != background and not on_landmark and not on_landmark_b and existing != color:
                raise ValueError("relation-conditioned copy collides with another object")
            out[r][c] = color

    if kind == "repeated_k":
        _, k = placement
        dr = origin[0] - top
        dc = origin[1] - left
        for i in range(1, k + 1):
            copy_cells = frozenset((r + i * dr, c + i * dc) for r, c in source.cells)
            if any(not (0 <= r < h and 0 <= c < w) for r, c in copy_cells):
                raise ValueError("repeated copy exceeds the canvas")
            paint_cells(copy_cells)
    else:
        dy, dx = origin[0] - top, origin[1] - left
        copied_cells = frozenset((r + dy, c + dx) for r, c in source.cells)
        if copied_cells == source.cells:
            raise ValueError("copy placement is a no-op")
        if any(not (0 <= r < h and 0 <= c < w) for r, c in copied_cells):
            raise ValueError("relation-conditioned copy exceeds the canvas")
        paint_cells(copied_cells)
    return tuple(tuple(row) for row in out)


def _check_landmark_translation(grid: Grid, source_selector: Selector,
                                landmark_selector: Selector,
                                placement: tuple, color_policy: str,
                                landmark_b_selector: Selector | None = None) -> bool | None:
    """Translate the landmark and check that the compiled placement follows."""
    background = infer_background(grid)
    objects = extract_objects(grid, background_color=background)
    source_matches = _matches(objects, source_selector)
    landmark_matches = _matches(objects, landmark_selector)
    if len(source_matches) != 1 or len(landmark_matches) != 1:
        return None
    source, landmark = source_matches[0], landmark_matches[0]
    landmark_b = None
    if landmark_b_selector is not None:
        landmark_b_matches = _matches(objects, landmark_b_selector)
        if len(landmark_b_matches) != 1:
            return None
        landmark_b = landmark_b_matches[0]
    original_origin = _placement_origin(source, landmark, placement, landmark_b)
    if original_origin is None:
        return None
    source_top, source_left = source.bbox[:2]
    kind = placement[0]
    if kind == "repeated_k":
        _, k = placement
        dr = original_origin[0] - source_top
        dc = original_origin[1] - source_left
        baseline_cells = frozenset()
        for i in range(1, k + 1):
            baseline_cells |= frozenset((r + i * dr, c + i * dc) for r, c in source.cells)
    else:
        baseline_cells = frozenset((r + original_origin[0] - source_top,
                                    c + original_origin[1] - source_left)
                                   for r, c in source.cells)
    h, w = len(grid), len(grid[0])
    other_cells = set().union(*(obj.cells for obj in objects
                                if obj.cells != landmark.cells))
    attempted = False
    for dy, dx in ((-1, 0), (1, 0), (0, -1), (0, 1)):
        moved = frozenset((r + dy, c + dx) for r, c in landmark.cells)
        if any(not (0 <= r < h and 0 <= c < w) for r, c in moved):
            continue
        if moved & other_cells:
            continue
        attempted = True
        perturbed = [list(row) for row in grid]
        for r, c in landmark.cells:
            perturbed[r][c] = background
        for r, c in moved:
            perturbed[r][c] = landmark.color
        perturbed_grid = tuple(tuple(row) for row in perturbed)
        try:
            moved_source = _resolve(perturbed_grid, source_selector)
            moved_landmark = _resolve(perturbed_grid, landmark_selector)
            moved_landmark_b = None
            if landmark_b_selector is not None:
                moved_landmark_b_matches = _matches(
                    extract_objects(perturbed_grid, background_color=background),
                    landmark_b_selector)
                if len(moved_landmark_b_matches) != 1:
                    continue
                moved_landmark_b = moved_landmark_b_matches[0]
            origin = _placement_origin(moved_source, moved_landmark, placement, moved_landmark_b)
            if origin is None:
                continue
            top, left = moved_source.bbox[:2]
            if kind == "repeated_k":
                _, k = placement
                dr = origin[0] - top
                dc = origin[1] - left
                copy_cells = frozenset()
                for i in range(1, k + 1):
                    copy_cells |= frozenset((r + i * dr, c + i * dc) for r, c in moved_source.cells)
            else:
                copy_cells = frozenset((r + origin[0] - top,
                                        c + origin[1] - left)
                                       for r, c in moved_source.cells)
            if copy_cells == baseline_cells:
                continue
            output = _render_copy(perturbed_grid, source_selector,
                                  landmark_selector, placement, color_policy,
                                  landmark_b_selector)
            color = (moved_source.color if color_policy == "source"
                     else moved_landmark.color)
            if all(output[r][c] == color for r, c in copy_cells):
                return True
        except (ArithmeticError, IndexError, TypeError, ValueError):
            continue
    return False if attempted else None


def _placement_specs(source: ArcObject) -> list[tuple]:
    specs = [("onto_marker", anchor) for anchor in
             ("top_left", "center_cell", "bottom_right")]
    for vertical in ("start", "center", "end"):
        for horizontal in ("start", "center", "end"):
            specs.append(("align_bbox", vertical, horizontal))
    for direction in ("above", "below", "left", "right"):
        orthogonal = ("start", "center", "end")
        specs.extend(("adjacent", direction, align) for align in orthogonal)
    # Between two landmarks: place source between landmark_a and landmark_b
    specs.append(("between",))
    # Mirrored across a landmark (point reflection through landmark center)
    specs.append(("mirrored_across",))
    # Repeated k times in a line from landmark
    for k in (2, 3):
        specs.append(("repeated_k", k))
    return specs


def generate_relation_copy_hypotheses(
        train_pairs: Iterable[tuple[Grid, Grid]], *,
        max_hypotheses: int = 64) -> list[Rule]:
    """Compile copy/place candidates from object roles and landmark relations.

    No displacement is learned as a constant. Placement is represented as an
    anchor, bbox alignment, adjacency, between, mirrored, or repeated relation
    and is recomputed on each grid. The first demonstration prunes proposals;
    the caller must replay all demos.

    Returns at most 16 hypotheses after parsimony funnel (64 -> 16).
    """
    pairs = tuple(train_pairs)
    if len(pairs) < 2:
        return []
    first_source, first_target = pairs[0]
    deltas = [compare_grids(source, target, infer_background(source))
              for source, target in pairs]
    if any(delta.dimensions_changed or delta.removed_cells for delta in deltas):
        return []
    if not any(delta.added_cells or delta.recolored_cells for delta in deltas):
        return []

    objects = extract_objects(first_source,
                              background_color=infer_background(first_source))
    proposals: dict[str, Rule] = {}
    for source_object in objects:
        source_roles = _selector_specs(objects, source_object)
        if not source_roles:
            continue
        for landmark_object in objects:
            if landmark_object.cells == source_object.cells:
                continue
            landmark_roles = _selector_specs(objects, landmark_object)
            if not landmark_roles:
                continue
            for source_role in source_roles:
                for landmark_role in landmark_roles:
                    for placement in _placement_specs(source_object):
                        kind = placement[0]
                        # Between requires a second landmark
                        if kind == "between":
                            for landmark_b_object in objects:
                                if (landmark_b_object.cells == source_object.cells or
                                    landmark_b_object.cells == landmark_object.cells):
                                    continue
                                landmark_b_roles = _selector_specs(objects, landmark_b_object)
                                if not landmark_b_roles:
                                    continue
                                for landmark_b_role in landmark_b_roles:
                                    for color_policy in ("source", "landmark"):
                                        _add_proposal(proposals, source_role, landmark_role,
                                                      landmark_b_role, placement,
                                                      color_policy, source_object,
                                                      landmark_object, landmark_b_object,
                                                      first_source, first_target,
                                                      max_hypotheses)
                        else:
                            for color_policy in ("source", "landmark"):
                                _add_proposal(proposals, source_role, landmark_role,
                                              None, placement, color_policy,
                                              source_object, landmark_object, None,
                                              first_source, first_target,
                                              max_hypotheses)
                        if len(proposals) >= max_hypotheses:
                            break
                if len(proposals) >= max_hypotheses:
                    break
        if len(proposals) >= max_hypotheses:
            break

    raw_rules = list(proposals.values())
    # Apply 64 -> 16 funnel before invariance checking
    funneled = _funnel_hypotheses(raw_rules, max_before_invariance=16, max_per_placement_family=2)
    return funneled


def _add_proposal(proposals: dict[str, Rule],
                  source_role: Selector, landmark_role: Selector,
                  landmark_b_role: Selector | None,
                  placement: tuple, color_policy: str,
                  source_object, landmark_object, landmark_b_object,
                  first_source: Grid, first_target: Grid,
                  max_hypotheses: int) -> None:
    kind = placement[0]
    relation_names = ["source-role", "landmark-role"]
    if kind == "onto_marker":
        relation_names.append("copy_onto_marker")
    elif kind == "align_bbox":
        relation_names.append("align_bbox")
    elif kind == "adjacent":
        relation_names.append("adjacent")
    elif kind == "between":
        relation_names.append("between")
    elif kind == "mirrored_across":
        relation_names.append("mirrored_across")
    elif kind == "repeated_k":
        relation_names.append("repeated_k")
    else:
        relation_names.append("place_relative_to_landmark")
    readable_placement = ":".join(map(str, placement))
    name_parts = ["object-program:copy(" + repr(source_role),
                  ")->place(" + repr(landmark_role)]
    if landmark_b_role is not None:
        name_parts.append("," + repr(landmark_b_role))
    name_parts.append("," + readable_placement + ")->color(" + color_policy + ")")
    name = "".join(name_parts)
    if name in proposals:
        return
    apply = lambda grid, sr=source_role, lr=landmark_role, \
        lbr=landmark_b_role, place=placement, cp=color_policy: _render_copy(
            grid, sr, lr, place, cp, lbr)
    try:
        if apply(first_source) != first_target:
            return
    except (ArithmeticError, IndexError, TypeError, ValueError):
        return
    known_colors = {source_object.color, landmark_object.color}
    if landmark_b_object is not None:
        known_colors.add(landmark_b_object.color)
    proposals[name] = Rule(
        name=name, apply=apply,
        complexity=(4 + len(relation_names) +
                    _selector_complexity(source_role) +
                    _selector_complexity(landmark_role) +
                    (_selector_complexity(landmark_b_role) if landmark_b_role else 0)),
        assumptions=1,
        family="relation-conditioned-copy",
        structural_coverage=len(relation_names),
        known_colors=tuple(sorted(known_colors)),
        relation_predicates=tuple(relation_names),
        relation_perturbation=lambda grid, sr=source_role, lr=landmark_role,
            lbr=landmark_b_role, place=placement, cp=color_policy:
            _check_landmark_translation(grid, sr, lr, place, cp, lbr))

"""Small, replayable hypotheses inferred from ARC demonstrations."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Callable, Iterable

from .deltas import compare_grids
from .grid import Grid, dimensions
from .objects import extract_objects
from .primitives import (complete_symmetry, crop_color, crop_non_background,
                          combine_regions, fill_enclosed_background, gravity,
                          object_bounding_boxes, object_feature, object_outlines,
                          recolor_by_palette_rank, recolor_objects_by_feature,
                          connect_aligned_objects, reflect_horizontal,
                          connect_nearest_objects,
                          reflect_vertical, rotate, scale, select_objects,
                          split_on_separator, tile, transform_each_object)

Transform = Callable[[Grid], Grid]


@dataclass(frozen=True)
class Rule:
    name: str
    apply: Transform
    complexity: int
    assumptions: int = 0
    family: str = "grid-transform"
    matched_examples: int = 0
    structural_coverage: int = 0
    known_colors: tuple[int, ...] = ()
    relation_predicates: tuple[str, ...] = ()
    local_writes: int = 0
    invariance_passes: tuple[str, ...] = ()
    invariance_failures: tuple[str, ...] = ()
    relation_perturbation: Callable[[Grid], bool | None] | None = None


def _fits(transform: Transform, pairs: tuple[tuple[Grid, Grid], ...]) -> bool:
    try:
        return all(transform(source) == target for source, target in pairs)
    except (ArithmeticError, IndexError, TypeError, ValueError):
        return False


def _mapping_rule(pairs: tuple[tuple[Grid, Grid], ...], preprocess: Transform,
                  name: str, complexity: int = 2) -> Rule | None:
    mapping: dict[int, int] = {}
    for source, target in pairs:
        source = preprocess(source)
        if dimensions(source) != dimensions(target):
            return None
        for row_a, row_b in zip(source, target):
            for a, b in zip(row_a, row_b):
                if a in mapping and mapping[a] != b:
                    return None
                mapping[a] = b
    if not any(a != b for a, b in mapping.items()):
        return None
    known_colors = tuple(sorted({value for source, _ in pairs
                                 for row in preprocess(source) for value in row}))
    return Rule(name, lambda grid, preprocess=preprocess, mapping=mapping: tuple(
        tuple(mapping.get(v, v) for v in row)
        for row in preprocess(grid)),
        complexity=complexity, assumptions=1, family="color",
        known_colors=known_colors)


def _count_rules(pairs: tuple[tuple[Grid, Grid], ...]) -> Iterable[Rule]:
    if not pairs or any(dimensions(target) != (1, 1) for _, target in pairs):
        return
    colors = sorted({value for grid, _ in pairs for row in grid for value in row if value})
    metrics = [
        ("nonbackground-cell-count", lambda g: sum(v != 0 for row in g for v in row)),
        ("connected-object-count", lambda g: sum(v != 0 for row in g for v in row)),
        ("distinct-color-count", lambda g: len({v for row in g for v in row if v})),
    ]
    from .objects import connected_components
    metrics[1] = (metrics[1][0], lambda g: len(connected_components(g)))
    metrics.extend((f"color-{color}-cell-count",
                    lambda g, color=color: sum(v == color for row in g for v in row))
                   for color in colors)
    metrics.extend((f"color-{color}-object-count",
                    lambda g, color=color: len(connected_components(g, color=color)))
                   for color in colors)
    for name, measure in metrics:
        if all(target[0][0] == measure(source) for source, target in pairs):
            yield Rule(name, lambda grid, measure=measure: ((measure(grid),),),
                       complexity=2, assumptions=1, family="counting")


def _local_rewrite_rule(pairs: tuple[tuple[Grid, Grid], ...], radius: int) -> Rule | None:
    if any(dimensions(source) != dimensions(target) for source, target in pairs):
        return None
    contexts: dict[tuple[int, ...], int] = {}
    counts: dict[tuple[int, ...], int] = {}
    example_support: dict[tuple[int, ...], set[int]] = {}
    changed_support: dict[tuple[int, ...], set[int]] = {}
    for example_index, (source, target) in enumerate(pairs):
        h, w = dimensions(source)
        for r in range(h):
            for c in range(w):
                context = tuple(
                    source[rr][cc] if 0 <= rr < h and 0 <= cc < w else -1
                    for rr in range(r - radius, r + radius + 1)
                    for cc in range(c - radius, c + radius + 1))
                output = target[r][c]
                if context in contexts and contexts[context] != output:
                    return None
                contexts[context] = output
                counts[context] = counts.get(context, 0) + 1
                example_support.setdefault(context, set()).add(example_index)
                center = context[len(context) // 2]
                if output != center:
                    changed_support.setdefault(context, set()).add(example_index)
    reused = sum(len(indices) >= 2 for indices in example_support.values())
    # A local program must show a changed context recurring across separate
    # demonstrations. Repetition among neighboring cells in one grid is not
    # evidence that the rule generalizes beyond that one configuration.
    supported_changes = sum(len(indices) >= 2
                            for indices in changed_support.values())
    if reused < 2 or supported_changes < 1:
        return None

    def apply(grid: Grid) -> Grid:
        h, w = dimensions(grid)
        rows = []
        for r in range(h):
            row = []
            for c in range(w):
                context = tuple(
                    grid[rr][cc] if 0 <= rr < h and 0 <= cc < w else -1
                    for rr in range(r - radius, r + radius + 1)
                    for cc in range(c - radius, c + radius + 1))
                row.append(contexts.get(context, grid[r][c]))
            rows.append(tuple(row))
        return tuple(rows)

    return Rule(f"local-neighborhood-r{radius}", apply,
                complexity=12 + radius * 4, assumptions=3,
                family="local-rewrite", structural_coverage=reused,
                local_writes=supported_changes)


def _palette_rank_rule(pairs: tuple[tuple[Grid, Grid], ...],
                       measure: str, preprocess: Transform,
                       name: str) -> Rule | None:
    rank_mapping: dict[int, int] = {}
    for source, target in pairs:
        source = preprocess(source)
        if dimensions(source) != dimensions(target):
            return None
        palette = {value for row in source for value in row}
        target_palette = {value for row in target for value in row}
        if not target_palette <= palette:
            return None
        if measure == "cells":
            counts = {color: sum(value == color for row in source for value in row)
                      for color in palette}
        else:
            from .objects import connected_components
            counts = {color: (0 if color == 0 else
                              len(connected_components(source, color=color)))
                      for color in palette}
        ordered = sorted(palette, key=lambda color: (-counts[color], color))
        color_to_rank = {color: rank for rank, color in enumerate(ordered)}
        for row_a, row_b in zip(source, target):
            for a, b in zip(row_a, row_b):
                source_rank, target_rank = color_to_rank[a], color_to_rank[b]
                if (source_rank in rank_mapping and
                        rank_mapping[source_rank] != target_rank):
                    return None
                rank_mapping[source_rank] = target_rank
    if not rank_mapping or all(rank == target for rank, target in rank_mapping.items()):
        return None
    return Rule(name, lambda grid, preprocess=preprocess,
                rank_mapping=rank_mapping, measure=measure: recolor_by_palette_rank(
                    preprocess(grid), rank_mapping, measure),
                complexity=5, assumptions=2, family="palette-role")


def _object_correspondence_rule(
        pairs: tuple[tuple[Grid, Grid], ...]) -> Rule | None:
    """Infer a shared per-shape/color translation and recoloring from demos."""
    from .primitives import object_shape_signature, transform_objects_by_signature

    transforms: dict[tuple, tuple[int, int, int]] = {}
    observed = 0
    for source, target in pairs:
        if dimensions(source) != dimensions(target):
            return None
        source_objects = extract_objects(source)
        target_objects = extract_objects(target)
        if len(source_objects) != len(target_objects):
            return None
        unused = set(range(len(target_objects)))
        for obj in source_objects:
            shape = object_shape_signature(obj)
            candidates = [index for index in unused
                          if object_shape_signature(target_objects[index]) == shape]
            if not candidates:
                return None
            same_color = [index for index in candidates
                          if target_objects[index].color == obj.color]
            if len(same_color) == 1:
                selected = same_color[0]
            elif len(candidates) == 1:
                selected = candidates[0]
            else:
                # Correspondence among indistinguishable recolored shapes is
                # ambiguous; do not invent a coordinate-based tie breaker.
                return None
            output_object = target_objects[selected]
            key = (obj.color, shape)
            transform = (output_object.bbox[0] - obj.bbox[0],
                         output_object.bbox[1] - obj.bbox[1],
                         output_object.color)
            if key in transforms and transforms[key] != transform:
                return None
            transforms[key] = transform
            unused.remove(selected)
            observed += 1
        if unused:
            return None
    if not transforms or all(value == (0, 0, key[0])
                             for key, value in transforms.items()):
        return None

    def apply(grid: Grid, transforms=transforms) -> Grid:
        return transform_objects_by_signature(grid, transforms)

    if not _fits(apply, pairs):
        return None
    return Rule("object-correspondence(shape,color)", apply,
                complexity=4 + len(transforms), assumptions=2,
                family="object-correspondence",
                structural_coverage=observed,
                known_colors=tuple(sorted({key[0] for key in transforms})))


def generate_hypotheses(train_pairs: Iterable[tuple[Grid, Grid]], *,
                        return_search_stats: bool = False):
    """Generate direct and composed candidates; replay remains authoritative.

    If direct rules cannot replay every demonstration, use a bounded program
    search over grid/object/relation operators. Search output is only a source
    of hypotheses: the caller still verifies every returned rule exactly.
    """
    pairs = tuple(train_pairs)
    if not pairs:
        return ([], {"triggered": False, "reason": "no_training_pairs"}) \
            if return_search_stats else []
    geometries: list[tuple[str, Transform, int]] = [
        ("identity", lambda g: g, 1),
        ("reflect-horizontal", reflect_horizontal, 2),
        ("reflect-vertical", reflect_vertical, 2),
        ("reflect-both-axes", lambda g: reflect_vertical(reflect_horizontal(g)), 3),
        ("rotate-90", lambda g: rotate(g, 1), 2),
        ("rotate-180", lambda g: rotate(g, 2), 2),
        ("rotate-270", lambda g: rotate(g, 3), 2),
        ("crop-non-background", crop_non_background, 2),
    ]
    rules: list[Rule] = [
        Rule("identity", lambda g: g, 1, family="identity"),
        Rule("reflect-horizontal", reflect_horizontal, 2),
        Rule("reflect-vertical", reflect_vertical, 2),
        Rule("reflect-both-axes", lambda g: reflect_vertical(reflect_horizontal(g)), 3),
        Rule("rotate-90", lambda g: rotate(g, 1), 2),
        Rule("rotate-180", lambda g: rotate(g, 2), 2),
        Rule("rotate-270", lambda g: rotate(g, 3), 2),
        Rule("crop-non-background", crop_non_background, 2, assumptions=1),
    ]
    for axis in ("vertical", "horizontal", "diagonal", "antidiagonal"):
        transform = lambda g, axis=axis: complete_symmetry(g, axis)
        if _fits(transform, pairs):
            rules.append(Rule(f"complete-symmetry({axis})", transform, 3,
                              assumptions=1, family="symmetry"))
    for name, transform, complexity in (
            ("fill-enclosed", fill_enclosed_background, 3),
            ("fill-object-bboxes", object_bounding_boxes, 3),
            ("object-outlines", object_outlines, 3)):
        if _fits(transform, pairs):
            rules.append(Rule(name, transform, complexity, assumptions=1,
                              family="object-transform"))
    selectors = ("largest", "smallest", "unique-size", "unique-shape",
                 "most-frequent-color", "least-frequent-color", "symmetric",
                 "asymmetric", "horizontal", "vertical", "square", "point",
                 "wide", "tall")
    for selector in selectors:
        transform = lambda g, selector=selector: select_objects(g, selector)
        if _fits(transform, pairs):
            rules.append(Rule(f"select-objects({selector})", transform, 3,
                              assumptions=1, family="object-selection"))
        cropped = lambda g, transform=transform: crop_non_background(transform(g))
        if _fits(cropped, pairs):
            rules.append(Rule(f"crop-selected-objects({selector})", cropped, 4,
                              assumptions=2, family="object-selection"))
    for operation in ("reflect-horizontal", "reflect-vertical", "rotate-90",
                      "rotate-180", "rotate-270"):
        transform = lambda g, operation=operation: transform_each_object(g, operation)
        if _fits(transform, pairs):
            rules.append(Rule(f"transform-each-object({operation})", transform, 4,
                              assumptions=1, family="object-transform"))
    # Learn a global object-property -> output-color map from demonstrations.
    for feature in ("size", "shape", "orientation", "symmetry", "dimensions"):
        mapping = {}
        consistent = True
        for source, target in pairs:
            if dimensions(source) != dimensions(target):
                consistent = False
                break
            for obj in extract_objects(source):
                colors_at_object = {target[r][c] for r, c in obj.cells}
                if len(colors_at_object) != 1:
                    consistent = False
                    break
                key = object_feature(obj, feature)
                color = next(iter(colors_at_object))
                if key in mapping and mapping[key] != color:
                    consistent = False
                    break
                mapping[key] = color
            if not consistent:
                break
        if consistent and mapping:
            transform = lambda g, mapping=mapping, feature=feature: \
                recolor_objects_by_feature(g, mapping, feature)
            if _fits(transform, pairs):
                rules.append(Rule(f"recolor-objects-by-{feature}", transform, 4,
                                  assumptions=1, family="object-recolor"))
    for direction in ("up", "down", "left", "right"):
        transform = lambda g, direction=direction: gravity(g, direction)
        if _fits(transform, pairs):
            rules.append(Rule(f"gravity-{direction}", transform, 4,
                              assumptions=1, family="object-movement"))
    correspondence = _object_correspondence_rule(pairs)
    if correspondence:
        rules.append(correspondence)
    from .relations import generate_relation_copy_hypotheses
    rules.extend(generate_relation_copy_hypotheses(pairs))
    for color_policy in ("same", "first", "second"):
        transform = lambda g, color_policy=color_policy: \
            connect_aligned_objects(g, color_policy)
        if _fits(transform, pairs):
            rules.append(Rule(f"connect-aligned({color_policy})", transform, 5,
                              assumptions=2, family="object-relations"))
    if any(source != target for source, target in pairs):
        for route in ("horizontal-first", "vertical-first"):
            for color_policy in ("same", "first", "second"):
                transform = lambda g, route=route, color_policy=color_policy: \
                    connect_nearest_objects(g, route, color_policy)
                if _fits(transform, pairs):
                    rules.append(Rule(
                        f"connect-nearest({route},{color_policy})", transform, 7,
                        assumptions=3, family="object-relations"))
    for axis in ("horizontal", "vertical"):
        for operation in ("union", "intersection", "xor",
                          "subtract-left", "subtract-right"):
            def combine_halves(grid: Grid, axis=axis, operation=operation) -> Grid:
                regions = split_on_separator(grid, axis)
                if len(regions) != 2:
                    raise ValueError("expected exactly two regions around a separator")
                return combine_regions(regions[0], regions[1], operation)
            if _fits(combine_halves, pairs):
                rules.append(Rule(f"split-{axis}-{operation}", combine_halves, 4,
                                  assumptions=2, family="region-combination"))
    for name, transform, complexity in geometries[1:]:
        mapped = _mapping_rule(pairs, transform,
                               f"{name}+color-map", complexity + 2)
        if mapped:
            rules.append(mapped)
    for name, transform, complexity in geometries:
        for measure in ("cells", "objects"):
            role_rule = _palette_rank_rule(
                pairs, measure, transform,
                f"{name}+palette-role-{measure}")
            if role_rule:
                rules.append(role_rule)
    for direction in ("up", "down", "left", "right"):
        transform = lambda g, direction=direction: gravity(g, direction)
        mapped = _mapping_rule(pairs, transform,
                               f"gravity-{direction}+color-map", 6)
        if mapped:
            rules.append(mapped)

    # Retain one color at a time; crop its symbolic object region as a second
    # hypothesis. These parameters come from visible training colors only.
    input_colors = sorted({value for source, _ in pairs
                           for row in source for value in row if value != 0})
    for color in input_colors:
        keep = lambda grid, color=color: tuple(
            tuple(value if value == color else 0 for value in row) for row in grid)
        for suffix, transform, complexity in (
                ("keep-color", keep, 2),
                ("crop-color", lambda g, keep=keep: crop_non_background(keep(g)), 3)):
            if _fits(transform, pairs):
                rules.append(Rule(f"{suffix}({color})", transform, complexity,
                                  assumptions=1, family="object-selection"))
            mapped = _mapping_rule(pairs, transform,
                                   f"{suffix}({color})+color-map", complexity + 2)
            if mapped:
                rules.append(mapped)

    # Shallow compositions cover common "select/crop, then transform" rules.
    # Only two operations are composed; all parameters are fixed by the DSL.
    simple_ops: list[tuple[str, Transform, int]] = [
        item for item in geometries if item[0] != "identity"
    ]
    for color in input_colors:
        simple_ops.append((f"keep-color({color})",
                           lambda g, color=color: tuple(
                               tuple(v if v == color else 0 for v in row) for row in g), 2))
        simple_ops.append((f"crop-color({color})",
                           lambda g, color=color: crop_color(g, color), 3))
        simple_ops.append((f"fill-holes({color})",
                           lambda g, color=color: fill_enclosed_background(g, color), 3))
    for selector in selectors:
        simple_ops.append((f"select-objects({selector})",
                           lambda g, selector=selector: select_objects(g, selector), 3))
    for operation in ("reflect-horizontal", "reflect-vertical", "rotate-90",
                      "rotate-180", "rotate-270"):
        simple_ops.append((f"transform-each-object({operation})",
                           lambda g, operation=operation:
                           transform_each_object(g, operation), 4))
    simple_ops.append(("fill-holes-majority", fill_enclosed_background, 3))
    # Avoid the Cartesian product of unrelated selectors; geometric stages
    # may be composed with one selection/cropping/filling stage in either order.
    geometric = [item for item in geometries
                 if item[0].startswith(("reflect", "rotate", "crop-non-background"))]
    structural = [item for item in simple_ops
                  if item[0].startswith(("keep-color", "crop-color", "fill-holes",
                                         "select-objects", "transform-each-object"))]
    for geom_name, geom, geom_cost in geometric:
        for struct_name, struct, struct_cost in structural:
            for order, first, second in (("then", geom, struct),
                                         ("then", struct, geom)):
                transform = lambda grid, first=first, second=second: second(first(grid))
                name = f"{geom_name}+{struct_name}" if first is geom else f"{struct_name}+{geom_name}"
                if _fits(transform, pairs):
                    rules.append(Rule(name, transform, geom_cost + struct_cost,
                                      assumptions=2, family="composition"))

    # Fixed-offset translation rules are removed. Relation-conditioned
    # copy/place (generated via generate_relation_copy_hypotheses) is the
    # only object-copy mechanism. Constant (dy, dx) hypotheses do not
    # generalize when landmarks move.

    first_in, first_out = pairs[0]
    h0, w0 = dimensions(first_in)
    h1, w1 = dimensions(first_out)
    if h1 % h0 == 0 and w1 % w0 == 0:
        sy, sx = h1 // h0, w1 // w0
        if (sy > 1 or sx > 1) and all(
                scale(source, sy, sx) == target for source, target in pairs
                if dimensions(target) == (dimensions(source)[0] * sy,
                                          dimensions(source)[1] * sx)) and all(
                dimensions(target) == (dimensions(source)[0] * sy,
                                       dimensions(source)[1] * sx)
                for source, target in pairs):
            rules.append(Rule(f"scale({sy},{sx})",
                              lambda g, sy=sy, sx=sx: scale(g, sy, sx),
                              2 + sy + sx, assumptions=1, family="scaling"))
            scaled = lambda g, sy=sy, sx=sx: scale(g, sy, sx)
            mapped = _mapping_rule(pairs, scaled, f"scale({sy},{sx})+color-map",
                                   4 + sy + sx)
            if mapped:
                rules.append(mapped)

    if h1 % h0 == 0 and w1 % w0 == 0:
        ny, nx = h1 // h0, w1 // w0
        if (ny > 1 or nx > 1) and all(
                dimensions(target) == (dimensions(source)[0] * ny,
                                       dimensions(source)[1] * nx)
                and tile(source, ny, nx) == target for source, target in pairs):
            rules.append(Rule(f"tile({ny},{nx})", lambda g, ny=ny, nx=nx: tile(g, ny, nx),
                              3 + ny + nx, assumptions=1, family="tiling"))
            tiled = lambda g, ny=ny, nx=nx: tile(g, ny, nx)
            mapped = _mapping_rule(pairs, tiled, f"tile({ny},{nx})+color-map",
                                   5 + ny + nx)
            if mapped:
                rules.append(mapped)

    mapping = _mapping_rule(pairs, lambda g: g, "global-color-map")
    if mapping:
        rules.append(mapping)

    # Per-color constant translations removed. Relation-conditioned
    # copy/place handles object movement relative to landmarks.
    for radius in (1, 2):
        local_rule = _local_rewrite_rule(pairs, radius)
        if local_rule:
            rules.append(local_rule)
    rules.extend(_count_rules(pairs))
    direct_exact = any(_fits(rule.apply, pairs) for rule in rules)
    search_stats = {"triggered": False,
                    "reason": "direct_exact_hypothesis_exists" if direct_exact
                    else "no_direct_exact_hypothesis"}
    if not direct_exact:
        from .program_search import discover_compositions
        composed, search_stats = discover_compositions(pairs)
        rules.extend(composed)
    return (rules, search_stats) if return_search_stats else rules

from __future__ import annotations
"""
--------------------------------------------
HERCULE AI Operating System
Module: Autonomy Worker (Stage 10)
Author: Heeran Paul
License: MIT
--------------------------------------------

One controlled background worker over EXISTING systems only:

* kernel.Scheduler (threads) — reused, max_workers=1
* cognition.TaskManager (queue, lifecycle, persistence) — reused
* Brain.run_cycle (plan/policy/execution/verification/memory) — reused
* existing tracer — reused for autonomy events

The worker NEVER executes tools, resolves capabilities, or bypasses
policy itself: every task runs through ``Brain.run_cycle``, which
enforces permissions, capability validation, verification, budgets,
and high-risk authorization exactly as in interactive mode.

Safety properties:

* opt-in only (disabled by default — no always-on behavior)
* max 1 concurrent task; stoppable; pause stops new pickups
* only tasks flagged autonomous are picked up (interactive CLI tasks
  are never double-executed)
* retries flow through TaskManager.retry() (bounded by max_retries)
* per-run wall-clock is bounded by the loop's own time budget;
  overruns are recorded honestly, never hidden
* recurring schedules spawn child tasks (terminal states are never
  mutated — no state corruption)
* restart recovery requeues interrupted tasks via retry(); verified
  steps are never replayed (run_cycle resume machinery owns that)
"""

import logging
import threading
import time
from datetime import datetime, timezone
from typing import Any, Callable, Dict, List, Optional

from autonomy.levels import LEVEL_NAMES, evaluate_gate, normalize_level

logger = logging.getLogger("HERCULE.Autonomy")

TERMINAL_STATES = {"COMPLETED", "FAILED", "CANCELLED"}
ELIGIBLE_STATES = {"QUEUED", "RETRYING"}


def _utcnow() -> str:
    return datetime.now(timezone.utc).isoformat()


def _utcnow_ts() -> float:
    return datetime.now(timezone.utc).timestamp()


class AutonomyWorker:
    """Single-threaded background executor for scheduled task queue."""

    def __init__(self, services: Dict[str, Any], scheduler=None,
                 config: Optional[Dict[str, Any]] = None):
        from kernel.scheduler import Scheduler

        self.services = services
        self.brain = services["brain"]
        orchestrator = services.get("orchestrator")
        self.tasks = getattr(orchestrator, "task_manager", None)
        if self.tasks is None:
            raise RuntimeError("AutonomyWorker requires orchestrator.task_manager")
        self.scheduler = scheduler or Scheduler(max_workers=1)
        self._owns_scheduler = scheduler is None
        config = dict(config or {})
        from system.config.runtime_config import load_runtime_config
        env = load_runtime_config()
        self.enabled: bool = bool(config.get("enabled", env.autonomy_enabled))
        self.poll_interval_s: float = float(config.get("poll_interval_s", env.autonomy_poll_interval_s))
        self.max_task_runtime_s: float = float(config.get("max_task_runtime_s", env.autonomy_max_task_runtime_s))
        self.max_concurrent_tasks: int = int(config.get("max_concurrent_tasks", env.autonomy_max_concurrent_tasks))
        self.autonomy_level: int = normalize_level(config.get("autonomy_level", env.autonomy_level))
        self._stop_event = threading.Event()
        self._paused = False
        self._lock = threading.Lock()
        self._future = None
        self._worker_state = "STOPPED"
        self._active_task_id: Optional[str] = None
        self._last_result: Optional[Dict[str, Any]] = None
        self._started_count = 0
        self._completed_count = 0
        self._failed_count = 0

    # --------------------------------------------------
    # Tracing (existing tracer; best-effort, never fatal)
    # --------------------------------------------------
    def _trace(self, stage: str, data: Optional[Dict[str, Any]] = None) -> None:
        try:
            tracer = getattr(self.brain, "_tracer", None)
            if tracer is not None and hasattr(tracer, "record"):
                tracer.record(f"autonomy-{id(self):x}", stage, data or {})
        except Exception:
            pass
        try:
            logger.info("AUTONOMY %s %s", stage,
                        " ".join(f"{k}={v}" for k, v in (data or {}).items()))
        except Exception:
            pass

    # --------------------------------------------------
    # Scheduling (run once / delayed / recurring)
    # --------------------------------------------------
    def schedule(self, goal: str, delay_s: float = 0.0,
                 interval_s: Optional[float] = None,
                 priority: int = 5, timeout: int = 60,
                 max_retries: int = 2,
                 metadata: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        """Queue an autonomous task. Returns {task_id, duplicate, ...}."""
        cleaned = str(goal or "").strip()
        if not cleaned:
            raise ValueError("cannot schedule an empty goal")
        if delay_s is None or float(delay_s) < 0:
            raise ValueError("delay_s must be >= 0")
        if interval_s is not None and float(interval_s) <= 0:
            raise ValueError("interval_s must be > 0 for recurring tasks")
        # Autonomy-level gate (UAI §27): deterministic risk-vs-level check
        # before anything is queued. PolicyManager still evaluates every
        # execution downstream; this only gates scheduling.
        gate = evaluate_gate(self.autonomy_level, cleaned)
        if not gate["allowed"]:
            self._trace("SCHEDULE_DENIED", {"goal": cleaned[:120], "level": self.autonomy_level,
                                            "risk": gate["risk"], "reason": gate["reason"]})
            raise PermissionError(gate["reason"])
        now_ts = _utcnow_ts()
        run_at = now_ts + float(delay_s or 0.0)
        schedule = {
            "run_at": datetime.fromtimestamp(run_at, tz=timezone.utc).isoformat(),
            "interval_s": float(interval_s) if interval_s else None,
            "recurring": bool(interval_s),
            "next_run_at": datetime.fromtimestamp(run_at, tz=timezone.utc).isoformat(),
            "occurrences": 0,
        }
        # Duplicate prevention: same goal + same schedule shape already
        # active (non-terminal) -> return the existing task honestly.
        # run_at compares with tolerance (scheduling twice in a row is
        # the same intent, not two intents).
        for task in self._autonomous_tasks():
            status = str(task.get("status", "")).upper()
            if status in TERMINAL_STATES:
                continue
            meta = task.get("metadata", {}) or {}
            existing = meta.get("schedule", {}) or {}
            if (str(task.get("goal", "")) != cleaned
                    or bool(existing.get("recurring")) != bool(interval_s)
                    or str(existing.get("interval_s") or "") != str(schedule["interval_s"] or "")):
                continue
            try:
                old_ts = datetime.fromisoformat(str(existing.get("next_run_at", ""))).timestamp()
                if abs(old_ts - run_at) > 120:
                    continue
            except Exception:
                pass
            return {"task_id": str(task.get("id")), "duplicate": True,
                    "status": status}
        merged = dict(metadata or {})
        merged.update({"autonomous": True, "schedule": schedule, "goal": cleaned})
        task_id = self.tasks.create_task(
            cleaned, timeout=int(timeout), metadata=merged,
            priority=int(priority))
        task = self.tasks.get(task_id)
        task["max_retries"] = int(max_retries)
        self.tasks.queue_task(task_id)
        self._trace("TASK_QUEUED", {"task_id": task_id, "goal": cleaned[:120],
                                   "run_at": schedule["run_at"],
                                   "recurring": schedule["recurring"]})
        try:
            self.tasks.save()
        except Exception:
            pass
        return {"task_id": task_id, "duplicate": False,
                "status": "QUEUED", "run_at": schedule["run_at"]}

    def _autonomous_tasks(self) -> List[Dict[str, Any]]:
        try:
            return [t for t in self.tasks
                    if isinstance(t, dict) and (t.get("metadata", {}) or {}).get("autonomous")]
        except Exception:
            return []

    def _due_tasks(self) -> List[Dict[str, Any]]:
        now = _utcnow()
        due = []
        for task in self._autonomous_tasks():
            if str(task.get("status", "")).upper() not in ELIGIBLE_STATES:
                continue
            sched = (task.get("metadata", {}) or {}).get("schedule", {}) or {}
            if str(sched.get("next_run_at", "")) <= now:
                due.append(task)
        due.sort(key=lambda t: (int(t.get("priority", 5)),
                                str(t.get("created_at", ""))))
        return due

    # --------------------------------------------------
    # Lifecycle: start / stop / pause / resume
    # --------------------------------------------------
    def start(self, recover: bool = True) -> Dict[str, Any]:
        """Start the background loop (opt-in). Runs recovery first.

        Levels 0 (conversation only) and 1 (suggest only) never execute,
        so start() is refused for those levels --- the worker remains a
        no-op and the caller should lower the request or run interactally.
        """
        if self.autonomy_level <= 1:
            return {"started": False,
                    "reason": (f"autonomy level {self.autonomy_level} "
                               f"({LEVEL_NAMES[self.autonomy_level]}) does not permit execution")}
        with self._lock:
            if self._future is not None and not self._future.done():
                return {"state": self._worker_state, "already_running": True}
            self._stop_event.clear()
            self._paused = False
            self._worker_state = "IDLE"
        recovered: Dict[str, Any] = {}
        if recover:
            recovered = self.recover_on_startup()
        try:
            self.brain.consciousness.set_state("AUTONOMOUS", "autonomy worker started")
        except Exception:
            pass
        self._trace("AUTONOMY_START", {"recovered": recovered})
        try:
            bus = getattr(self.brain, "event_bus", None)
            if bus is not None:
                bus.publish("AUTONOMY_STARTED", level=self.autonomy_level)
        except Exception:
            pass
        self._future = self.scheduler.submit(self._loop)
        return {"state": "IDLE", "recovered": recovered}

    def stop(self, wait: bool = True, timeout: float = 30.0) -> Dict[str, Any]:
        """Stop cleanly: no new pickups; persist state; shut down threads."""
        self._stop_event.set()
        future, scheduler = self._future, self.scheduler
        if future is not None and wait:
            try:
                future.result(timeout=timeout)
            except Exception as exc:
                logger.warning("autonomy worker stop waited: %s", exc)
        if self._owns_scheduler:
            try:
                scheduler.shutdown(wait=wait)
            except Exception as exc:
                logger.warning("autonomy scheduler shutdown: %s", exc)
        try:
            self.tasks.save()
        except Exception as exc:
            logger.warning("autonomy task persist on shutdown: %s", exc)
        with self._lock:
            self._worker_state = "STOPPED"
        try:
            self.brain.consciousness.set_state("IDLE", "autonomy worker stopped")
        except Exception:
            pass
        self._trace("AUTONOMY_STOP", {"active_task": self._active_task_id or ""})
        try:
            bus = getattr(self.brain, "event_bus", None)
            if bus is not None:
                bus.publish("AUTONOMY_STOPPED", level=self.autonomy_level)
        except Exception:
            pass
        return {"state": "STOPPED"}

    def pause(self) -> Dict[str, Any]:
        """Stop picking up new tasks (a running task finishes honestly)."""
        with self._lock:
            self._paused = True
            if self._worker_state != "STOPPED":
                self._worker_state = "PAUSED"
        try:
            self.brain.consciousness.set_state("WAITING", "autonomy paused")
        except Exception:
            pass
        return {"state": self._worker_state}

    def resume(self) -> Dict[str, Any]:
        with self._lock:
            if self._worker_state == "STOPPED":
                raise RuntimeError("autonomy worker is stopped; start it first")
            self._paused = False
            self._worker_state = "IDLE"
        try:
            self.brain.consciousness.set_state("AUTONOMOUS", "autonomy resumed")
        except Exception:
            pass
        return {"state": self._worker_state}

    @property
    def worker_state(self) -> str:
        return self._worker_state

    # --------------------------------------------------
    # Restart recovery (load, verify, resume safely)
    # --------------------------------------------------
    def recover_on_startup(self) -> Dict[str, Any]:
        """Reconcile persisted autonomous tasks after a restart.

        Stale RUNNING/RECOVERING -> retry() (keeps checkpoints; verified
        steps are never replayed by run_cycle's resume machinery).
        Stale RETRYING stays eligible as-is. PAUSED/WAITING/QUEUED and
        FAILED-with-budget are left for normal pickup. Terminal tasks
        are never mutated. Returns an honest summary.
        """
        summary: Dict[str, Any] = {"resumed": [], "left_paused": [],
                                   "left_queued": [], "failed_now": []}
        try:
            self.tasks.load()
        except Exception as exc:
            logger.warning("autonomy recovery load: %s", exc)
        for task in self._autonomous_tasks():
            task_id = str(task.get("id"))
            status = str(task.get("status", "")).upper()
            try:
                if status in ("RUNNING", "RECOVERING"):
                    self.tasks.retry(task_id, reason="interrupted by restart; safe resume")
                    summary["resumed"].append(task_id)
                    self._trace("TASK_QUEUED", {"task_id": task_id,
                                               "reason": "restart-recovery"})
                elif status == "PAUSED":
                    summary["left_paused"].append(task_id)
                elif status in ("QUEUED", "WAITING", "RETRYING"):
                    summary["left_queued"].append(task_id)
                elif status == "FAILED":
                    if int(task.get("retry_count", 0) or 0) < int(task.get("max_retries", 2)):
                        self.tasks.retry(task_id, reason="restart recovery; retries remain")
                        summary["resumed"].append(task_id)
            except Exception as exc:
                summary["failed_now"].append({"task_id": task_id, "error": str(exc)[:160]})
        try:
            self.tasks.save()
        except Exception:
            pass
        return summary

    # --------------------------------------------------
    # Main loop (single task at a time)
    # --------------------------------------------------
    def _loop(self) -> None:
        while not self._stop_event.is_set():
            try:
                if self._paused:
                    with self._lock:
                        if self._worker_state != "STOPPED":
                            self._worker_state = "PAUSED"
                    self._stop_event.wait(self.poll_interval_s)
                    continue
                with self._lock:
                    if self._worker_state != "STOPPED":
                        self._worker_state = "IDLE"
                due = self._due_tasks()
                if not due:
                    with self._lock:
                        if self._worker_state != "STOPPED":
                            self._worker_state = "WAITING"
                    try:
                        self.brain.consciousness.set_state("WAITING", "autonomy idle; queue empty")
                    except Exception:
                        pass
                    self._stop_event.wait(self.poll_interval_s)
                    continue
                self._execute_one(due[0])
            except Exception as exc:
                logger.error("autonomy worker loop error: %s", exc)
                self._stop_event.wait(self.poll_interval_s)

    def _execute_one(self, task: Dict[str, Any]) -> None:
        task_id = str(task.get("id"))
        goal = str(task.get("goal", task.get("description", "")))
        with self._lock:
            self._worker_state = "RUNNING"
            self._active_task_id = task_id
        try:
            self.brain.consciousness.set_state("AUTONOMOUS", f"executing:{task_id}")
        except Exception:
            pass
        # Eligible RETRYING tasks enter RUNNING directly; QUEUED via start()
        # (validates dependencies — unmet deps park the task honestly).
        try:
            current = str(self.tasks.get(task_id).get("status", "")).upper()
            if current == "RETRYING":
                self.tasks.transition(task_id, "RUNNING")
            else:
                self.tasks.start(task_id)
        except Exception as exc:
            self._trace("TASK_FAILED", {"task_id": task_id,
                                       "error": f"start refused: {exc}"[:160]})
            with self._lock:
                self._active_task_id = None
            return
        self._trace("TASK_STARTED", {"task_id": task_id, "goal": goal[:120]})
        started = time.perf_counter()
        try:
            result = self.brain.run_cycle(goal, task_id=task_id)
        except Exception as exc:
            try:
                self.tasks.fail(task_id, str(exc)[:300])
            except Exception:
                pass
            result = {"status": "failed", "error": str(exc)[:300]}
        elapsed = time.perf_counter() - started
        status = str((result or {}).get("status", "failed")).lower()
        over_budget = elapsed > self.max_task_runtime_s
        # Per-step outcomes already recorded by the loop; emit worker-level
        # STEP_* events from durable capability states (never invented).
        self._emit_step_events(task_id)
        if status == "failed":
            try:
                task_now = self.tasks.get(task_id)
                if int(task_now.get("retry_count", 0) or 0) < int(task_now.get("max_retries", 2)):
                    self.tasks.retry(task_id, reason=str((result or {}).get("error", ""))[:200])
                    self._trace("REPLAN", {"task_id": task_id,
                                          "action": "worker-retry-queued"})
                # else: FAILED stands; run_cycle already failed it honestly.
            except Exception as exc:
                logger.warning("autonomy retry bookkeeping: %s", exc)
        if str(self.tasks.get(task_id).get("status", "")).upper() == "COMPLETED":
            self._completed_count += 1
            self._trace("TASK_COMPLETED", {"task_id": task_id,
                                          "elapsed_s": round(elapsed, 1)})
            self._maybe_reschedule(task_id)
        else:
            self._failed_count += 1
            self._trace("TASK_FAILED", {"task_id": task_id,
                                       "status": status,
                                       "elapsed_s": round(elapsed, 1)})
        if over_budget:
            # The outcome stands (it really happened); the overrun is
            # recorded honestly in logs and last_result, and operators
            # can tighten max_task_runtime_s or the loop time budget.
            logger.warning("autonomy task %s overran budget: %.1fs > %.1fs (outcome stands, it was real)",
                           task_id, elapsed, self.max_task_runtime_s)
        # Concise background-task experience is recorded by run_cycle's own
        # memory path; the worker only persists task state.
        try:
            self.tasks.save()
        except Exception:
            pass
        with self._lock:
            self._active_task_id = None
            if self._worker_state != "STOPPED":
                self._worker_state = "IDLE"
        self._last_result = {"task_id": task_id, "status": status,
                             "summary": str((result or {}).get("execution_summary", ""))[:200],
                             "at": _utcnow(), "elapsed_s": round(elapsed, 1),
                             "over_budget": over_budget}

    def _emit_step_events(self, task_id: str) -> None:
        try:
            states = ((self.tasks.get(task_id).get("metadata", {}) or {})
                      .get("capability_states", {}) or {})
            replans = 0
            for step_id in sorted(states):
                state = states[step_id] or {}
                verification = state.get("verification") or {}
                if verification.get("passed"):
                    self._trace("STEP_COMPLETED", {"task_id": task_id, "step_id": step_id})
                elif state.get("status"):
                    self._trace("STEP_FAILED", {"task_id": task_id, "step_id": step_id,
                                               "detail": str(state.get("failure", ""))[:160]})
                if int(state.get("retries", 0) or 0) > 0:
                    replans += 1
            if replans:
                self._trace("REPLAN", {"task_id": task_id, "retried_steps": replans})
        except Exception:
            pass

    def _maybe_reschedule(self, task_id: str) -> None:
        try:
            task = self.tasks.get(task_id)
            sched = (task.get("metadata", {}) or {}).get("schedule", {}) or {}
            if not sched.get("recurring") or not sched.get("interval_s"):
                return
            nxt = _utcnow_ts() + float(sched["interval_s"])
            child_meta = {"autonomous": True, "goal": str(task.get("goal", "")),
                          "schedule": {**sched,
                                       "next_run_at": datetime.fromtimestamp(
                                           nxt, tz=timezone.utc).isoformat(),
                                       "occurrences": int(sched.get("occurrences", 0)) + 1}}
            child_id = self.tasks.create_task(
                str(task.get("goal", "")), timeout=int(task.get("timeout", 60)),
                metadata=child_meta, priority=int(task.get("priority", 5)),
                parent_task_id=task_id)
            child = self.tasks.get(child_id)
            child["max_retries"] = int(task.get("max_retries", 2))
            self.tasks.queue_task(child_id)
            self._trace("TASK_QUEUED", {"task_id": child_id, "recurring_child_of": task_id,
                                       "next_run_at": child_meta["schedule"]["next_run_at"]})
        except Exception as exc:
            logger.warning("autonomy reschedule: %s", exc)

    # --------------------------------------------------
    # Status snapshot for UI (UNKNOWN, never fabricated)
    # --------------------------------------------------
    def status(self) -> Dict[str, Any]:
        try:
            queued = [str(t.get("id")) for t in self._due_tasks()]
            all_auto = self._autonomous_tasks()
            counts: Dict[str, int] = {}
            for task in all_auto:
                key = str(task.get("status", "UNKNOWN")).upper()
                counts[key] = counts.get(key, 0) + 1
            return {
                "enabled": self.enabled,
                "worker_state": self._worker_state,
                "max_concurrent_tasks": self.max_concurrent_tasks,
                "max_task_runtime_s": self.max_task_runtime_s,
                "queued": queued,
                "active_task": self._active_task_id or "",
                "last_result": dict(self._last_result or {}),
                "counts": counts,
                "started": self._started_count,
                "completed": self._completed_count,
                "failed": self._failed_count,
            }
        except Exception as exc:
            return {"enabled": self.enabled, "worker_state": "UNKNOWN",
                    "error": str(exc)[:160]}

    def set_enabled(self, enabled: bool) -> Dict[str, Any]:
        self.enabled = bool(enabled)
        return {"enabled": self.enabled}

